// Riot's official vi_VN text, saved 2026-10-20 from Data Dragon 16.20.1 championFull.json: full biography and the 5 ability descriptions (passive, Q, W, E, R).
window.ATLAS_I18N_FULL={"aatrox":["Từng là những người bảo hộ cao quý của Shurima để chống lại Hư Không, Aatrox cùng đồng bọn cuối cùng lại trở thành một mối hiểm họa còn lớn hơn đối với cả Runeterra, và chỉ bị đánh bại bằng món phép thuật khôn ngoan của nhân loại. Nhưng sau nhiều thế kỉ bị giam cầm, Aatrox là kẻ đầu tiên một lần nữa tìm về với tự do, bằng cách vấy bẩn và biến đổi những kẻ ngu ngốc dám cầm thử thứ vũ khí ma thuật chứa đựng linh hồn hắn. Giờ đây, với da thịt chiếm đoạt được, hắn quay trở lại Runeterra trong một hình hài khủng khiếp tương tự trước đây, tìm kiếm sự tàn sát và trả món hận thù năm xưa.",["Thường kỳ, đòn đánh kế tiếp của Aatrox sẽ gây thêm sát thương phép và hồi máu, dựa trên máu tối đa của mục tiêu.","Aatrox đập kiếm xuống đất, gây sát thương vật lý. Có thể chém ba lần, mỗi lần có một diện tác dụng khác nhau.","Aatrox đập kiếm xuống đất, gây sát thương lên kẻ địch đầu tiên trúng phải. Tướng và quái to phải nhanh rời vùng tác động nếu không muốn bị kéo về tâm và chịu sát thương lần nữa.","Nội tại giúp Aatrox hồi máu khi gây sát thương lên tướng. Kích hoạt giúp Aatrox lướt theo hướng chỉ định.","Aatrox hóa quỷ, làm hoảng sợ lính địch gần đó và được cộng SMCK, tăng hồi máu cũng như Tốc độ Di chuyển. Nếu hắn tham gia hạ gục, hiệu ứng này được kéo dài."]],"ahri":["Sinh ra với kết nối ma thuật cõi linh giới, Ahri là một vastaya cáo tinh với khả năng thao túng cảm xúc của con mồi và hấp thụ tinh hoa từ chúng—nhận được một phần ký ức và trí tuệ từ mỗi linh hồn mà cô nàng hấp thụ. Từng là một kẻ săn mồi mạnh mẽ và bướng bỉnh, giờ đây Ahri ngao du khắp thế giới để tìm kiếm manh mối về tổ tiên của mình cũng như thay thế những ký ức bị đánh cắp bởi chính ký ức của bản thân cô.",["Sau khi hạ 9 lính hoặc quái, Ahri sẽ được hồi máu.\nKhi tham gia hạ gục tướng, Ahri sẽ được hồi máu nhiều hơn.","Ahri phóng ra và thu lại quả cầu ma thuật của mình, gây sát thương phép trên đường phóng đi và sát thương chuẩn trên đường thu về.","Ahri nhận thêm Tốc độ Di chuyển và triệu hồi ra ba ngọn lửa hồ ly, tự động khóa mục tiêu và tấn công những kẻ địch ở gần.","Ahri hôn gió, gây sát thương và mê hoặc kẻ địch đầu tiên trúng chiêu, ngay lập tức ngắt quãng kỹ năng di chuyển và khiến chúng bước về phía cô một cách vô hại.","Ahri lướt đi và bắn ra những tia sét linh hồn, gây sát thương lên kẻ địch xung quanh. Phi Hồ có thể được sử dụng tối đa ba lần trước khi hồi chiêu, và nhận được thêm một lần tái sử dụng với mỗi mạng tham gia hạ gục tướng địch."]],"akali":["Rời khỏi Hội Kinkou, từ bỏ danh hiệu Nắm Đấm Bóng Đêm, Akali giờ trở thành thứ vũ khí giết chóc hành động một mình mà người dân cần. Dù vẫn khắc ghi những gì học được từ Shen, cô đã thế sẽ tiêu diệt mọi kẻ thù của Ionia, từng mạng từng mạng một. Akali có thể ra tay trong yên lặng, nhưng thông điệp của cô rất rõ ràng: hãy khiếp sợ một sát thủ vô chủ.",["Dùng kỹ năng sát thương tướng địch tạo một vòng năng lượng quanh chúng. Rời khỏi vòng này cường hóa đòn đánh kế tiếp của Akali, giúp tăng tầm và sát thương.","Akali ném ra năm phi đao, gây sát thương dựa trên Sức mạnh Công kích cộng thêm và Sức mạnh Phép thuật của cô, đồng thời làm chậm.","Akali ném bom khói và nhận thêm Tốc độ Di chuyển trong thoáng chốc. Khi đứng trong khói mù, Akali được vô hình và không thể bị chỉ định. Tấn công hoặc dùng kỹ năng thoáng làm cô lộ diện.","Akali nhảy lùi lại và phóng phi tiêu ra trước mặt, gây sát thương phép. Kẻ địch đầu tiên hoặc khói mù trúng phải bị đánh dấu. Tái kích hoạt để lướt tới chỗ mục tiêu bị đánh dấu, gây thêm sát thương.","Akali lướt theo hướng chỉ định, gây sát thương lên kẻ địch trúng chiêu. Tái kích hoạt: Akali lướt theo hướng chỉ định, kết liễu tất cả kẻ địch trúng chiêu."]],"akshan":["Nhướn mày trước hiểm nguy, Akshan chiến đấu với cái ác bằng thần thái rạng ngời cùng ý chí báo thù luôn bừng cháy trong bộ áo sơ mi thiếu vải. Với kỹ năng lén lút vô cùng điêu luyện, anh có thể bất chợt lẩn khuất trước tầm mắt của kẻ thù và đột ngột quay trở lại vào thời khắc chúng ít mong đợi nhất. Cùng niềm tin và nhận thức về công lý, kết hợp với thứ vũ khí có thể đảo ngược sự sống và cái chết trứ danh, anh sửa mọi sai lầm của những kẻ vô lại tại Runeterra theo kim chỉ nam đạo đức của riêng mình: “Đừng là một kẻ khốn nạn.”",["Mỗi ba lần gây sát thương từ Đòn Đánh hoặc Kỹ Năng gây thêm sát thương và cho một Lá Chắn nếu mục tiêu là Tướng.\nKhi Akshan tấn công, gã sẽ bắn ra thêm một Đòn Đánh phụ gây ít sát thương hơn. Nếu hủy đòn đánh phụ, gã được tăng Tốc Độ Di Chuyển.","Akshan ném một boomerang gây sát thương trên đường đi và đường về, tăng tầm mỗi khi nó trúng phải một kẻ địch.","Akshan tự động đánh dấu tướng địch là Kẻ Vô Lại khi chúng hạ gục đồng minh của gã. Nếu Akshan hạ gục một Kẻ Vô Lại, gã hồi sinh cho đồng minh vừa bị giết, nhận thêm vàng, và xóa tất cả đánh dấu còn lại.\nKhi kích hoạt, Akshan tiến vào trạng thái ngụy trang, nhận thêm Tốc Độ Di Chuyển và Hồi Năng Lượng nếu tiến về phía Kẻ Vô Lại. Akshan mất đi khả năng ngụy trang sau một chốc lát nếu không ở trong bụi hoặc gần tường.","Akshan bắn ra một dây móc cài vào một địa hình rồi đu vòng quanh nó, liên tục xả đạn vào kẻ địch gần nhất trong khi đu dây. Gã có thể nhảy xuống sớm hoặc bị văng ra nếu va chạm với tướng hoặc địa hình.","Akshan khóa mục tiêu vào một tướng địch và bắt đầu tích trữ đạn. Khi kết thúc vận sức, gã khai hỏa tất cả những phát đạn đã tích trữ, gây sát thương dựa trên máu đã mất lên tướng, lính, hoặc trụ đầu tiên mà nó trúng phải."]],"alistar":["Nổi danh là một chiến binh đáng sợ với ý chí kiên cường, Alistar luôn tìm cách để báo thù cho cái chết của bộ tộc dưới tay đế quốc Noxus. Dù bị bắt làm nô lệ và ép phải trở thành đấu sĩ, ý chí bất khuất là thứ đã giữ anh tránh khỏi biến thành một ác thú thực thụ. Giờ đây, khi đã được giải thoát khỏi xiềng xích, anh trỗi dậy, dùng cơn cuồng nộ đáng sợ không kém gì cặp sừng, móng guốc, hay nắm đấm làm vũ khí và chiến đấu nhân danh những người bị áp bức lầm than.",["Alistar cộng dồn tiếng gầm bằng cách làm choáng hoặc đẩy lùi tướng địch hoặc khi có kẻ địch gần đó chết. Khi nạp đầy cộng dồn, hắn hồi máu cho mình và tất cả tướng đồng minh gần đó.","Alistar dộng xuống đất, gây sát thương lên kẻ địch gần đó và hất chúng lên không.","Alistar húc mục tiêu, gây sát thương và hất văng nạn nhân đi.","Alistar giày xéo các đơn vị địch gần đó, đi xuyên vật thể và nhận một cộng dồn nếu gây sát thương tướng địch. Khi nạp đầy cộng dồn, đòn đánh tiếp theo của Alistar lên tướng địch gây thêm sát thương phép và làm choáng chúng.","Alistar gầm lên một tiếng, loại bỏ mọi trạng thái khống chế, và giảm sát thương vật lý và phép gánh chịu trong thời gian tác dụng."]],"ambessa":["Tất cả những ai biết cái tên Medarda đều tôn trọng và sợ hãi thủ lĩnh của gia tộc, Ambessa. Là một tướng quân Noxus, bà là hiện thân của sự kết hợp chết người giữa sức mạnh tàn nhẫn và ý chí bất khuất trong chiến đấu. Vai trò nữ trưởng gia tộc của bà cũng vậy, đòi hỏi sự xảo quyệt hơn người để phát triển gia tộc Medarda và không chừa chỗ cho thất bại hay lòng trắc ẩn. Vận dụng phương châm tàn nhẫn từ loài sói, Ambessa sẽ làm bất cứ điều gì cần thiết để bảo vệ di sản của gia tộc mình, ngay cả khi phải đánh đổi tình yêu từ những đứa con của bà.",["Nhập một lệnh tung đòn đánh hoặc di chuyển khi thi triển kỹ năng sẽ khiến Ambessa lướt đi một khoảng ngắn khi kỹ năng tung ra, ban cho đòn đánh kế tiếp của bà thêm tầm đánh, sát thương, và tốc độ đánh, đồng thời hồi lại nội năng.","Ambessa quét đao xích của bà theo hình bán nguyệt trước mặt, gây sát thương cộng thêm lên những kẻ địch trúng lưỡi đao. Đánh trúng một kẻ địch sẽ biến đổi lần thi triển tiếp theo của kỹ năng này trong thoáng chốc, khiến bà dậm mạnh đao xích theo đường thẳng trước mặt, gây sát thương cộng thêm lên kẻ địch đầu tiên trúng chiêu.","Ambessa nhận một lá chắn, gồng mình trong thoáng chốc, sau đó dậm mạnh xuống mặt đất gây sát thương lên kẻ địch xung quanh. Nếu bà chặn được sát thương từ kẻ địch (trừ lính địch) khi đang gồng, kỹ năng này sẽ gây thêm sát thương.","Ambessa quất đao xích của bà ra xung quanh, gây sát thương và làm chậm kẻ địch trúng chiêu. Kích hoạt Bước Chân Long Khuyển từ kỹ năng này sẽ khiến bà tung đòn đánh lần thứ hai tại điểm đến của cú lướt.","Ambessa dịch chuyển đến tướng địch ở xa nhất trên một đường thẳng và áp chế chúng khi đến đích. Sau đó bà quật kẻ địch xuống đất, khiến chúng chịu sát thương và làm choáng."]],"amumu":["Truyền thuyết kể rằng Amumu là một linh hồn đơn độc và u sầu xuất hiện từ Shurima cổ đại, cậu cứ mãi lang thang khắp thế gian tìm kiếm cho mình một người bạn. Lời nguyền từ thuở xa xưa đã khiến cậu phải sống cô độc suốt đời, bởi ai bị cậu chạm vào đều sẽ biến mất khỏi cuộc sống này vĩnh viễn. Những người từng thấy Amumu miêu tả cậu là một xác chết biết đi có vóc dáng nhỏ bé và quấn đầy băng vải. Amumu là nguồn cảm hứng viết nên những câu chuyện thần thoại, là nhân vật trong các bài hát và truyện kể dân gian được kể đi kể lại qua nhiều thế hệ đến nỗi chẳng ai có thể phân biệt đâu là sự thật và đâu là tưởng tượng được nữa.",["Đòn đánh của Amumu Nguyền Rủa kẻ địch, khiến chúng chịu thêm sát thương chuẩn khi trúng sát thương phép.","Amumu quăng một dải băng dính vào mục tiêu, làm choáng rồi kéo hắn lại bên cạnh nạn nhân.","Đau đớn tột cùng, kẻ địch xung quanh mất một số phần trăm Máu tối đa của chúng mỗi giây và bị làm mới Nguyền Rủa trên người.","Vĩnh viễn giảm lượng sát thương vật lý mà Amumu gánh chịu. Amumu có thể phóng thích cơn giận, gây sát thương lên kẻ địch xung quanh. Mỗi khi Amumu bị đánh trúng, hồi chiêu của Giận Dữ được giảm đi.","Amumu trói những đơn vị địch xung quanh với băng gạc của mình, đặt hiệu ứng Nguyền Rủa, gây sát thương và làm choáng chúng."]],"anivia":["Anivia là một á thần Freljord nhân từ cổ đại với sứ mệnh vĩnh hằng là bảo vệ vùng Freljord cho dù là sống, chết hay trải qua sự tái sinh. Là á thần được sinh ra dưới lớp băng vĩnh cửu cùng những cơn gió lạnh thấu xương, cô sử dụng những quyền năng mà mình có để đẩy lùi bất kỳ những kẻ ngoại đạo dám đặt chân tới quấy nhiễu vùng đất quê hương. Những người được Anivia dẫn dắt và bảo vệ tại các bộ tộc nơi phương Bắc khắc nghiệt coi cô là biểu tượng của hy vọng, cũng như là điềm báo cho một sự thay đổi lớn. Cô chiến đấu bằng tất cả sức mình và hiểu rõ ràng nhờ sự hy sinh của bản thân, ký ức về cô sẽ mãi trường tồn và cô sẽ tái sinh trong một ngày mai mới.",["Sau khi bị hạ gục, Anivia hóa thành một quả trứng và hồi lại đầy bình máu.","Anivia chập cánh lại và gọi ra một quả cầu băng bay về kẻ địch, gây trạng thái hạ nhiệt và sát thương bất cứ ai trên đường bay của nó. Khi quả cầu phát nổ, nó gây sát thương tầm trung trong bán kính, làm choáng bất cứ ai trong vòng ảnh hưởng.","Anivia ngưng đọng độ ẩm trong không khí thành một bức tường băng vững chắc chặn đường quân địch. Bức tường sẽ tồn tại trong một thời gian ngắn trước khi tan chảy.","Anivia đập cánh, tạt một luồng gió buốt giá vào mục tiêu, gây sát thương. Nếu mục tiêu vừa bị trúng Quả Cầu Băng hoặc bị dính Bão Tuyết toàn phần, sát thương sẽ nhân đôi.","Anivia gọi xuống một cơn mưa băng sát thương kẻ địch và làm chậm chúng."]],"annie":["Nguy hiểm nhưng không kém phần đáng yêu, Annie là một pháp sư nhí có khả năng điều khiển lửa. Ngay cả trong vùng núi phía bắc Noxus, cô vẫn là kẻ dị thường. Mối liên kết với lửa sớm thể hiện qua những lần cảm xúc bất chợt bùng nổ, dù cuối cùng cô đã học cách kiểm soát mấy \"trò vui\" này. Sở thích của cô là triệu hồi chú gấu bông yêu quý, Tibbers, làm hộ vệ. Đắm chìm trong sự ngây thơ con trẻ, Annie đi khắp các cánh rừng tối, lúc nào cũng mong tìm một ai để chơi cùng.",["Sau khi dùng kỹ năng 4 lần, kỹ năng công kích tiếp theo của Annie sẽ làm choáng mục tiêu.\nNhận sẵn Hỏa Cuồng khi Annie bắt đầu trận đấu và sau khi hồi sinh.","Annie phóng một quả cầu lửa gây sát thương, và hồi lại năng lượng tổn thất nếu kết liễu được mục tiêu.","Annie chưởng lửa theo hình nón, gây sát thương lên tất cả kẻ địch trong vùng ảnh hưởng.","Tạo cho Annie hoặc một đồng minh lớp lá chắn, gia tăng Tốc Độ Di Chuyển và gây sát thương lên những kẻ địch tấn công cô bé bằng đòn đánh hoặc kỹ năng.","Annie gọi chú gấu Tibbers của mình ra, gây sát thương lên vùng ảnh hưởng. Tibbers có thể đánh và thiêu đốt kẻ địch quanh nó."]],"aphelios":["Lặng lẽ bước ra từ ánh trăng cùng vũ khí trên tay, Aphelios hạ gục những kẻ địch thù ghét đức tin của mình trong yên lặng - thứ duy nhất lên tiếng là sự chắc chắn và chính xác của từng viên đạn. Mặc dù những thứ độc nhất đang chảy trong huyết quản của Aphelios khiến anh ấy câm lặng, chị gái Alune sẽ là người dẫn lối cho anh. Từ điện thờ xa xôi, cô truyền thứ vũ khí làm từ đá mặt trăng vào tay anh. Chừng nào mặt trăng còn tiếp tục soi sáng, Aphelios sẽ chẳng bao giờ đơn độc.",["Aphelios sử dụng 5 Vũ Khí Lunari do người chị Alune tạo ra. Anh có thể dùng hai cái một lúc: một chính và một phụ. Mỗi vũ khí có Đòn đánh và Kỹ năng riêng. Đòn đánh và kỹ năng tiêu hao đạn của vũ khí. Khi hết đạn, Aphelios bỏ vũ khí đó và Alune triệu hồi vũ khí tiếp theo trong số 5 vũ khí.","Aphelios có 5 kỹ năng kích hoạt khác nhau, tùy theo vũ khí chính:\nCalibrum (Súng Thiên Lý): Bắn tầm xa, đánh dấu mục tiêu để có thể bắn thêm một phát từ bất kỳ đâu trên bản đồ.\nSeverum (Súng Huyết Tinh): Chạy thật nhanh và tấn công các kẻ địch xung quanh bằng cả hai vũ khí.\nGravitum (Pháo Trọng Trường): Trói chân tất cả kẻ địch bị làm chậm bởi vũ khí này.\nInfernum (Súng Hỏa Ngục): Thổi lửa theo hình nón và tấn công kẻ địch bằng vũ khí phụ.\nCrescendum (Thăng Hoa Luân): Đặt một tháp cạnh bắn bằng vũ khí phụ.","Aphelios đổi vũ khí chính sang vũ khí phụ, cùng với đó là đòn đánh và kỹ năng kích hoạt.","Aphelios không có kỹ năng thứ ba. Chỗ này để hiển thị vũ khí kế tiếp Alune sẽ triệu hồi cho anh. Thứ tự vũ khí ban đầu là cố định, nhưng có thể thay đổi dần -- khi một vũ khí hết đạn, nó được đặt xuống cuối danh sách","Bắn một viên nguyệt đạn phát nổ trên tướng địch. Đặt hiệu ứng của vũ khí chính của Aphelios."]],"ashe":["Ashe là chiến mẫu sinh ra từ lớp băng của tộc Hậu Nhân Avarosa, và là người chỉ huy đội quân đông đảo nhất phương Bắc. Khắc kỷ, thông minh, và đầy lý tưởng nhưng lại chẳng mấy thoải mái với vai trò thủ lĩnh, cô đã đánh thức sức mạnh ma thuật từ cổ nhân để làm chủ cây cung làm từ Chân Băng. Cùng niềm tin từ người dân rằng cô là truyền nhân của nữ anh hùng thần thoại Avarosa, Ashe hy vọng có thể chiếm lại các vùng đất của bộ tộc cổ xưa và một lần nữa thống nhất Freljord.",["Các phát bắn của Ashe làm chậm mục tiêu, khiến cô gây thêm sát thương lên chúng.\nĐòn chí mạng của Ashe sẽ không gây thêm sát thương nhưng chúng sẽ làm mục tiêu bị chậm hơn nhiều.","Ashe gia tăng điểm Chú Tâm bằng cách tung những phát bắn thường. Khi đạt tối đa điểm Chú Tâm, Chú Tâm Tiễn sẽ tiêu hao hết tất cả điểm này giúp tăng Tốc độ Đánh và khiến các đòn đánh thường của Ashe thành những mũi tên liên hoàn trong một thời gian.","Ashe bắn ra loạt mũi tên gây sát thương theo hình nón. Kỹ năng này cũng áp dụng hiệu ứng Băng Tiễn.","Ashe lệnh cho Linh Hồn Chim Ưng đi do thám bất cứ đâu trên bản đồ.","Ashe bắn ra một mũi tên băng theo đường thẳng. Nếu mũi tên trúng một tướng địch, nó sẽ gây sát thương và làm choáng hắn. Thời gian làm choáng tăng theo quãng đường mũi tên bay được. Ngoài ra, kẻ địch xung quanh cũng dính sát thương và bị làm chậm."]],"aurelionsol":["Aurelion Sol đã từng ngự trị trên những dải thiên hà vô tận của vũ trụ cùng với những tạo tác kỳ quan do chính ông tạo ra. Nhưng giờ đây, ông lại phải sử dụng thứ sức mạnh thánh thần của mình theo lệnh của một vương quốc ngoài rìa vũ trụ - nơi đã từng lừa ông để ông phục vụ chúng. Dù có phải kéo sao trên trời xuống, Aurelion Sol cũng sẽ tất cả để đổi lấy sự tự do và trở về với những cung đường đầy sao của mình.",["Các kỹ năng gây sát thương của Aurelion Sol sẽ nghiền nát kẻ địch thành các cộng dồn Bụi Sao và cải thiện vĩnh viễn từng kỹ năng của ông.","Aurelion Sol bắn ra hơi thở của rồng trong vài giây, gây sát thương lên kẻ địch đầu tiên trúng đòn và lan lượng sát thương đã suy giảm lên những kẻ địch ở gần. Mỗi giây hơi thở được bắn trực tiếp lên một kẻ địch sẽ gây thêm sát thương nhờ lượng Bụi Sao đã thu thập được. Kỹ năng này sẽ thu được Bụi Sao nếu mục tiêu là tướng.","Aurelion Sol bay vượt địa hình theo hướng chỉ định. Ông vẫn có thể sử dụng các kỹ năng khác khi đang trong trạng thái này. Khi đang bay, Hơi Thở Hỏa Tinh sẽ không có hồi chiêu hay thời gian bắn tối đa và gây thêm sát thương.\nHồi chiêu còn lại của Thượng Long Cảnh Giới sẽ giảm khi Aurelion Sol gây sát thương lên tướng địch và hạ gục chúng.\nBụi Sao sẽ tăng tầm đánh tối đa của Thượng Long Cảnh Giới.","Aurelion Sol triệu hồi 1 hố đen, gây sát thương và từ từ kéo kẻ địch vào giữa tâm của hố. Kỹ năng này sẽ cho Bụi Sao với mỗi kẻ địch bị hạ gục trong hố đen và mỗi giây một tướng địch bị kẹt bên trong. Khi bị hút vào trung tâm, kẻ địch sẽ bị kết liễu nếu còn dưới một lượng % Máu tối đa nhất định. Bụi Sao giúp tăng phạm vi tác dụng của Hố Đen Kỳ Bí cũng như ngưỡng kết liễu.","Sao Rơi: Aurelion Sol ném một ngôi sao xuống mặt đất. Vụ va chạm này sẽ gây sát thương phép và làm choáng kẻ địch đồng thời vẫn ban Bụi Sao tương ứng với mỗi kẻ địch trúng đòn. Sao Rơi tiếp theo của Aurelion Sol sẽ biến thể thành Màn Trời Giáng Thế nếu thu thập đủ Bụi Sao.\nMàn Trời Giáng Thế: Aurelion Sol lôi ra một ngôi sao khổng lồ từ thiên đường, gia tăng vùng ảnh hưởng cũng như lượng sát thương gây ra, đồng thời hất tung tất cả kẻ địch xung quanh thay vì làm choáng chúng. Sau đó, một luồng sóng xung kích sẽ lan tỏa từ rìa của vùng tác động, gây sát thương và làm chậm tất cả kẻ địch trúng đòn. Bụi Sao sẽ tăng phạm vi tác động của cả Sao Rơi lẫn Màn Trời Giáng Thế."]],"aurora":["Ngay từ khi được sinh ra, Aurora đã sống chung với một khả năng độc đáo đó là di chuyển qua lại giữa cõi linh hồn và vật chất. Quyết tâm tìm hiểu thêm về những cư dân của cõi linh hồn, cô rời nhà để tiếp tục nghiên cứu và tình cờ gặp một á thần bướng bỉnh, người đã trở nên tha hóa và đánh mất chính mình. Chứng kiến sự tuyệt vọng ẩn giấu, Aurora quyết tâm tìm cách giúp người bạn hoang dã của mình lấy lại danh tính đã mất - cuộc hành trình sẽ đưa cô đến những nơi xa nhất của Freljord.",["Đòn đánh và kỹ năng của Aurora sẽ thanh tẩy linh hồn trên những kẻ địch mà cô gây sát thương lên. Các linh hồn được thanh tẩy sẽ đi theo Aurora và hồi máu cho cô.","Aurora bắn ra một bùa chú, nguyền rủa bất cứ kẻ địch nào trúng chiêu. Cô ấy có thể tái kích hoạt kỹ năng này để thu những lời nguyền đang kích hoạt về bản thân, gây sát thương lên những kẻ địch trúng chiêu trên đường thu về.","Aurora nhảy về hướng chỉ định, bước vào cõi linh giới khi tới nơi, trở nên tàng hình và nhận thêm Tốc Độ Di Chuyển trong một khoảng thời gian ngắn.","Aurora hội tụ cõi linh giới, giải phóng năng lượng linh hồn, gây sát thương phép và làm chậm những kẻ địch trúng chiêu. Sau đó cô ấy sẽ nhảy lùi lại để vào vị trí an toàn.","Aurora nhảy về hướng chỉ định, phóng ra một sóng âm gây sát thương và làm chậm những kẻ địch trúng chiêu. Sau đó, cô ấy tạo ra một khu vực làm chậm kẻ địch bên trong và cho phép Aurora dịch chuyển từ đầu này sang đầu kia."]],"azir":["Azir là hoàng đế của Shurima từ một thời đại xa xưa, một kẻ kiêu hãnh đứng trên đỉnh của sự bất tử. Thói ngạo mạn đã khiến ngài bị phản bội và bị sát hại đúng thời khắc đắc thắng nhất. Nhưng giờ, qua hàng thiên niên kỷ sau, ngài đã tái thế và trở thành Thể Thăng Hoa đầy sức mạnh. Sau khi thành phố bị chôn vùi của ngài trỗi dậy từ lòng cát, Azir khát khao có thể phục hồi Shurima được hưng thịnh như trước đây.",["Azir có thể triệu hồi Đĩa Mặt Trời từ tàn tích trụ.","Azir lệnh cho tất cả Binh Sĩ Cát lao về hướng đã chọn. Binh Sĩ Cát gây sát thương phép lên tất cả mục tiêu chúng lướt qua và gây hiệu ứng làm chậm trong 1 giây.","Azir triệu hồi 1 Binh Sĩ Cát để tấn công những kẻ địch ở gần, binh sĩ này sẽ tung đòn đánh lên những mục tiêu trong tầm đánh của mình thay cho Azir. Những đòn đánh này sẽ gây sát thương phép lên kẻ địch theo đường thẳng.","Azir tạo lá chắn cho bản thân và lướt tới chỗ một Binh Sĩ Cát, gây sát thương lên kẻ địch. Nếu lướt trúng tướng, ngài ngay lập tức dừng lướt và nhận được một tích trữ Binh Sĩ Cát.","Azir triệu hồi ra một bức tường những binh sĩ xông tới, đẩy lùi và sát thương kẻ địch."]],"bard":["Người du hành qua những vì tinh tú, Bard là một sứ giả hòa bình với mục tiêu duy trì sự hài hòa giữa vạn vật, và sự thờ ơ lạnh lẽo của những thứ ngoài kia. Nhiều người Runeterra đã truyền lại những câu hát về bản chất lạ lùng của ông, dù họ đều đồng ý rằng vị lữ khách vũ trụ này bị thu hút bởi những tạo vật mang sức mạnh ma thuật to lớn. Bao quanh ông là dàn đồng ca của những tinh linh meep hữu ích, thật không thể nhầm lẫn rằng những điều ông làm là có ý đồ xấu xa, bởi Bard luôn phụng sự cho một lợi ích lớn lao chung… theo cách riêng của ông.",["Tinh Linh Chuông: Bard thu hút các tinh linh nhỏ bé hỗ trợ ông đánh thường, gây thêm sát thương phép. Khi Bard thu thập đủ số Chuông, các tinh linh sẽ gây thêm sát thương diện rộng và làm chậm kẻ địch.\nChuông: Chuông xuất hiện ngẫu nhiên cho Bard thu thập. Chúng cho kinh nghiệm, hồi phục năng lượng, và Tốc độ Di chuyển ngoài giao tranh.","Bard bắn ra một luồng sóng năng lượng làm chậm kẻ địch đầu tiên trúng chiêu, rồi tiếp tục bay đi. Nếu va phải tường, nó sẽ làm choáng mục tiêu khởi điểm; nếu va phải một tướng địch khác, nó sẽ làm choáng cả hai.","Tạo ra một ngôi điện giúp hồi Máu và có thể được cường hóa theo thời gian. Nó sẽ biến mất sau khi hồi máu và tăng tốc cho đồng minh đầu tiên chạm vào.","Bard mở ra một cánh cổng tại vùng địa hình cạnh bên. Tất cả kẻ địch lẫn đồng minh đều có thể tham gia vào chuyến hành trình một chiều xuyên địa hình này.","Bard phóng thích năng lượng vào một vị trí khiến tất cả các tướng, lính, quái và trụ trong vùng ảnh hưởng đều phải rơi vào trạng thái tĩnh trong thoáng chốc."]],"belveth":["Một nữ chúa quỷ quyệt được tạo ra từ những loại vật liệu thô từ cả một thành phố đã bị nuốt chửng, Bel'Veth chính là cái kết của Runeterra… và là khởi đầu của thực tại kinh hoàng mà ả hằng mong muốn. Dẫn đường bởi những kỉ nguyên của lịch sử, kiến thức, và những kỉ niệm từ thế giới bên trên được viết lại, ả ngấu nghiến cái nhu cầu trải nghiệm và cảm xúc mới, thu nhập tất cả những gì đi qua con đường của ả. Thế nhưng nhu cầu của ả chưa bao giờ có thể thoả mãn được chỉ bằng một thế giới khi ả hướng khát vọng cháy bỏng của mình tới những cựu thần của Hư Không…",["Bel'Veth nhận cộng dồn tốc độ đánh vĩnh viễn khi hạ lính to, quái to hoặc tướng. Ả cũng nhận thêm tốc độ đánh tạm thời sau khi sử dụng kỹ năng.","Bel'Veth lướt theo một hướng chỉ định và gây sát thương lên tất cả các kẻ địch ả lướt qua.","Bel'Veth dậm mạnh đuôi xuống đất tạo ra một vết nứt, gây sát thương, hất tung và làm chậm kẻ địch.","Bel'Veth tự trói bản thân mình tại chỗ, vận sức tạo ra một cơn bão những nhát xiên liên tục nhắm vào mục tiêu thấp máu nhất, đồng thời cho bản thân ả thêm hút máu và giảm sát thương nhận vào.","Bel'Veth nuốt chửng một vết tích san hô Hư Không, biến đổi thành hình dạng thực sự của ả và được nhận thêm máu tối đa, tầm đánh và tốc độ đánh. Tiêu thụ vết tích san hô Hư Không của một quái khủng Hư Không sẽ cho khả năng triệu hồi lũ cá hư không."]],"blitzcrank":["Được tạo ra để dọn dẹp mọi rác thải độc hại ở Zaun, Blitzcrank là một người máy hơi nước khổng lồ, gần như không thể bị phá hủy. Tuy nhiên, vì cảm thấy việc dọn dẹp quá hạn chế, nó đã tự biến đổi bản thân trở thành thể dạng khác để phục vụ cho người dân Khu Hầm Thải tốt hơn. Blitzcrank sử dụng sức mạnh và sức bền của mình để bảo vệ người khác, sẵn sàng quên mình và chìa tay giúp đỡ hoặc tung điện từ ngăn chặn bất kỳ kẻ gây rối nào.",["Blitzcrank nhận được một lá chắn dựa theo số năng lượng khi thấp máu.","Blitzcrank bắn tay phải ra chộp lấy kẻ địch trên đường, gây sát thương rồi kéo mục tiêu về phía mình.","Blitzcrank vận hành bộ biến áp khiến nó được tăng mạnh Tốc độ Di chuyển và Tốc độ Đánh. Nó tạm thời bị làm chậm sau khi hết thời gian hiệu lực.","Blitzcrank gồng nắm đấm khiến đòn đánh kế gây gấp hai sát thương và hất kẻ địch lên trời.","Kẻ địch bị Blitzcrank tấn công bị đánh dấu và chịu sát thương điện từ sau 1 giây. Ngoài ra, Blitzcrank có thể kích hoạt kỹ năng này để phá lá chắn, gây sát thương và làm câm lặng kẻ địch xung quanh."]],"brand":["Từng là một tộc nhân của Freljord băng giá mang tên Kegan Rodhe, sinh vật được gọi là Brand chính là bài học về sức cám dỗ của sức mạnh. Sau khi tìm được một viên Cổ Ngữ Thế Giới trong truyền thuyết, Kegan đã phản bội những người đồng hành và chiếm lấy nó cho riêng mình và rồi chỉ trong chớp mắt, con người ấy đã không còn. Linh hồn của hắn bị thiêu rụi, thân xác hắn trở thành ngọn lửa sống. Giờ đây Brand đi khắp Valoran tìm kiếm những Cổ Ngữ khác, thề sẽ trả thù cho những điều sai trái mà có sống mười cõi đời hắn cũng chưa chắc phải chịu.",["Các kỹ năng của Brand khiến mục tiêu bị bỏng, gây sát thương trong vòng 4 giây, cộng dồn nhiều nhất 3 lần. Nếu Brand hạ gục kẻ địch đang bị bỏng, hắn hồi lại năng lượng. Khi Bỏng đạt cộng dồn tối đa trên một tướng hoặc quái to, nó trở nên bất ổn và phát nổ sau 2 giây, đặt hiệu ứng kỹ năng và gây lượng lớn sát thương trong một vùng quanh nạn nhân.","Brand phóng quả cầu lửa tới phía trước gây sát thương phép. Nếu mục tiêu đang bị bỏng, Vệt Lửa sẽ làm choáng mục tiêu.","Sau một thoáng, Brand tạo ra một cột lửa tại vị trí đã chọn, gây sát thương phép lên những kẻ địch trong vùng ảnh hưởng. Những nạn nhân đang bị bỏng trúng chiêu sẽ phải chịu thêm 25% sát thương.","Brand gọi ra một vụ nổ lớn ngay trên mục tiêu, lan sang những kẻ địch ở gần và gây sát thương phép lên chúng. Nếu mục tiêu bị bỏng, Bùng Cháy sẽ lan gấp đôi.","Brand phóng ra một luồng lửa hủy diệt có thể nảy tối đa 5 lần giữa Brand và những kẻ địch ở gần, gây sát thương phép lên chúng mỗi lần nảy. Luồng lửa sẽ ưu tiên những Tướng chịu nhiều cộng dồn Bỏng. Nếu mục tiêu bị bỏng, Bão Lửa sẽ thoáng làm chậm chúng."]],"braum":["Với lớp cơ bắp rắn chắc cùng trái tim bùng cháy hơn tất thảy, Braum là người hùng được cả Freljord yêu mến. Sảnh rượu nào ở phía bắc Frostheld cũng bàn tán về thứ sức mạnh huyền thoại có thể san bằng nguyên cánh rừng sồi chỉ trong một đêm và nắm đấm làm cho một ngọn núi tan tành thành đá vụn của ông. Cùng một cánh cửa kho được phù phép làm khiên, Braum đi khắp phương Bắc giá lạnh cùng nụ cười rộng mở dưới hàng ria. Ông hẳn là một người bạn đích thực cho tất cả những ai cần giúp đỡ.",["Đòn đánh của Braum gây hiệu ứng Đánh Ngất Ngư. Sau khi đã kích phát điểm tích trữ đầu tiên, các đòn đánh từ đồng minh cũng sẽ cộng dồn hiệu ứng Đánh Ngất Ngư.\nKhi đã đủ 4 điểm, mục tiêu sẽ bị choáng và chịu sát thương phép. Trong vài giây kế tiếp nạn nhân sẽ không thể chịu thêm điểm cộng dồn hiệu ứng, nhưng bù lại sẽ phải chịu thêm sát thương phép từ các đòn đánh thường của Braum.","Braum phóng băng từ chiếc khiên của hắn, gây sát thương phép và làm chậm.\nGây một điểm tích trữ hiệu ứng Đánh Ngất Ngư.","Braum phóng tới một mục tiêu tướng hoặc lính đồng minh. Khi đến nơi Braum và đơn vị đồng minh đó sẽ được nhận thêm Giáp và Kháng Phép trong vài giây.","Braum giương chiếc khiên của mình lên theo một phương hướng trong vài giây, tất cả các tia đạn đạo bay về phía đấy khi va vào hắn sẽ bị tiêu hủy hoàn toàn. Ngoài ra Braum còn chặn lại toàn bộ sát thương từ đòn đánh đầu tiên đồng thời giảm lại sát thương của toàn bộ các đòn đánh về sau tung ra từ hướng đó.","Braum dậm mạnh xuống mặt đất, hất văng những kẻ địch cạnh bên, và trong đường thẳng phía trước hắn lên không. Một vệt rạn nứt sẽ hiện ra theo đường thẳng đó gây hiệu ứng làm chậm lên các nạn nhân."]],"briar":["Một thí nghiệm thất bại của hội Hoa Hồng Đen, sự khát máu không thể kiểm soát của Briar đòi hỏi một chiếc gông đặc biệt để kiểm soát tâm trí điên cuồng của cô. Sau nhiều năm bị giam cầm, thứ vũ khí sống này đã thoát khỏi sự kềm kẹp và tự giải phóng bản thân ra thế giới bên ngoài. Giờ đây không còn bị ai kiểm soát, cô đi theo tiếng gọi của tri thức và máu, trân quý những cơ hội để hóa cuồng, kể cả khi việc giành lại kiểm soát là không hề dễ dàng.",["Đòn đánh và kỹ năng của Briar tạo cộng dồn chảy máu, giúp hồi máu cho cô bằng một phần sát thương gây ra. Luôn luôn trong cơn đói, cô được tăng khả năng hồi phục theo Máu đã mất, nhưng không có Hồi Máu Cơ Bản.","Briar nhảy tới một mục tiêu, tấn công kẻ địch bằng cú Lộn Gót (Đau Thương), làm choáng và phá Giáp của chúng.","Briar lao tới trước và phá hủy chiếc gông của mình, tiến vào trạng thái Cuồng Huyết, cô sẽ truy đuổi không ngừng kẻ địch ở gần nhất (ưu tiên tướng). Khi đang hóa cuồng, cô được tăng Tốc Độ Đánh và Tốc Độ Di Chuyển, đồng thời đòn đánh của cô gây sát thương lan xung quanh mục tiêu.\nBriar có thể tái kích hoạt kỹ năng này khi đang hóa cuồng để NGOẠM vào mục tiêu trong đòn đánh kế tiếp, gây thêm sát thương dựa trên lượng Máu đã mất của chúng và hồi máu cho bản thân bằng một phần sát thương gây ra.","Briar định thần lại, xóa bỏ Cuồng Huyết và dồn sức cho một cú thét mạnh mẽ khiến kẻ địch nhận sát thương và bị làm chậm. Khi đang vận sức, cô được giảm sát thương nhận phải và được hồi một phần Máu tối đa. Nếu vận sức tối đa, tiếng thét sẽ đẩy lùi kẻ địch, gây thêm sát thương và làm choáng những kẻ địch bị va phải tường.","Briar sút ra một phi tiêu máu từ chiếc gông, đánh dấu tướng địch đầu tiên trúng chiêu làm con mồi. Sau đó, cô sẽ lao thẳng tới con mồi, gây hoảng sợ cho những kẻ địch xung quanh khi tiếp cận mục tiêu, đồng thời tiến vào trạng thái cuồng máu hoàn toàn. Cô sẽ truy đuổi mục tiêu của mình cho đến khi kẻ đó bị hạ, nhận hiệu ứng Cuồng Huyết cũng như được tăng Giáp, Kháng Phép, Hút Máu và Tốc Độ Di Chuyển."]],"caitlyn":["Nhân viên trị an xuất sắc nhất Piltover - Caitlyn Kiramman cũng là người mang lại hy vọng dọn được sạch sẽ các tên tội phạm đang lẩn lút trong thành phố. Cô thường bắt cặp với Vi với cương vị là một đối trọng bình tĩnh trước tính nết hơi nóng nảy của bạn đồng nghiệp. Dù sở hữu khẩu súng trường Hextech độc nhất vô nhị, vũ khí mạnh nhất của Caitlyn lại là trí tuệ siêu phàm. Cô có thể đặt những cái bẫy tinh vi để bắt giữ bất kỳ kẻ phá luật nào đủ ngu ngốc dám ra tay trong Thành Phố Tân Tiến.",["Sau một vài phát bắn, hoặc khi bắn vào mục tiêu dẫm bẫy hay dính lưới, Caitlyn bắn một phát thiện xạ gây thêm sát thương (gia tăng theo tỉ lệ chí mạng). Với mục tiêu dẫm bẫy hay dính lưới, tầm bắn Thiện Xạ tăng gấp đôi.","Caitlyn nâng khẩu súng trường của mình lên trong 1 giây rồi bắn ra một phát đạn xuyên phá gây sát thương vật lí (sát thương giảm dần lên các mục tiêu trúng đòn tiếp theo).","Caitlyn đặt ra một chiếc bẫy, tướng địch khi dẫm vào bẫy sẽ bị lộ diện và bất động trong 1.5 giây, và cho Caitlyn một phát bắn Thiện Xạ.","Caitlyn bắn ra một tấm lưới làm chậm mục tiêu của cô ta. Còn Caitlyn sẽ bay ngược về phía sau.","Caitlyn ngắm cẩn thận cho một cú bắn chuẩn xác, gây sát thương khủng khiếp lên một mục tiêu ở cự ly xa. Tướng đối phương có thể hứng đạn thế cho đồng đội của chúng."]],"camille":["Camille là Đội trưởng Tình báo nhà Ferros, đồng thời là một điệp viên thanh lịch và tinh nhuệ hành án bên ngoài ranh giới luật pháp, đảm bảo cho cỗ máy Piltover lẫn khu Zaun bên dưới hoạt động trơn chu. Chuẩn xác và dễ dàng thích nghi, cô cho những hành động kỹ thuật cẩu thả là nỗi xấu hổ và cần phải đưa chúng về đúng quỹ đạo. Sở hữu trí tuệ sắc bén hệt như lưỡi dao của mình, Camille theo đuổi sự siêu việt bằng cách nâng cấp chính cơ thể mình bằng công nghệ hextech khiến nhiều kẻ phải tự hỏi không biết trong cơ thể đó, liệu phần máy có nhiều hơn phần người không.",["Đòn đánh lên tướng giúp tạo lá chắn tỉ lệ theo máu tối đa của Camille dựa trên loại sát thương của mục tiêu (Vật lý hoặc Phép) trong một khoảng thời gian ngắn.","Đòn đánh kế của Camille gây thêm sát thương và tăng Tốc độ Di chuyển. Kỹ năng này có thể tái sử dụng sau chốc lát, gây thêm nhiều sát thương nếu Camille ngừng lại một chút giữa hai đòn tấn công.","Camille quét theo hình nón sau một khoảng trễ, gây sát thương. Kẻ địch ở nửa ngoài vùng quét bị làm chậm và chịu thêm sát thương, đồng thời Camille được hồi máu.","Camille đu đến chỗ tường, rồi nhảy khỏi đó và hất tung tướng địch khi chạm đất.","Camille lướt tới tướng chỉ định, nhốt chúng trong một khu vực. Cô cũng gây thêm sát thương phép trên đòn đánh lên mục tiêu."]],"cassiopeia":["Cassiopeia là một sinh vật chết chóc thích thao túng kẻ khác để thực hiện ý đồ nham hiểm của mình. Từng là cô con gái út xinh đẹp nhất của gia tộc quý tộc Du Couteau xứ Noxus, ả đi xuống sâu dưới những hầm mộ Shurima để tìm kiếm sức mạnh cổ xưa. Tại đó, ả bị một sinh vật bảo vệ ngôi mộ cắn vào da thịt, và nọc độc của nó biến ả thành sinh vật hình rắn gớm ghiếc. Giờ đây Cassiopeia trườn và xảo quyệt lẩn quẩn dưới màn đêm tối, hóa đá kẻ thù bằng ánh nhìn tai họa của ả.",["Tất cả hiệu ứng tăng Tốc Độ Di Chuyển sẽ hiệu quả hơn trên Cassiopeia.","Cassiopeia tạo ra một vụ nổ Độc tại một khu vực sau thoáng chốc, tăng cho ả Tốc độ Di chuyển nếu như tung kỹ năng trúng tướng địch.","Cassiopeia phun độc thành hình cung trước mặt, để lại một đám mây độc trên mặt đất. Kẻ địch đứng trong chướng khí liên tục trúng độc, khiến chúng chịu sát thương theo thời gian, bị làm chậm và sa lầy. Kẻ địch bị sa lầy không thể dùng kỹ năng di chuyển.","Cassiopeia tung ra một đòn đánh vào mục tiêu, hồi máu cho ả. Nếu bị trúng độc, mục tiêu chịu thêm sát thương. Nếu mục tiêu bị hạ gục, Cassiopeia được hồi lại năng lượng.","Cassiopeia phóng thích một vòng xoáy năng lượng ma thuật từ đôi mắt của ả, làm choáng tất cả kẻ địch đối diện và làm chậm những kẻ dám quay lưng lại."]],"chogath":["Từ khoảnh khắc đầu tiên Cho'Gath xuất hiện dưới cái nắng gay gắt của Runeterra, con quái vật này đã bị thôi thúc bởi cơn đói vô độ. Cho'Gath, đại diện hoàn hảo cho khao khát nuốt chửng mọi sự sống của Hư Không, có hệ thống sinh học vô cùng phức tạp. Nó chuyển hóa mọi vật chất, cường hóa kích thước cơ thể và sức mạnh cơ bắp, biến lớp vỏ ngoài cứng cáp như kim cương. Đến một ngày khi sự cường tráng chẳng còn phù hợp với nhu cầu của quái thú Hư Không, nó nôn phần vật chất thừa có dạng gai nhọn ra ngoài, đâm xiên qua những con mồi và mặc chúng nằm đó đánh chén sau.",["Bất cứ khi nào Cho'Gath tiêu diệt một đơn vị, hắn được hồi lại Máu và Năng lượng. Giá trị này gia tăng dựa trên cấp của Cho'Gath.","Tạo một vụ địa chấn tại vị trí mục tiêu, tung kẻ địch lên không, gây sát thương và làm chậm.","Cho'Gath phóng thích một luồng sóng âm theo hình nón, gây sát thương phép và làm câm lặng kẻ địch trong vài giây.","Đòn đánh của Cho'Gath phun ra gai nhọn, gây sát thương và làm chậm tất cả kẻ địch trước mặt.","Ngoạm một đơn vị địch, gây sát thương chuẩn cực lớn. Nếu mục tiêu bị hạ, Cho'Gath tăng kích thước và Máu tối đa."]],"corki":["Chàng phi công Yordle Corki thích nhất hai thứ: bay, và bộ ria tuyệt đẹp của mình… dù không cần phải theo đúng thứ tự trên. Sau khi rời thành phố Bandle, anh định cư ở Piltover và say mê những cỗ máy tuyệt vời nơi đây. Anh tập trung phát triển những phương tiện trên không, dẫn dắt một lực lượng phòng không với cái tên Yipsnake Gầm Rú gồm những cựu binh dày dặn kinh nghiệm. Corki tuần tra bầu trời quanh quê hương mới với sự bình tĩnh và anh chưa từng gặp một vấn đề nào mà một dàn tên lửa không giải quyết được.",["Một phần sát thương đòn đánh cơ bản của Corki sẽ được gây ra dưới dạng sát thương chuẩn cộng thêm.","Corki bắn một quả bom sáng vào vị trí mục tiêu, gây sát thương phép lên những nạn nhân trúng chiêu. Vụ nổ làm lộ diện các đơn vị trong vùng ảnh hưởng trong thoáng chốc.","Corki bay một quãng ngắn, thả bom tạo ra một vệt lửa gây sát thương lên kẻ địch đứng trên đó.","Súng Máy của Corki bắn liên tục theo hình nón phía trước hắn, gây sát thương và giảm Giáp lẫn Kháng Phép của kẻ địch.","Corki bắn một quả hỏa tiễn vào vị trí mục tiêu sẽ nổ tung sau khi khi va chạm, gây sát thương lên những kẻ địch quanh vùng ảnh hưởng. Corki tích trữ một hỏa tiễn mỗi 12 giây lên đến tổng cộng 7 quả. Mỗi quả thứ 3 sẽ là quả Cực Đại, gây sát thương cao hơn."]],"darius":["Không có biểu tượng sức mạnh Noxus nào vĩ đại hơn Darius, tướng lĩnh đáng sợ và dạn dày nhất nơi đây. Đi từ xuất thân khiêm tốn và rồi trở thành Đại Tướng Noxus, hắn đã đập tạn vô số kẻ địch của đế quốc - nhiều người trong đó còn chính là người Noxus. Hắn không bao giờ nghi ngờ đại nghĩa của mình và cũng không bao giờ ngần ngại một khi đã vung lưỡi rìu của mình lên. Bất kỳ ai đối đầu với thủ lĩnh Quân đoàn Tam Cực sẽ không nhận được chút khoan dung nào.",["Đòn đánh và kỹ năng sát thương của Darius khiến kẻ địch xuất huyết, chịu sát thương vật lý trong vòng 5 giây, cộng dồn tối đa 5 lần. Khi tướng địch đạt tối đa cộng dồn, Darius hóa cuồng và nhận lượng lớn Sức mạnh Công kích.","Darius múa rìu xung quanh mình. Những kẻ địch trúng phải lưỡi rìu sẽ cho nhiều sát thương hơn những kẻ bị trúng phải cán rìu. Darius sẽ hồi máu lại dựa vào số tướng và quái to bị lưỡi rìu chém phải.","Đòn đánh tiếp theo của Darius nhắm vào động mạch kẻ địch. Khi bị chảy máu trầm trọng, Tốc Độ Di Chuyển của chúng sẽ chậm đi đáng kể.","Darius cường hóa chiếc rìu của mình, khiến sát thương vật lí của hắn bỏ qua một số phần trăm Giáp của mục tiêu. Khi được kích hoạt, Darius sẽ quét kẻ địch bằng chiếc rìu của mình và kéo chúng đến cạnh bên hắn.","Darius nhảy xổ vào một tướng địch rồi tấn công bằng một cú bổ chí tử, gây sát thương chuẩn. Lượng sát thương sẽ gia tăng dựa trên những điểm cộng dồn Xuất Huyết trên mục tiêu. Nếu Máy Chém Noxus là đòn kết liễu, kĩ năng này có thể được tái sử dụng trong một khoảng thời gian ngắn."]],"diana":["Cùng chiếc nguyệt kiếm lưỡi liềm trên tay, Diana là môn đồ và chiến binh của Giáo Hội Lunari - một đức tin đã bị vùi sâu dưới từng tấc đất quanh Đỉnh Núi Targon. Khoác trên mình bộ giáp lấp lánh màu tuyết lạnh trong đêm, cô là hiện thân cho sức mạnh của trăng bạc. Được Thượng Nhân từ trên đỉnh Núi Targon lựa chọn, Diana hấp thụ mọi tinh hoa, đấu tranh để hiểu được quyền năng và mục đích của mình tại thế giới này khi chẳng còn là con người nữa.",["Mỗi đòn đánh thứ ba sẽ lan sang các mục tiêu xung quanh, gây thêm sát thương phép. Sau khi sử dụng một kỹ năng, Diana được tăng Tốc Độ Đánh trong 5 giây.","Phóng thích một tia chớp năng lượng mặt trăng theo hình cung, gây sát thương phép.\nĐặt Ánh Trăng lên kẻ địch trúng phải, làm lộ diện chúng nếu chúng không tàng hình trong 3 giây.","Diana tạo ra 3 quả cầu quay quanh mình. Chúng phát nổ khi chạm vào kẻ địch, gây sát thương trên một vùng nhỏ. Cô cũng nhận được một lá chắn tạm thời. Nếu quả cầu thứ ba nổ, lá chắn được tăng thêm giá trị.","Biến thành hiện thân của mặt trăng báo thù, lao vào kẻ địch và gây sát thương phép.\nTrăng Mờ không có hồi chiêu khi lướt vào kẻ địch đang có hiệu ứng Ánh Trăng. Xóa bỏ Ánh Trăng trên tất cả kẻ địch dù chúng có là mục tiêu của Trăng Mờ hay không.","Diana làm lộ diện và kéo tất cả kẻ địch xung quanh lại, đồng thời làm chậm chúng.\nNếu Diana kéo được tướng, ánh trăng sẽ bao phủ cô sau khoảng trễ ngắn, gây sát thương phép ra xung quanh, tăng thêm với mỗi mục tiêu kéo được sau mục tiêu đầu."]],"drmundo":["Được biết đến là con quái vật màu tím cực kỳ điên rồ cùng sự tàn bạo đáng ghê tởm, Dr. Mundo là nỗi khiếp sợ của người dân xứ Zaun, khiến họ ở lỳ trong nhà vào những đêm đặc biệt tối trời. Dù giờ hắn tự xưng mình là bác sĩ, nhưng Mundo đã từng là bệnh nhân trong một trại tâm thần khét tiếng bậc nhất tại Zaun. Sau khi \"chữa trị\" cho toàn bộ nhân viên ở đó, Dr. Mundo tự mình thiết lập cơ sở hành nghề tại chính những căn phòng trống mình đã từng được điều trị, bắt chước những quy trình phi đạo đức trước đây thường xuyên được thực hiện lên cơ thể hắn. Cùng tủ thuốc đầy ắp và \"rất nhiều\" kiến thức y khoa, hắn ngày càng khiến bản thân mình trở nên quái dị hơn với từng mũi tiêm, khiến các \"bệnh nhân\" không may lang thang gần phòng khám của hắn phải khiếp sợ.",["Dr. Mundo miễn nhiễm hiệu ứng Bất Động đầu tiên lên hắn, thay vào đó sẽ mất Máu và văng ra một lọ hóa chất gần đó. Dr. Mundo có thể nhặt nó lên, hồi lại máu và giảm Hồi Chiêu Nội Tại này.\nDr. Mundo cũng được tăng mạnh Hồi phục Máu.","Dr. Mundo ném chiếc cưa tay, gây sát thương theo phần trăm máu hiện tại lên kẻ địch đầu tiên trúng phải và làm chậm chúng.","Dr. Mundo tự sốc điện bản thân, gây sát thương liên tục lên kẻ địch xung quanh và tích trữ một phần sát thương nhận vào. Khi kết thúc thời gian hiệu ứng, hoặc Tái Kích Hoạt, Dr. Mundo giải phóng một vụ nổ điện lên kẻ địch xung quanh. Nếu vụ nổ trúng một ai đó, hắn được hồi một phần lượng máu đã tích trữ","Nội tại - Dr. Mundo nhận thêm Sức Mạnh Công Kích, tăng lên dựa theo Máu tối đa.\nKích hoạt - Dr. Mundo nện đối thủ bằng \"túi y tế\" của mình, gây thêm sát thương dựa theo Máu đã mất. Nếu kẻ địch bị hạ gục, chúng sẽ bị hất văng đi, gây sát thương lên kẻ địch chạm phải.","Dr. Mundo bơm hóa chất vào cơ thể, hồi lập tức một lượng máu đã mất. Sau đó hắn nhận thêm Tốc Độ Di Chuyển và hồi lại một phần Máu tối đa của bản thân trong một thời gian dài."]],"draven":["Tại Noxus, đấu trường đẫm máu là nơi các đấu sĩ đối đầu và so bì sức mạnh - nhưng chẳng ai được tung hô như Draven cả. Hắn nhận thấy rằng đám đông vô cùng tán dương những màn đấu kịch tính hắn tạo ra cùng mỗi cú xoay rìu điêu luyện vô song có được từ những ngày lính chiến. Nghiện sự cổ vũ người đời dành cho sự hoàn hảo thô bạo của mình, Draven thề sẽ đánh bại bất kỳ ai để đảm bảo tên hắn mãi mãi được ngân vang, lưu truyền khắp đế quốc.",["Draven tích điểm Ngưỡng Mộ khi bắt được một Rìu Xoay hoặc tiêu diệt một lính, quái hay trụ. Hạ gục tướng địch cho Draven thêm vàng dựa theo số điểm Ngưỡng Mộ.","Đòn đánh kế tiếp của Draven sẽ gây thêm sát thương vật lí. Chiếc rìu sẽ nảy ra khỏi mục tiêu văng lên không trung. Nếu Draven bắt được nó, hắn sẽ tự động sẵn sàng để tung ra chiêu Rìu Xoay lần nữa. Draven có thể sẵn sàng cho tối đa hai chiếc Rìu Xoay.","Draven nhận thêm Tốc độ Di chuyển và Tốc độ đánh. Lượng Tốc độ Di chuyển cộng thêm sẽ giảm dần theo thời gian. Bắt lại chiếc Rìu Xoay sẽ hoàn thành thời gian hồi chiêu Xung Huyết.","Draven quẳng chiếc rìu ra, gây sát thương vật lí lên những mục tiêu bị trúng phải và hất chúng sang một bên. Ngoài ra nạn nhân cũng bị làm chậm.","Draven ném hai chiếc rìu khổng lồ gây sát thương vật lý lên những kẻ địch chúng đi qua. Lốc Xoáy Tử Vong sẽ từ từ đổi chiều và quay trở về Draven sau khi trúng một mục tiêu. Draven cũng có thể kích hoạt kỹ năng này trong khi lưỡi rìu đang bay để thu nó về sớm hơn. Gây ít sát thương hơn với mỗi kẻ địch nó đi qua và tái tạo lại khi đổi hướng. Kết liễu ngay lập tức kẻ địch có ít máu hơn số cộng dồn Ngưỡng Mộ của Draven."]],"ekko":["Một thiên tài từ khu ổ chuột của Zaun, Ekko có thể thao túng thời gian để xoay chuyển mọi tình thế thành có lợi cho mình. Cậu ta sử dụng phát minh của chính mình, động cơ Z-Drive, để khám phá mọi khả năng có thể xảy ra, từ đó kiến tạo những khoảnh khắc hoàn hảo trong mọi tình huống. Dù mê đắm trong sự tự do của bản thân, nhưng nếu bạn bè gặp nguy hiểm thì Ekko và Ánh Lửa luôn sẵn sàng làm bất cứ thứ gì để bảo vệ cho họ.",["Mỗi đòn đánh hoặc kỹ năng sát thương thứ ba lên cùng mục tiêu sẽ khiến chúng chịu thêm sát thương phép, và tăng cho Ekko lượng lớn tốc độ di chuyển nếu đó là tướng.","Ekko tung ra một quả lựu đạn, thứ sẽ phát nổ tạo ra một trường thời gian bóp méo khi trúng một tướng địch, làm chậm và gây sát thương lên mọi đơn vị bên trong. Sau đó, nó sẽ quay trở lại với Ekko, gây sát thương trên đường về.","Đòn đánh của Ekko gây thêm sát thương phép lên các kẻ địch thấp máu. Cậu có thể dùng Lưỡng Giới Đồng Quy để tạo ra một vùng thời không sau vài giây giúp làm chậm kẻ địch đứng trong đó. Nếu Ekko đi vào vùng thời không, cậu có lá chắn và làm choáng kẻ địch.","Ekko lướt đi né tránh sát thương và kích hoạt Động Cơ Zero. Đòn tấn công tiếp theo của cậu sẽ gây thêm sát thương và bóp méo thời gian, dịch chuyển tức thời cậu đến mục tiêu.","Ekko tự đảo lộn dòng thời gian của bản thân, khiến cậu trở nên không thể bị chọn làm mục tiêu và quay về thời điểm thích hợp trong quá khứ. Cậu ta biến trở lại địa điểm vài giây trước, và hồi máu một phần sát thương nhận vào trong thời gian đó. Kẻ địch đứng gần địa điểm này sẽ phải chịu rất nhiều sát thương."]],"elise":["Sâu trong thành phố cổ nhất Noxus, né tránh ánh mặt trời trong cung điện tối tăm chính là mãnh thú săn mồi hiểm ác - Elise. Ả từng là người thường, cai quản một gia tộc hùng mạnh, nhưng vết cắn từ một á thần đê hèn đã biến đổi ả thành một thứ khác xinh đẹp, bất tử và hoàn toàn phi nhân tính - một sinh vật với hình thù giống nhện có khả năng thu hút con mồi dấn thân vào lưới mạng của ả. Để có thể duy trì tuổi trẻ vĩnh hằng, Elise săn lùng những kẻ khờ dại và vô tín chẳng thể kháng cự sức quyến rũ của ả, điều cũng chẳng mấy ai có thể làm được.",["Dạng Người: Khi Elise dùng kỹ năng trúng 1 kẻ địch, cô nhận được 1 Nhện Con ngủ say.\nDạng Nhện: Đòn đánh gây thêm sát thương phép và hồi máu cho Elise.","Dạng Người: Mục tiêu càng nhiều máu thì gây càng nhiều sát thương.\nNhện Chúa: Nhảy xổ vào kẻ địch, nạn nhân còn càng thấp máu càng nhận nhiều sát thương.","Dạng Người: Phóng một con Nhện Con độc tố vào kẻ địch, nó sẽ phát nổ khi đến gần một mục tiêu.\nNhện Chúa: Elise cùng bầy Nhện Con được tăng Tốc độ Đánh.","Dạng người: Làm choáng kẻ địch đầu tiên trúng phải đồng thời khiến nạn nhân bị lộ diện nếu chúng đang không tàng hình.\nNhện Chúa: Elise cùng bầy Nhện Con đu lên dây tơ rồi đáp xuống ngay trên mục tiêu. Sau khi đáp xuống mục tiêu, Elise được tăng sát thương và hồi máu cộng thêm của Dạng Nhện.","Biến thành một con nhện hung hãn, đánh đổi tầm đánh để lấy Tốc độ Di chuyển và dàn kĩ năng mới."]],"evelynn":["Bên trong ranh giới hắc ám của Runeterra, nữ yêu Evelynn đang tìm kiếm nạn nhân tiếp theo. Ả dụ dỗ con mồi bằng vẻ khiêu gợi của một người phụ nữ, rồi khi kẻ đó bị bùa mê ngải lú, Evelynn mới lộ ra chân dạng. Thế là, ả lôi nạn nhân vào đọa đày khôn xiết, tận hưởng vui thú trước nỗi đau của họ. Với nữ yêu, những mối quan hệ đó chỉ là những lần chơi bời vô hại. Nhưng với phần còn lại của Runeterra, chúng là những truyện kể rùng rợn về thứ dục vọng đi sai đường, đồng thời cũng là lời nhắc nhở kinh hoàng về cái giá của khát khao lầm lạc.",["Khi không giao tranh, Evelynn tiến vào trạng thái Yêu Ảnh. Yêu Ảnh hồi máu cho Evelynn nếu ả đang thấp máu và cho Ngụy Trang sau cấp 6.","Evelynn dùng sợi roi trên lưng để tấn công, gây sát thương lên đơn vị đầu tiên trúng phải. Tiếp đó, Evelynn có thể bắn ra một dải gai vào kẻ địch ở gần một vài lần.","Evelynn nguyền rủa mục tiêu, khiến đòn đánh hoặc kỹ năng kế tiếp của ả sau một khoảng trễ sẽ mê hoặc mục tiêu và giảm Kháng Phép của kẻ đó.","Evelynn quất roi vào mục tiêu, gây sát thương. Sau đó ả sẽ được tăng Tốc độ Di chuyển trong chốc lát.","Evelynn thoáng trở nên không thể bị chỉ định và càn quét vùng trước mặt trước khi dịch chuyển về sau một khoảng cách lớn."]],"ezreal":["Chàng thám hiểm gia bảnh bao với tài năng ma thuật chảy trong huyết quản nhưng chẳng hề hay biết - Ezreal đã bôn ba khắp những lăng mộ ẩn giấu, đùa giỡn với những lời nguyền cổ xưa và vượt qua những chướng ngại bất khả thi \"dễ như ăn kẹo\". Ngoài lòng dũng cảm và gan dạ không có điểm dừng cùng trí thông minh vốn có, điều giúp chàng ta dễ dàng ứng biến trong mọi trường hợp bất ngờ chính là chiếc giáp tay Shurima thần bí, thứ có thể bắn ra những luồng năng lượng hủy diệt. Chẳng thể chối cãi được rằng bất cứ nơi nào Ezreal đến, rắc rối sẽ luôn sát theo sau. Hoặc đằng trước. Hoặc có thể ở khắp mọi nơi.",["Ezreal nhận thêm Tốc độ Đánh mỗi khi dùng kỹ năng trúng đích, cộng dồn tối đa 5 lần.","Ezreal bắn ra một luồng năng lượng giúp làm giảm hồi chiêu nếu trúng kẻ địch.","Ezreal bắn ra một quả cầu dính vào tướng hoặc mục tiêu đầu tiên trúng phải. Nếu Ezreal tấn công kẻ địch có quả cầu, nó sẽ phát nổ và gây sát thương.","Ezreal bay đến một chỗ gần đó và bắn ra một luồng năng lượng vào kẻ địch gần nhất. Ưu tiên kẻ địch bị trúng Tinh Hoa Tuôn Chảy.","Ezreal giương cung rồi bắn ra một làn sóng năng lượng gây sát thương cực lớn lên mọi kẻ địch nó đi qua (sát thương giảm đi với lính và quái thường)."]],"fiddlesticks":["Một thứ gì đó vừa thức giấc trên Runeterra. Một thứ cổ đại. Một thứ kinh hoàng. Cơn ác mộng vĩnh cửu được biết đến với cái tên Fiddlesticks rình rập nơi rìa xã hội của những phàm nhân, được dẫn dụ đến những vùng đất đầy sự hoang tưởng, nơi nó nhấm nháp những nạn nhân hoảng loạn. Mang theo một lưỡi hái tà ác, con quái vật gầy gò, rách nát này chính là hiện thân của nỗi sợ, khiến tâm trí của những kẻ đủ xấu số để còn sống sót sau khi chạm trán nó vỡ vụn. Hãy cẩn thận với tiếng kêu của lũ quạ, hay tiếng thầm thì của một con bù nhìn hình người... bởi Fiddlesticks đã trở lại.",["Phụ kiện của Fiddlesticks sẽ được thay thế bởi Bù Nhìn Kỳ Quái.","Fiddlesticks gây sát thương lên kẻ địch bằng kỹ năng khi không bị chúng nhìn thấy hoặc thi triển Khiếp Hãi sẽ khiến chúng hoảng sợ trong một khoảng thời gian.","Fiddlesticks hút máu từ tất cả kẻ địch xung quanh, gây thêm sát thương kết liễu ở cuối hiệu ứng.","Fiddlesticks chém lưỡi liềm lên một khu vực, làm chậm tất cả kẻ địch trúng chiêu và câm lặng những mục tiêu ở trung tâm cú chém.","Triệu hồi một đàn quạ sát nhân bay điên cuồng xung quanh Fiddlesticks, gây sát thương mỗi giây lên tất cả kẻ địch trong vùng."]],"fiora":["Là nữ kiếm sư đáng sợ nhất của toàn cõi Valoran, Fiora nổi tiếng với ý chí bất khuất và niềm tự hào đến ngạo mạn của cô dành cho kĩ năng dụng kiếm của bản thân. Được sinh ra trong Nhà Laurent thuộc Demacia, Fiora giành lấy quyền chỉ huy gia tộc từ tay cha cô, khi nó gần như bị sụp đổ bởi một vụ bê bối. Mặc dù danh tiếng của nhà Laurent đã bị hủy hoại, Fiora vẫn tìm mọi cách để khôi phục danh dự của gia đình và đưa nhà Laurent trở lại hàng ngũ danh gia vọng tộc của Demacia.",["Fiora vạch ra một Điểm Yếu trên Tướng này. Nếu tấn công trúng Điểm Yếu, cô được Hồi Máu và nhận thêm Tốc Độ Di Chuyển.","Fiora lao tới trước và chém một kẻ địch gần kề, gây sát thương vật lí và các hiệu ứng trên đòn đánh.","Fiora chặn lại toàn bộ sát thương và các hiệu ứng khống chế nhận vào trong một khoảng thời gian ngắn, rồi đâm về một hướng. Cú đâm này sẽ làm chậm tướng địch đầu tiên trúng chiêu, hoặc làm choáng chúng nếu như Fiora đã chặn được một hiệu ứng khống chế cứng bằng kĩ năng này.","Fiora được tăng tốc độ đánh cho hai đòn tiếp theo. Đòn đánh đầu tiên sẽ làm chậm mục tiêu, còn đòn đánh thứ hai sẽ gây chí mạng.","Fiora vạch ra cả bốn Điểm Yếu trên một tướng địch và nhận thêm Tốc Độ Di Chuyển khi ở gần chúng. Nếu Fiora phá vỡ cả bốn điểm yếu hoặc nếu kẻ địch bị hạ gục sau khi Fiora tấn công ít nhất một điểm yếu, Fiora và đồng minh trong khu vực sẽ được hồi máu trong vòng vài giây."]],"fizz":["Fizz là một Yordle lưỡng cư trú ngụ giữa những rặng đá ngầm quanh Bilgewater. Cậu thường thu nhặt và trả lại những cống vật bị ném xuống biển bởi mấy ông thuyền trưởng mê tín. Qua vô số câu chuyện kể về những kẻ đánh giá thấp sinh vật nhỏ nhắn này, tới thủy thủ dạn dày nhất cũng biết đừng nên dây với cậu. Tuy hay bị nhầm lẫn với những tinh linh đại dương, cậu lại là chỉ huy của đám quái thú ăn thịt khổng lồ dưới đáy sâu và thích thú nuốt chửng cả đồng minh lẫn kẻ địch.",["Fizz có thể đi xuyên vật thể và giảm một lượng sát thương gánh chịu cố định từ mọi nguồn.","Fizz lướt qua mục tiêu, gây sát thương phép và đặt hiệu ứng trên đòn đánh.","Đòn đánh của Fizz làm chảy máu kẻ địch, gây sát thương phép trong vài giây. Fizz cường hóa đòn đánh tiếp theo để gây thêm sát thương và gia tăng sức mạnh cho các đòn đánh sau đó trong một thời gian ngắn.","Fizz nhảy lên rồi duyên dáng đáp xuống trên cây đinh ba, trở nên không thể bị chỉ định. Từ vị trí này, Fizz có thể dậm xuống mặt đất hoặc nhảy một lần nữa trước khi đập ra sau.","Fizz quăng cá vào hướng chỉ định, bám dính lấy bất kỳ tướng địch nào chạm phải và làm chậm mục tiêu. Sau chốc lát, thủy quái trồi lên, hất tung mục tiêu và đẩy kẻ địch xung quanh sang bên. Mọi kẻ địch trúng phải chịu sát thương phép và bị làm chậm."]],"galio":["Bức tượng đá khổng lồ Galio sừng sững đứng canh gác bên ngoài thành Demacia rực rỡ. Như một bức tường thành được tạo nên để chống lại các pháp sư của kẻ địch, Galio đứng bất động qua nhiều thập kỉ cho đến một ngày, nhờ thứ ma thuật hùng mạnh đã khiến ông chuyển mình sống dậy. Sau khi được tái thế, Galio dành hết thời gian tận hưởng niềm vui chiến trận cùng vinh dự hiếm hoi được bảo vệ đồng bào. Nhưng thắng lợi của ông luôn có hai mặt. Bởi thứ ma thuật ông đang cố gắng đánh bại lại chính là ngọn nguồn giúp ông thức giấc. Và ngay sau khi chiến thắng, ông sẽ lại trở thành bức tượng đá im lìm như ngày nào.",["Cứ sau vài giây, đòn đánh kế tiếp của Galio gây thêm sát thương phép trong một vùng.","Galio tung ra hai luồng gió hội tụ lại thành bão gây sát thương theo thời gian.","Galio di chuyển chậm lại và tiến vào thế thủ. Khi dừng vận sức, Galio sẽ khiêu khích và gây sát thương các kẻ địch gần đó.","Galio lùi lại một bước rồi lao tới, hất tung tướng địch đầu tiên đụng phải.","Galio chọn vị trí một đồng minh làm điểm đáp, tạo cho tất cả đồng minh trong khu vực một lớp giáp phép. Sau chốc lát, Galio đáp xuống vị trí đó, hất tung các kẻ địch xung quanh."]],"gangplank":["Tàn nhẫn và khó đoán, gã hải tặc vương thất thế Gangplank đã từng trị vì thành phố cảng Bilgewater là nỗi khiếp sợ của cả thế giới. Có nhiều người tin rằng khi thời của hắn kết thúc, hắn sẽ càng trở thành thực thể nguy hiểm hơn bao giờ hết. Gangplank muốn thấy Bilgewater chìm trong biển máu một lần nữa trước khi để nó rơi vào tay ai khác. Và giờ đây cùng khẩu súng, thanh gươm và hàng tá thùng thuốc súng, hắn quyết tâm đòi lại những gì đã tuột mất.",["Cứ sau vài giây, đòn đánh cận chiến của Gangplank sẽ thiêu đốt kẻ địch.","Bắn mục tiêu, cướp được thêm Vàng cho mỗi đơn vị địch bị tiêu diệt","Ăn trái cây để chữa lành các hiệu ứng khống chế và hồi Máu.","Gangplank đặt ra một thùng thuốc súng tại địa điểm chỉ định. Nếu hắn tấn công nó, nó sẽ phát nổ, gây sát thương của đòn đánh lan ra các kẻ địch trong phạm vi ảnh hưởng, và làm chậm chúng.","Gangplank ra hiệu cho tàu chiến của hắn oanh tạc một khu vực, làm chậm và gây sát thương lên kẻ địch."]],"garen":["Garen là chiến binh cao quý và đầy tự hào trong Đội Tiên Phong. Anh nhận được sự ca tụng bởi đồng đội cũng như kính trọng từ kẻ địch, chí ít là với tư cách là người trong dòng dõi Crownguard, những người mang trọng trách bảo vệ Demacia và lý tưởng của nó. Khoác trên mình bộ giáp kháng ma thuật và cầm trên tay thanh trọng kiếm, Garen hiên ngang đối đầu với lũ pháp sư và phù thủy trên chiến trường cùng với những lưỡi kiếm bén lạnh và nhanh như gió lốc.",["Nếu Garen không bị dính sát thương hoặc kỹ năng của địch, anh hồi lại một phần máu tối đa mỗi giây.","Garen nhận lượng lớn Tốc Độ Di Chuyển, xóa bỏ tất cả các hiệu ứng làm chậm trên bản thân. Đòn đánh tiếp theo tấn công vào điểm yếu của kẻ địch, gây thêm sát thương và khiến chúng câm lặng.","Garen được tăng Giáp và Kháng Phép khi hạ gục kẻ địch. Anh có thể kích hoạt kỹ năng để tạo lá chắn và kháng hiệu ứng trong chốc lát, sau đó là một lượng chống chịu nhỏ hơn nhưng lâu hơn.","Garen xoay kiếm quanh mình, gây sát thương vật lý lên các kẻ địch gần đó.","Garen triệu hồi sức mạnh Demacia để kết liễu tướng địch."]],"gnar":["Gnar là một yordle nguyên thủy, dù vừa vui vẻ đó thôi, nhưng cậu cũng có thể nổi giận ngay tức thì như một đứa trẻ, biến mình thành một con quái thú khổng lồ và hủy diệt. Bị mắc kẹt bên trong Chân Băng hàng thiên niên kỷ, sinh vật hiếu kỳ này cuối cùng đã thoát ra được và giờ đây chu du trong một thế giới mới, thứ đối với cậu thật kỳ lạ và đáng ngạc nhiên. Khi bị kích động trước những mối nguy hiểm, Gnar có thể ném bất cứ thứ gì cậu ấy có thể về phía kẻ thù, thường thì đó là chiếc boomerang của cậu… nhưng cũng có khi là cả một tòa nhà gần đó.",["Gnar tăng cộng dồn Cuồng khi giao tranh. Ở tối đa Cuồng, kỹ năng kế tiếp sẽ biến Gnar thành Gnar Khổng Lồ, tăng mạnh khả năng sống sót và kích hoạt bộ kỹ năng hoàn toàn mới.","Gnar quẳng đi chiếc boomerang thứ gây sát thương và làm chậm kẻ địch trúng phải trước khi quay về với hắn. Nếu hắn bắt lại được chiếc boomerang sẽ khiến thời gian hồi chiêu giảm đi.\nGnar Khổng Lồ ném đi một tảng đá, thứ sẽ đập vào một đơn vị đầu tiên trúng phải, gây sát thương và làm chậm mọi thứ cạnh bên. Tảng đá có thể được nhặt lại để giảm thời gian hồi chiêu.","Các đòn đánh và kĩ năng của Gnar khiến hắn cảm thấy phấn khích, giúp gây thêm sát thương và tăng Tốc độ Di chuyển.\nGnar Khổng Lồ không hề cảm thấy phấn khích, mà chỉ đơn giản là muốn đập phá mọi thứ phía trước hắn, làm choáng các nạn nhân trúng chiêu.","Gnar nhảy tới điểm đã chọn rồi nhún nhảy khỏi đầu bất kì đơn vị nào hắn đáp xuống, để tiếp tục di chuyển xa hơn.\nGnar Khổng Lồ quá lớn để nhún nhảy nên phải đáp mạnh xuống mặt đất, gây sát thương xung quanh hắn.","Gnar Khổng Lồ ném mọi thứ quanh hắn theo hướng đã chọn, gây sát thương và làm chậm các nạn nhân trúng chiêu. Bất kì kẻ địch nào trúng phải vách tường đều bị làm choáng và chịu thêm sát thương."]],"gragas":["Vừa vui vẻ vừa uy nghiêm, Gragas là bậc thầy ủ rượu có thân hình to lớn và tính khí ồn ào, luôn tìm kiếm những cách mới để nâng cao tinh thần của mọi người. Chẳng ai biết ông xuất thân từ đâu, chỉ biết rằng ông tìm kiếm nguyên liệu trong số những chất thải không tì vết của Freljord để giúp hoàn thiện món đồ uống pha chế mới nhất của mình. Ông ta bốc đồng, cứng đầu và nổi tiếng với những cuộc ẩu đả thường kết thúc bằng bữa tiệc thâu đêm và thiệt hại tài sản trên diện rộng. Sự hiện diện của Gragas báo hiệu trước cho một đêm đầy vui tươi và đổ nát - theo đúng thứ tự đó.",["Sau vài giây, Gragas lại được hồi máu khi sử dụng kỹ năng.","Gragas lăn thùng rượu đến một vị trí, có thể kích hoạt để phát nổ hoặc tự phát nổ sau 4 giây. Sức mạnh của vụ nổ sẽ tăng dần theo thời gian. Những kẻ địch trúng vụ nổ sẽ bị làm chậm Tốc độ Di chuyển.","Gragas uống thử loại rượu mới nhất của mình trong 1 giây. Hậu quả là hắn trở nên náo nhiệt và hiếu chiến, gây thêm sát thương phép lên tất cả kẻ địch xung quanh ở đòn đánh kế tiếp, đồng thời giảm lượng sát thương nhận vào.","Gragas lao đến vị trí đã chọn và va chạm với kẻ địch đầu tiên hắn đụng phải, gây sát thương lên tất cả kẻ địch xung quanh và làm choáng chúng.","Gragas quẳng bình rượu đến vị trí mục tiêu, phát nổ khi tiếp xúc, gây sát thương và hất tung kẻ địch trong vụ nổ."]],"graves":["Malcolm Graves là một tay lính đánh thuê, một tên nghiện cờ bạc cũng như là một tên cướp khét tiếng bị truy nã ở mọi thành phố hay đế quốc mà hắn đặt chân đến. Dù có tính cách nóng nảy, gã trọng danh dự của một tên tội phạm, và thường chỉ động đến khẩu shotgun hai nòng Định Mệnh của mình để kết thúc mọi sự vụ. Trong những năm gần đây, gã đã hàn gắn lại mối quan hệ với Twisted Fate, và cùng nhau gây náo loạn thế giới ngầm Bilgewater một lần nữa.",["Khẩu shotgun của Graves có một vài điểm đặc biệt. Graves phải nạp lại khi bắn hết đạn. Phát bắn sẽ bắn ra 4 viên đạn và không thể xuyên qua mục tiêu. Những mục tiêu không phải tướng khi dính nhiều đạn cùng lúc sẽ bị đẩy lùi.","Graves bắn ra một viên đạn sẽ nổ sau 1 giây, hoặc sau khi va phải địa hình.","Graves bắn một bọc khói vào khu vực chỉ định, tạo ra một đám mù làm giảm tầm nhìn. Kẻ địch trúng bọc khói chịu sát thương phép và bị giảm Tốc độ Di chuyển trong thoáng chốc.","Graves lướt về phía trước, nhận thêm Giáp và Kháng Phép trong vài giây. Nếu lướt về phía tướng địch, Graves được hai điểm Lì Đòn. Đòn đánh thường trúng kẻ địch sẽ giảm thời gian hồi của kỹ năng này và làm mới thời gian tăng chống chịu.","Graves bắn một viên đạn cực mạnh gây sát thương khủng lên mục tiêu đầu tiên trúng phải. Sau khi trúng một tướng hoặc bay hết tầm xa, viên đạn phát nổ gây sát thương theo hình nón."]],"gwen":["Bằng một loại phép thuật mà cô chưa từng hay biết, Gwen đã sống dậy, biến đổi từ hình dạng búp bê thành một cô gái bằng xương bằng thịt. Sử dụng chính những vật dụng đã tạo ra mình cùng tình yêu của chủ nhân trên từng bước chân, cô không xem thường bất kỳ điều gì cả. Quyền năng thanh tẩy từ Sương Lam, một loại ma thuật cổ xưa, đã biến kéo, kim và chỉ khâu của Gwen thành những món đồ sáng lấp lánh. Sự sống là điều quá mới mẻ đối với cô, nhưng Gwen rất hạnh phúc. Cô đã hạ quyết tâm chiến đấu vì những điều tốt đẹp trên thế giới đang đứng trên bờ vực tan vỡ.",["Đòn đánh của Gwen gây sát thương phép cộng thêm dựa theo số máu của mục tiêu. Cô được hồi lại một phần lượng sát thương hiệu ứng này gây ra lên tướng.","Gwen nhấp kéo theo hình nón tối đa 6 lần, gây sát thương phép. Gwen gây sát thương chuẩn lên các đơn vị ở trung tâm và áp dụng sát thương nội tại lên chúng trong mỗi nhát cắt.","Gwen triệu hồi màn sương bảo vệ bản thân khỏi những kẻ địch bên ngoài. Cô chỉ có thể bị chỉ định bởi những kẻ địch bước vào trong màn sương.","Gwen lướt đi một quãng ngắn, sau đó tăng tốc độ đánh, tầm đánh, và sát thương phép mỗi Đòn Đánh trong vài giây. Nếu tấn công kẻ địch trong thời gian này, hồi chiêu của Kỹ năng sẽ được trả lại một phần.","Gwen phóng một cây kim làm chậm kẻ địch, gây sát thương phép và áp dụng Ngàn Nhát Cắt lên tướng địch trúng chiêu.\nKỹ năng này có thể được sử dụng hai lần nữa, mỗi lần sau sẽ phóng ra nhiều kim hơn và gây thêm sát thương."]],"hecarim":["Sinh vật gớm ghiếc lai giữa người và thú, Hecarim bị nguyền rủa phải đời đời bắt giữ những linh hồn phàm trần. Khi Quần Đảo Phước Lành chìm vào trong màn sương đen, gã hiệp sĩ đầy tự hào này đã bị năng lượng hủy diệt của Đại Suy Vong nuốt chửng cùng với tất cả đoàn người ngựa sắt. Giờ đây, mỗi khi Màn Sương Đen ùa đến Runeterra, hắn dẫn đầu đội quân giết chóc, tận hưởng cuộc tàn sát và nghiền nát kẻ địch dưới móng sắt của mình.",["Hecarim nhận thêm Sức mạnh Công kích tương đương với số phần trăm Tốc độ Di chuyển được cộng thêm của hắn.","Hecarim tấn công các mục tiêu xung quanh và gây sát thương vật lý. Nếu Hecarim gây sát thương lên ít nhất một kẻ địch, hắn tăng sát thương và giảm thời gian hồi của các lần Càn Quét sau.","Hecarim nhận thêm Giáp và Kháng Phép. Hecarim gây sát thương phép lên kẻ thù xung quanh trong một khoảng thời gian ngắn, hắn cũng được hồi máu dựa trên phần trăm lượng sát thương mà đối phương phải gánh chịu.","Hecarim nhận thêm Tốc độ Di chuyển và có thể đi xuyên vật thể trong một khoảng thời gian ngắn. Đòn tấn công tiếp theo của hắn đẩy lùi mục tiêu đồng thời gây thêm sát thương vật lí dựa trên quãng đường di chuyển được từ khi kích hoạt kĩ năng.","Hecarim triệu hồi các bóng ma kị sĩ và chạy tới trước, gây sát thương phép trên một đường thẳng. Hecarim sẽ tạo ra một luồng sóng năng lượng khi hắn kết thúc cú phóng tới, khiến những kẻ địch cạnh bên bỏ chạy tán loạn trong sợ hãi."]],"heimerdinger":["Dù khá lập dị, Giáo Sư Cecil B. Heimerdinger là một trong những nhà sáng chế sáng tạo và được nể trọng nhất mà thế giới từng biết đến. Là một thành viên lâu năm của Hội Đồng Piltover, ông đã chứng kiến cả những điểm sáng và góc khuất trong tham vọng tiến bộ bất tận của thành phố. Tuy nhiên, nhà khoa học và người thầy lỗi lạc này sẽ luôn tận tâm sử dụng các thiết bị độc đáo của mình để cải thiện cuộc sống cho những người khác.",["Nhận thêm Tốc độ Di chuyển khi ở gần trụ đồng minh và Ụ Súng được Heimerdinger thiết lập.","Heimerdinger đặt một ụ súng bắn đại bác liên thanh kèm tia chớp xuyên thấu (ụ súng gây nửa sát thương lên trụ).","Heimerdinger bắn tên lửa tầm xa hội tụ ở chỗ trỏ chuột.","Heimerdinger ném lựu đạn vào một chỗ, gây sát thương lên kẻ địch đồng thời làm choáng những kẻ đứng ở tâm và làm chậm những kẻ đứng ngoài rìa.","Heimerdinger nảy ra sáng kiến cực ngầu, khiến kĩ năng kế tiếp của hắn được gia cường hiệu lực."]],"hwei":["Hwei là một họa sĩ u ám, người tạo ra những bức họa tuyệt đẹp để đối đầu với lũ tội phạm tại Ionia và an ủi những nạn nhân của chúng. Đằng sau nỗi u sầu đó là một tâm trí xúc cảm và giằng xé, bị ám ảnh bởi cả những hình ảnh sống động của trí tưởng tượng và ký ức khủng khiếp về vụ thảm sát ở ngôi đền. Hwei khao khát muốn hiểu được thứ ánh sáng và bóng tối này, cũng là động lực đưa anh về với tay nghệ sĩ đã khai sáng cho anh. Với cọ vẽ và bảng màu, Hwei tạo hình nên những khả năng vô tận để đưa anh tiến gần hơn tới hồi kết, hoặc chấp nhận sự tuyệt vọng.",["Hwei ký họa chữ ký của mình lên những tướng địch nhận sát thương từ kỹ năng của hắn.\nChữ ký sẽ hoàn thành và hiện lên dưới chân kẻ địch nếu chúng dính một kỹ năng gây sát thương thứ hai. Chữ ký phát nổ sau một khoảng chờ ngắn, gây sát thương phép lên tất cả kẻ địch gần đó.","Hwei hình dung về những thảm họa, cho phép hắn vẽ ra một cảnh tượng kinh hoàng.\nKỹ năng này thay thế các kỹ năng của Hwei bằng những kỹ năng gây sát thương: Lửa Tàn Phá, Sấm Sét Hủy Diệt và Vết Nứt Bỏng Cháy.","Hwei hình dung về một khung cảnh bình yên, cho phép hắn vẽ ra những bức họa khích lệ tinh thần.\nKỹ năng này thay thế các kỹ năng của Hwei bằng những kỹ năng hỗ trợ: Nước Chảy Thoáng Qua, Ánh Nước Phản Chiếu và Tia Sáng Khuấy Động.","Hwei hình dung về sự dằn vặt và khổ đau, cho phép hắn vẽ ra những khuôn mặt có khả năng khống chế kẻ địch.\nKỹ năng này thay thế các kỹ năng với hiệu ứng khống chế của Hwei: Khuôn Mặt U Ám, Địa Ngục Nhãn và Hàm Nhai Kinh Hãi.","Hwei vẽ ra một khung cảnh tuyệt vọng cùng cực. Tướng địch đầu tiên trúng chiêu sẽ trở thành trung tâm của một bức họa mở rộng dần, gây sát thương và làm chậm những kẻ địch gần bên. Khung cảnh sẽ phát nổ sau khi đạt kích thước tối đa hoặc nếu tướng địch hy sinh."]],"illaoi":["So với niềm tin mãnh liệt của bà, hình thể mạnh mẽ của Illaoi chẳng có cửa so bì. Với cương vị là nhà tiên tri của Thủy Thần Vĩ Đại, bà dùng tượng thần khổng lồ bằng vàng để rút hồn kẻ địch khỏi xác và đập tan nhận thức về thực tại của chúng. Mọi kẻ thách thức ''Người Nắm Giữ Chân Lý của Nagakabouros'' đều sớm phát hiện ra Illaoi không bao giờ đơn độc chiến đấu - vị thần của Quần Đảo Rắn luôn sát cánh bên bà ta.",["Illaoi và Tế Phẩm bà tạo ra sẽ sinh Xúc Tu trên địa hình gần đó. Xúc Tu đập vào linh hồn, Tế Phẩm, và mục tiêu Lời Răn Khắc Nghiệt của Illaoi. Tế Phẩm gây sát thương vật lý lên kẻ địch trúng phải, và hồi máu cho Illaoi nếu nó đập trúng một tướng.","Tăng sát thương từ Xúc Tu. Khi kích hoạt, Illaoi đập xuống một Xúc Tu gây sát thương vật lý.","Illaoi lao tới chỗ mục tiêu, gây sát thương vật lý và khiến các Xúc Tu gần đó quất vào mục tiêu.","Illaoi rút Linh Hồn ra khỏi thể xác kẻ địch, buộc nó phải đứng trước bà ta. Một phần sát thương Linh Hồn phải chịu cũng sẽ được gây ra cho thể xác. Nếu bị tiêu diệt hoặc nếu mục tiêu đi quá xa khỏi Linh Hồn, hắn sẽ trở thành Tế Phẩm và bắt đầu tạo ra Xúc Tu.","Illaoi đập tượng thần xuống đất, gây sát thương vật lý lên kẻ địch xung quanh. Một Xúc Tu được tạo ra với mỗi Tướng địch trúng phải."]],"irelia":["Giữa thời loạn cuộc bị Noxus chiếm đóng, Ionia đã sản sinh ra nhiều anh hùng, nhưng chẳng ai nổi bật hơn Irelia xứ Navori. Được luyện rèn cùng những điệu nhảy cổ xưa, cô áp dụng chính môn nghệ thuật này vào trong chiến đấu, sử dụng những động tác thanh nhã và điêu luyện để điều khiển hàng loạt lưỡi kiếm chết chóc. Sau khi chứng tỏ bản thân trong tư cách một chiến binh, cô được giao nhiệm vụ lãnh đạo kháng chiến, và tới tận ngày nay vẫn còn dốc lòng dốc sức cho công cuộc bảo vệ quê hương.",["Khi Irelia dùng kỹ năng trúng kẻ địch, cô nhận thêm Tốc độ Đánh cộng dồn. Ở số cộng dồn tối đa, cô gây thêm sát thương trên mỗi đòn đánh.","Irelia lướt tới tấn công mục tiêu và hồi máu cho bản thân. Nếu mục tiêu bị đánh dấu hoặc chết bởi Đâm Kiếm, nó hồi chiêu lại ngay lập tức.","Irelia vận sức gây sát thương cho kẻ địch dựa theo thời gian vận. Cô được giảm sát thương vật lý gánh chịu trong lúc vận.","Irelia tung ra hai lưỡi kiếm bay về phía nhau. Kẻ địch đứng trên đường thẳng đó chịu sát thương, bị làm choáng và đánh dấu.","Irelia phóng ra vô số lưỡi kiếm lan tỏa khi trúng phải một tướng địch. Đối phương dính chiêu sẽ nhận sát thương và bị Đánh Dấu. Sau đó, những lưỡi kiếm sẽ tạo thành một bức tường, gây sát thương và làm chậm đối phương bước qua nó."]],"ivern":["Ivern Bramblefoot, được nhiều người biết đến với cái tên Thụ Thần Thân Thiện là một sinh vật kỳ lạ nửa người nửa cây lãng du khắp các khu rừng ở Runeterra, gieo mầm sự sống tại mỗi nơi ông ghé qua. Ông biết những bí mật của thiên nhiên và kết tình bằng hữu với tất cả những gì sinh trưởng, bay lượn, hay chạy nhảy. Ivern đi giữa chốn hoang dã, truyền đạt tri thức cho bất kỳ ai ông gặp, làm tươi tốt thêm những cánh rừng, và đôi khi gửi gắm bí mật cho những chú bướm ngây thơ.",["Ivern không thể tấn công hoặc bị tấn công bởi quái thường. Ivern có thể tạo ra lùm cây ma thuật lớn dần theo thời gian ở bãi quái rừng. Khi lùm cây lớn hẳn, Ivern có thể trả tự do cho quái để nhận vàng và kinh nghiệm.","Ivern tạo ra một rễ cây gây sát thương và trói chân mục tiêu địch trúng phải. Đồng minh của Ivern có thể lướt tới mục tiêu bị trói.","Khi ở trong bụi, đòn đánh của Ivern và đồng minh gần bên sẽ gây sát thương phép cộng thêm. Ivern có thể kích hoạt kỹ năng này để tạo một bụi cỏ.","Ivern đặt lá chắn lên một đồng minh, lá chắn sẽ phát nổ sau chốc lát để làm chậm và gây sát thương lên kẻ địch. Lá chắn sẽ được hồi lại nếu không nổ trúng tướng địch.","Ivern triệu hồi người bạn hộ pháp Daisy để hỗ trợ chiến đấu. Tái kích hoạt để điều khiển Daisy tấn công hoặc di chuyển."]],"janna":["Sở hữu sức mạnh bão tố của Runeterra, Janna là một tinh linh gió đầy bí ẩn bảo vệ cho những con người khốn cùng ở Zaun. Nhiều người tin rằng cô có mặt trên trần thế theo lời thỉnh cầu của các thủy thủ mong mỏi cơn gió thuận khi băng qua vùng nước đầy bất trắc và bão dông. Kể từ đó, lòng tốt và sự bảo hộ của cô được kêu gọi từ thẳm sâu đất Zaun, nơi Janna trở thành biểu tượng cho hy vọng với những ai cần đến. Không người nào biết cô sẽ xuất hiện và ở đâu, nhưng thường thì, cô luôn đến để giúp đỡ.",["Đồng minh của Janna được tăng Tốc Độ Di Chuyển khi tiến về phía cô.\nJanna chuyển hóa một phần Tốc Độ Di Chuyển cộng thêm thành sát thương phép cộng thêm trên đòn đánh và cho Gió Tây.","Bằng cách tạo ra một vùng sức ép nhiệt độ, Janna có thể gọi ra một cơn bão ngày càng lớn theo thời gian. Cô có thể kích hoạt phép lần nữa để phóng thích cơn bão. Khi phóng thích cơn bão sẽ bay về hướng nó được tung ra, gây sát thương và hất văng kẻ địch trúng phải.","Janna triệu hồi một tinh linh gió có nội tại tăng Tốc Độ Di Chuyển cho cô và giúp cô đi xuyên qua các đơn vị. Cô cũng có thể kích hoạt kỹ năng này để gây sát thương và làm chậm Tốc Độ Di Chuyển của một kẻ địch.","Janna tạo ra một luồng gió bao phủ một tướng hoặc trụ đồng minh, giúp chặn sát thương nhận vào và tăng sát thương vật lí cho mục tiêu.","Janna bao phủ lấy bản thân bằng một cơn bão ma thuật, hất văng kẻ địch ra xa. Sau khi cơn bão xuất hiện, những cơn gió nhẹ sẽ hồi máu cho đồng minh xung quanh khi kỹ năng còn đang trong thời gian hiệu lực."]],"jarvan":["Là con trai duy nhất của nhà vua, Thái tử Jarvan chắc chắn sẽ kế vị ngai vàng Demacia. Được nuôi dậy để trở thành hình mẫu lý tưởng cho đạo đức quốc gia, anh bị buộc phải cân bằng giữa những kỳ vọng nặng nề đặt trên vài với khao khát được chứng tỏ bản thân trên chiến trường. Bên cạnh võ thuật cao cường, Jarvan còn biết khích lệ sĩ khí nhờ lòng dũng cảm và quyết đoán. Anh giương cao ngọn cờ của hoàng tộc và thể hiện sức mạnh chân chính của một nhà lãnh đạo tương lai.",["Đòn đánh đầu tiên của Jarvan lên 1 kẻ địch gây thêm sát thương vật lý dựa theo máu hiện tại của mục tiêu. Hiệu ứng không thể xảy ra trên cùng 1 kẻ địch trong vài giây.","Jarvan IV đâm thương về phía trước, gây sát thương vật lí và giảm giáp của tất cả kẻ địch trúng phải. Ngoài ra, kỹ năng này sẽ kéo Jarvan IV đến điểm rơi của Hoàng Kì Demacia, hất tung những kẻ địch trúng chiêu lên không.","Jarvan IV viện cầu sức mạnh từ những vì vua cổ đại của Demacia giúp bảo vệ anh khỏi sát thương và làm chậm kẻ địch xung quanh.","Jarvan IV mang theo niềm tự hào của Demacia giúp tăng một lượng Tốc độ Đánh nội tại. Kích hoạt Hoàng Kì Demacia cho phép Jarvan IV phóng đi lá cờ của Demacia gây sát thương tại điểm tiếp xúc, đồng thời tăng cho tướng đồng minh cạnh bên Tốc độ Đánh.","Jarvan IV anh dũng lao vào một mục tiêu mạnh đến mức địa hình xung quanh anh bị biến thành một vùng đấu trường. Những đơn vị đối phương cạnh bên cũng nhận sát thương tại cùng thời điểm."]],"jax":["Bậc thầy vũ khí vĩ đại nhất Runeterra, Jax là người sống sót cuối cùng trong những Kohari - các chiến binh đã tuyên thệ để bảo vệ Icathia. Nhưng khi Hư Không được giải phóng bởi chính sự ngạo nghễ của Icathia, nơi đây đã bị nuốt chửng, Jax và những chiến hữu của mình đã thề sẽ bảo vệ tất cả những gì còn sót lại. Giờ đây khi mối đe dọa ngưỡng tưởng đã chìm vào quên lãng thì ma thuật quay trở lại, ông lãng du khắp Valoran, thu thập “ánh sáng cuối cùng của Icathia” và tìm kiếm những chiến binh mạnh mẽ nhất để cùng mình kề vai sát cánh...",["Các đòn đánh cơ bản liên tục của Jax gia tăng cho hắn tốc độ đánh.","Jax nhảy bổ vào một mục tiêu. Nếu đó là kẻ địch, hắn tấn công nạn nhân bằng vũ khí của mình.","Jax tích tụ năng lượng vào vũ khí, khiến đòn đánh kế gây thêm sát thương.","Sự thiện chiến của Jax giúp hắn có thể tránh khỏi tất cả các đòn đánh trong một thời gian ngắn rồi nhanh chóng phản công gây choáng lên kẻ địch xung quanh.","Mỗi đòn đánh thứ ba liên tiếp gây thêm Sát Thương Phép. Ngoài ra, Jax có thể kích hoạt kĩ năng này để gây sát thương ra xung quanh và phóng thích sức mạnh tiềm tàng, giúp gia tăng Giáp và Kháng Phép trong một thời gian ngắn."]],"jayce":["Jayce Talis là một nhà phát minh xuất chúng, cùng với người bạn Viktor, đã có những khám phá vĩ đại đầu tiên trong lĩnh vực hextech. Được tôn vinh trên khắp Piltover, anh ấy cố gắng sống theo danh tiếng của mình là \"chàng trai hiện thân cho sự tiến bộ\", nhưng thường gặp phải nhiều khó khăn trước những kỳ vọng được đặt lên anh. Bởi vì điều này, Jayce đã bắt đầu nhận thấy phát minh của mình đang làm tăng thêm sự chia rẽ giữa Piltover và Zaun, và với cây búa hextech trên tay, anh ấy đã sẵn sàng bảo vệ tương lai của mình và của cả hai thành phố.",["Khi Jayce đổi vũ khí, anh nhận thêm Tốc độ Di chuyển trong một vài giây.","Dạng Búa: Bay tới một kẻ địch gây sát thương vật lí và làm chậm chúng.\nDạng Pháo: Bắn ra một quả cầu điện tích, thứ sẽ phát nổ khi chạm phải kẻ địch (hoặc hết tầm bay) gây sát thương vật lí lên tất cả những kẻ địch trong vùng ảnh hưởng của vụ nổ.","Dạng Búa: Nội tại: Hồi năng lượng theo mỗi đòn đánh. Kích hoạt: Tạo ra một vùng sấm chớp rền vang gây sát thương lên những kẻ địch xung quanh trong vài giây.\nDạng Pháo: Nhận một cú sốc năng lượng giúp tăng Tốc độ Đánh lên mức tối đa trong một vài đòn đánh kế tiếp.","Dạng Búa: Gây sát thương phép lên một kẻ địch và hất nạn nhân lùi lại một cự li ngắn.\nDạng Pháo: Tạo ra một chiếc Cổng Tăng Tốc giúp gia tăng Tốc độ Di chuyển cho những đồng minh bước qua đấy. Nếu Cầu Sấm được bắn xuyên qua cánh cổng này thì tốc độ bay, tầm bay và sát thương nó gây ra đều được gia tăng.","Dạng Búa: Chuyển sang Búa giúp nhận kĩ năng mới và được tăng tầm đánh. Đòn đánh đầu tiên ở dạng này sẽ giảm Giáp, Kháng Phép của nạn nhân.\nDạng Pháo: Chuyển sang Pháo giúp nhận kĩ năng mới và tăng Giáp, Kháng Phép. Đòn đánh đầu tiên ở dạng này sẽ gây thêm sát thương phép."]],"jhin":["Jhin là một tên tội phạm tâm thần tin rằng sát nhân là một loại nghệ thuật. Từng là tù nhân của Ionia nhưng được những kẻ đen tối trong hội đồng cai trị Ionia giải thoát, kẻ giết người hàng loạt này giờ hoạt động như là sát thủ cho chúng. Dùng khẩu súng như một cây cọ vẽ, Jhin tạo nên những tác phẩm nghệ thuật tàn nhẫn, khủng bố nạn nhân và những người không may chứng kiến. Sân khấu quái dị đem lại cho hắn sự thỏa mãn độc ác, khiến hắn trở thành lựa chọn hoàn hảo để gửi đến thông điệp hùng mạnh nhất: nỗi kinh hoàng.",["Khẩu đại bác cầm tay của Jhin, Lời Thì Thầm, là một công cụ gây sát thương cực lớn với độ chính xác cao. Nó bắn theo một tốc độ đánh cố định và chỉ chứa được bốn viên đạn. Viên đạn cuối cùng, mang theo ma thuật hắc ám, chí mạng và gây sát thương cộng thêm. Mỗi khi Lời Thì Thầm chí mạng, Jhin được tăng mạnh Tốc Độ Di Chuyển.","Jhin ném một bọc đạn vào một kẻ địch. Nó có thể nảy tối đa bốn mục tiêu và tăng thêm sát thương một lần hạ gục được một đơn vị.","Jhin giương súng lên bắn ra một phát đạn với tầm cực xa. Nó xuyên qua lính và quái, nhưng dừng lại ở tướng địch đầu tiên chạm phải. Nếu mục tiêu vừa bị tấn công bởi đồng minh của Jhin, dính bẫy hoa sen hoặc sát thương từ Jhin, chúng sẽ bị trói.","Jhin đặt một bẫy hoa sen kích hoạt khi bị giẫm lên. Nó làm chậm kẻ địch xung quanh trước khi gây sát thương trong một vụ nổ của những cánh hoa.\nCái Chết Hoàn Mỹ - Khi Jhin hạ gục một tướng địch, một Bẫy Hoa Sen sẽ nở rộ quanh thi thể chúng.","Jhin tập trung sức mạnh, biến đổi Lời Thì Thầm thành khẩu đại bác vác vai. Hắn có thể bắn ra 4 phát súng với tầm cực xa xuyên qua lính và quái nhưng dừng lại ở tướng địch đầu tiên chạm phải. Lời Thì Thầm làm chậm và gây sát thương cộng thêm lên kẻ địch trúng phải. Viên đạn thứ 4 được chế tạo hoàn hảo, vô cùng mạnh mẽ, và chắc chắn sẽ chí mạng."]],"jinx":["Một tội phạm điên cuồng và bốc đồng từ thành phố ngầm, Jinx bị ám ảnh bởi những thứ đã xảy ra trong quá khứ, nhưng điều đó cũng không ngăn cô gieo rắc sự hỗn loạn đặc trưng của mình đến cho Piltover và Zaun. Sử dụng kho vũ khí tự chế của mình với sức công phá khủng khiếp, giải phóng những vụ nổ và tiếng súng đầy màu sắc, truyền cảm hứng cho những kẻ nổi loạn và chống đối với sự điên cuồng mà cô mang lại.",["Jinx nhận lượng lớn Tốc độ Di chuyển và Tốc độ Đánh khi tham gia hạ gục tướng, công trình, hoặc quái khủng.","Jinx chuyển hóa các đòn đánh thường bằng cách hoán đổi giữa Bằng Chíu, khẩu súng nhỏ với Xương Cá, khẩu súng phóng lựu. Các phát bắn bằng Bằng Chíu sẽ tăng Tốc độ Đánh, còn các phát bắn bằng Xương Cá sẽ gây sát thương trên diện rộng, và gia tăng tầm bắn, nhưng bù lại sẽ tiêu hao Năng Lượng cũng như tốc độ bắn giảm.","Jinx sử dụng Giật Bắn, khẩu súng phóng điện, bắn một luồng sáng làm chậm, gây sát thương và làm lộ diện kẻ địch đầu tiên trúng phải.","Jinx ném ra một hàng lựu đạn, thứ sẽ phát nổ sau 5 giây, đốt cháy những kẻ địch. Lựu Đạn Ma Hỏa sẽ táp vào các tướng địch bước lên chúng, trói chân các nạn nhân đó.","Jinx bắn ra một quả siêu tên lửa bay toàn bản đồ, thứ vũ khí sẽ được gia tăng sát thương gây ra dựa trên khoảng cách nó đã bay. Quả tên lửa sẽ phát nổ khi va chạm với một tướng địch, gây sát thương lên nạn nhân chính cũng như các kẻ địch xung quanh đấy dựa trên số Máu chúng đã tổn thất."]],"ksante":["Tràn đầy thách thức và dũng cảm, K'Sante đã chiến đấu với vô số quái vật khổng lồ cũng như các thể thăng hoa tàn bạo để bảo vệ quê nhà của mình, ốc đảo Nazumah giữa lòng sa mạc Shurima. Nhưng sau khi những cuộc cãi vã nổ ra giữa anh và bạn đời của mình, K'Sante đã nhận ra rằng để trở thành một chiến binh xứng đáng lãnh đạo Nazumah, anh ta phải kiềm chế lòng kiêu hãnh của mình. Khi đó, K'Sante mới có thể đánh bại kẻ thù và bảo vệ người dân Nazumah.",["Kỹ Năng của K'Sante đánh dấu kẻ địch, khiến chúng nhận thêm sát thương từ Đòn Đánh tiếp theo của anh.\nKhi đang Khô Máu, K'Sante gây thêm sát thương trên tất cả Đòn Đánh và Kỹ Năng.","K'Sante dậm vũ khí, gây sát thương và làm chậm kẻ địch trong một khoảng ngắn.\nNếu trúng mục tiêu, nhận 1 cộng dồn Thần Khí Ntofo. Ở 2 cộng dồn, K'Sante bắn ra một sóng năng lượng kéo kẻ địch lại gần.\nKhi đang Khô Máu, hồi chiêu được giảm bớt.","K'Sante thủ thế, giảm sát thương nhận vào và sau đó lướt tới, đẩy lùi và làm choáng kẻ địch.\nKhi đang Khô Máu, gây thêm sát thương nhưng không còn đẩy lùi hoặc làm choáng.","K'Sante lướt đi và nhận một Lá Chắn. Nếu mục tiêu là đồng minh, K'Sante lướt tới đồng minh với tầm đánh xa gia tăng và cả hai cùng nhận Lá Chắn.\nKhi đang Khô Máu, hồi chiêu được giảm bớt và tốc độ được gia tăng.","K'Sante đẩy lùi một kẻ địch, hất chúng xuyên qua tường trên đường bay. Sau đó K'Sante tiến vào trạng thái Khô Máu và lướt đi theo chúng, được tăng sát thương, hồi máu và mở khóa kỹ năng mới tuy nhiên bị giảm sức phòng thủ."]],"kaisa":["Qua những trải đời khi bị Hư Không bắt đi khi còn nhỏ cùng bản lĩnh và ý chí kiên cường sống sót đã biến Kai'Sa trở thành một thợ săn đáng gờm và, và với một số người, cô là điềm báo cho một tương lai họ không muốn góp mặt. Với phần da thịt bám chặt cộng sinh bởi thứ sinh vật Hư Không, sẽ sớm đến lúc cô phải quyết định tha thứ cho những ai gọi mình là quái vật và cùng nhau đánh bại bóng tối... hay đơn giản là quên đi tất cả, để Hư Không nuốt chửng thế giới đã bỏ cô lại phía sau.",["Kai'Sa tích điểm Điện Dịch khi đánh thường, gây thêm sát thương phép. Các hiệu ứng bất động của đồng minh cũng giúp tích Điện Dịch. Bên cạnh đó, Kai'Sa nâng cấp các kỹ năng cơ bản khi mua trang bị.","Kai'Sa bắn ra một loạt tên năng lượng tìm kiếm các mục tiêu gần đó.\nVỏ Bọc Cộng Sinh: Cơn Mưa Icathia bắn nhiều tên năng lượng hơn.","Kai'Sa bắn ra một chùm tia tầm xa, đánh dấu nội tại lên kẻ địch.\nVỏ Bọc Cộng Sinh: Tia Truy Kích đánh dấu nhiều hơn và giảm hồi chiêu khi trúng tướng.","Kai'Sa tăng Tốc độ Di chuyển trong thoáng chốc, sau đó tăng Tốc độ Đánh.\nVỏ Bọc Cộng Sinh: Tích Tụ Năng Lượng được nâng cấp, cho Vô Hình trong thoáng chốc.","Kai'Sa lướt tới gần một tướng địch."]],"kalista":["Một bóng ma của sự trừng phạt và báo thù, Kalista là cơn ác mộng được triệu hồi từ Quần Đảo Bóng Đêm để săn đuổi những kẻ lật lọng và phản bội. Những nạn nhân có thể khóc lóc cầu xin được trả thù, nhưng Kalista chỉ trả lời những ai sẵn sàng trả giá bằng chính linh hồn của họ. Đau khổ sẽ đến với những ai trở thành mục tiêu của Kalista, vì mọi giao kèo với người thợ săn tàn nhẫn này chỉ có thể kết thúc với ngọn lửa lạnh lẽo trên mũi giáo của cô.",["Ra lệnh di chuyển khi Kalista đang đánh thường hoặc dùng Đâm Xuyên sẽ khiến cô phóng về hướng đó khi tung đòn đánh.","Kalista phóng ra một mũi giáo bay cực nhanh.","Gây thêm sát thương khi Kalista và Thệ Ước tấn công cùng một mục tiêu.\nKích hoạt để thả hồn ma do thám soi sáng khu vực trước mặt nó.","Các đòn đánh phóng giáo xuyên kẻ địch. Kích hoạt để rút các mũi giáo ra, làm chậm và gây sát thương gia tăng.","Dịch chuyển một đồng minh đến với Kalista. Họ có thể lướt tới một vị trí và đẩy lùi tất cả kẻ địch lại."]],"karma":["Không con người trần tục nào có thể minh chứng cho truyền thống tâm linh ở Ionia rõ ràng hơn Karma. Cô là hiện thân của một linh hồn cổ xưa đã tái sinh vô số lần, mang theo tất cả ký ức tiền kiếp sang mỗi cuộc sống mới, và ban phúc cho nó với sức mạnh ít ai hiểu thấu. Cô đã làm hết sức để dẫn dắt người dân qua thời kỳ khủng hoảng, dù biết rằng thái bình và hòa hợp chỉ có khi đánh đổi bằng cái giá khổng lồ - cho cả cô và vùng đất cô yêu mến nhất.",["Gây sát thương bằng kỹ năng sẽ giảm hồi chiêu của Kinh Mantra.","Karma phóng ra một quả câu năng lượng tâm linh, thứ sẽ phát nổ và sát thương khi trúng phải một đơn vị kẻ địch.\nMantra Cường Hóa: Sau vụ nổ, Kinh Mantra gia cường sức mạnh hủy diệt của kĩ năng Nội Hỏa, giúp tạo ra một vụ chấn động gây thêm sát thương sau thoáng chốc.","Karma tạo ra một sợi dây kết nối giữa bản thân với một kẻ địch, gây sát thương và làm nạn nhân bị lộ diện. Nếu mối liên kết không bị phá vỡ, kẻ địch sẽ bị trói chân và gây sát thương lần nữa.\nMantra Cường Hóa: Karma cường hóa mối liên kết, hồi máu bản thân và tăng thời gian trói chân.","Karma triệu hồi một lá chắn chặn sát thương và tăng Tốc độ Di chuyển cho đồng minh được bảo vệ.\nKinh Mantra: Năng lượng tỏa ra từ mục tiêu ban đầu, cường hóa giá trị cho lá chắn ban đầu và áp dụng Linh Giáp cho đồng minh xung quanh.","Karma cường hóa kĩ năng kế giúp gây thêm hiệu ứng. Kinh Mantra xuất hiện từ ngay cấp 1 và không cần điểm kĩ năng để tăng cấp."]],"karthus":["Điểm báo cho sự diệt vong, Karthus là một linh hồn bất tử hay ngân nga những bài hát ám ảnh, mở đầu cho nỗi kinh hoàng của sự hiện diện ác mộng của hắn. Người sống sợ sự vĩnh hằng của những hoạt tử nhân, nhưng Karthus chỉ thấy vẻ đẹp và sự thuần khiết trong đó, một sự kết hợp hoàn hảo giữa sinh và tử. Karthus rời khỏi Quần Đảo Bóng Đêm để mang đến niềm vui của cái chết cho đám người phàm, vị thánh tông đồ của những kẻ ''không sống''.",["Sau khi bị hạ gục, Karthus tiến vào trạng thái vong hồn cho phép hắn tiếp tục thi triển kỹ năng.","Karthus làm bùng phát một vụ nổ tại điểm đã chọn, gây sát thương lên những nạn nhân trúng chiêu. Gây thêm sát thương nếu mục tiêu bị cô lập.","Karthus tạo ra một bức tường xuyên thấu. Bất kì đơn vị kẻ địch nào bước qua đó đều sẽ bị giảm Tốc độ Di chuyển và Kháng Phép trong một thời gian cố định.","Karthus hấp thụ linh hồn của các nạn nhân giúp hắn phục hồi Năng lượng theo mỗi đơn vị tiêu diệt được. Ngoài ra, Karthus còn có thể bao phủ lấy bản thân bằng những cơn sóng linh hồn các nạn nhân của hắn để gây sát thương lên những kẻ địch cạnh bên, nhưng bù lại phải tiêu hao Năng lượng liên tục.","Sau khi niệm chú 3 giây, Karthus sát thương tất cả tướng địch."]],"kassadin":["Cắt một đường cháy rực qua những nơi tăm tối nhất của thế giới, Kassadin biết ngày tháng của mình không còn nhiều. Từng là một nhà thám hiểm đi nhiều biết rộng, ông cùng gia đình sống yên bình với các bộ tộc phương Nam - cho đến ngày làng của ông bị Hư Không nuốt mất. Ông thề trả thù, thu thập nhiều tạo vật ma thuật cũng như công nghệ cấm cho chuyến đi phía trước. Cuối cùng, Kassadin đặt chân đến vùng Icathia hoang vu, sẵn sàng đối mặt với bất kỳ con quái vật nào trên hành trình tìm kiếm gã tiên tri tự phong Malzahar.",["Kassadin được giảm sát thương phép gánh chịu và có thể bỏ qua vật thể.","Kassadin bắn một quả cầu năng lượng chân không, gây sát thương và làm ngắt quãng các kỹ năng niệm chú. Luồng năng lượng tàn dư tạo nên một lớp lá chắn quanh hắn, giúp hấp thụ sát thương phép nhận phải.","Nội tại: Các đòn đánh thường của Kassadin hồi lại gây thêm sát thương phép. Kích hoạt: Đòn đánh kế tiếp của Kassadin gây thêm một lượng lớn sát thương phép và giúp hồi lại Năng lượng.","Kassadin hút năng lượng từ những phép tung ra từ xung quanh. Khi tích tụ xong, Kassadin có thể sử dụng Áp Suất Hư Không để gây sát thương và làm chậm kẻ địch theo hình nón trước mặt hắn.","Kassadin dịch chuyển đến vị trí gần bên gây sát thương lên các kẻ địch xung quanh. Sử dụng Hư Vô Bộ Pháp nhiều lần trong thời gian ngắn sẽ làm hao tổn thêm năng lượng, nhưng bù lại gây thêm sát thương."]],"katarina":["Katarina là sát thủ đẳng cấp nhất Noxus với sự quyết đoán khi phân xử nhưng máu lạnh trên chiến trường. Là con gái cả của Đại tướng Du Couteau huyền thoại, cô được biết đến với những đòn kết liễu kẻ địch dứt khoát và nhanh nhạy ngay khi chúng không lường trước. Tham vọng mãnh liệt đã thôi thúc cô nhắm tới những mục tiêu được bảo vệ cẩn mật dù có nguy cơ đưa những người đồng đội vào thế nguy hiểm. Nhưng dù nhiệm vụ có ra sao, Katarina cũng sẽ không ngần ngại tung lưỡi dao bén sắc nhanh như bão tố của mình để kết liễu kẻ địch.",["Mỗi khi một tướng địch vừa bị Katarina gây sát thương chết đi, hồi chiêu còn lại của các kỹ năng của cô giảm mạnh.\nNếu Katarina nhặt một Phi Dao, cô dùng nó để chém vào tất cả kẻ địch gần đó, gây sát thương phép.","Katarina ném Phi Dao vào mục tiêu, nảy sang kẻ địch xung quanh trước khi cắm xuống đất.","Katarina tăng mạnh Tốc độ Di chuyển, đồng thời ném một Phi Dao lên không trung ở ngay vị trí hiện tại của mình.","Katarina bay đến chỗ mục tiêu, tấn công chúng nếu là kẻ địch, nếu không thì tấn công kẻ địch gần nhất.","Katarina trở thành một cơn lốc phi dao, gây sát thương phép cực lớn trong lúc vận sức vào ba tướng địch gần nhất."]],"kayle":["Là đứa con của một Thượng Nhân Targon trong thời kì Chiến Tranh Cổ Ngữ, Kayle tôn vinh những di sản của mẹ mình bằng cách chiến đấu vì công lý, trên đôi cánh rực cháy ngọn lửa thần thánh. Cô cùng người em gái song sinh Morgana bảo hộ vương quốc Demacia trong nhiều năm - cho đến khi Kayle bị ám ảnh bởi những khiếm khuyết của người phàm, và vĩnh viễn rời khỏi thế giới của họ. Dù vậy, truyền thuyết kể rằng lưỡi kiếm rực lửa của cô vẫn đang trừng trị những kẻ bất xứng, và người đời vẫn hi vọng rằng cô sẽ trở lại vào một ngày nào đó...",["Đòn đánh của Kayle được cường hóa khi cô lên cấp và cộng điểm kỹ năng. Đôi cánh của cô ngày một rực rỡ hơn, dần dần tăng Tốc độ Đánh, Tốc độ Di chuyển, tầm đánh, và bắn sóng lửa khi đánh.","Kayle triệu hồi thánh kiếm xuyên qua kẻ địch, gây sát thương, làm chậm và giảm chống chịu.","Được thiên giới ban phước, Kayle hồi máu và tăng Tốc độ Di chuyển cho bản thân cùng đồng minh gần nhất.","Nội tại: Thánh kiếm của Kayle, Thiên Đạo, gây thêm sát thương phép lên kẻ địch cô tấn công.\nKích hoạt: Đòn đánh kế tiếp của Kayle trừng phạt kẻ địch bằng lửa sao trời, gây thêm sát thương tùy theo máu đã mất của chúng.","Kayle khiến một tướng đồng minh bất tử và gọi Thượng Nhân Công Lý xuống thanh tẩy khu vực quanh người cô chọn."]],"kayn":["Môn đồ xuất sắc của ma thuật hắc ám, Sheida Kayn không ngừng chiến đấu để giành lấy định mệnh chân chính – để một ngày dẫn dắt Hội Bóng Tối thống trị Ionia. Hắn liều lĩnh sử dụng thanh vũ khí có tri giác Rhaast, mặc kệ việc nó liên tục gặm nhấm thể chất và tinh thần của mình. Sẽ chỉ có hai kết cục khả dĩ xảy ra: hoặc Kayn chiến thắng bằng ý chí sắt đá… hoặc lưỡi hái tà ác thôn tính hắn hoàn toàn, mở đường cho sự hủy diệt trên toàn Runeterra.",["Kayn sở hữu một vũ khí cổ đại và chiến đấu với Rhaast, gã darkin bên trong, để giành quyền kiểm soát. Hoặc Darkin sẽ thắng, hoặc Kayn sẽ làm chủ Rhaast và trở thành Sát Thủ Bóng Tối.\nDarkin: Hồi máu bằng một phần sát thương kỹ năng gây lên tướng.\nSát Thủ Bóng Tối: Gây thêm sát thương trong vài giây đầu giao tranh với tướng địch.","Kayn lướt tới sau đó quét lưỡi hai. Cả hai động tác đều gây sát thương.","Kayn sát thương và làm chậm các mục tiêu trên một đường thẳng.","Kayn có thể đi qua địa hình","Kayn nhập vào cơ thể một kẻ địch, gây sát thương cực lớn khi thoát ra."]],"kennen":["Không chỉ là một người gìn giữ cân bằng cho Ionia, Kennen còn là Yordle duy nhất trong hội Kinkou. Dù nhỏ bé và lông lá, cậu vẫn sẵn lòng xử lý mọi hiểm họa với phi tiêu sấm sét cùng lòng nhiệt huyết vô biên. Bên cạnh sư phụ Shen, Kennen tuần tra thế giới linh hồn, sử dụng năng lượng điện tàn phá để hạ gục kẻ địch.",["Kennen sẽ làm choáng kẻ địch có 3 cộng dồn Dấu Ấn Sấm Sét.","Kennen phóng ám khí vào kẻ địch, gây sát thương và khắc một Dấu Ấn Sấm Sét vào nạn nhân.","Đòn đánh của Kennen có thể gây thêm sát thương và khắc một Dấu Ấn Sấm Sét lên mục tiêu sau mỗi cú đánh, đồng thời hắn có thể kích hoạt kỹ năng này để sát thương và khắc thêm một Dấu Ấn Sấm Sét lên những nạn nhân đang bị khắc dấu ấn này.","Kennen biến thành dạng sét, có thể đi xuyên vật thể và đặt Dấu Ấn Sấm Sét. Trong dạng này, Kennen được tăng Tốc độ Di chuyển. Khi trở về dạng thường, Kennen được tăng tốc độ đánh.","Kennen triệu hồi một cơn bão tấn công ngẫu nhiên lên các tướng địch cạnh bên gây sát thương phép."]],"khazix":["Hư Không lớn dần, và Hư Không thích nghi - chân lý này không hiển hiện ở đâu rõ hơn Kha'Zix. Tiến hóa đã dẫn lối cho sinh vật đột biến này, một sinh vật sinh ra để sống sót và để tiêu diệt kẻ mạnh. Nếu gặp khó khăn khi làm điều đó, nó lại phát triển những phương thức hữu hiệu hơn để khắc chế và hạ gục con mồi. Mới đầu chỉ là một quái thú vô tri, trí thông minh của Kha'Zix đã tăng tiến theo mỗi lần đổi dạng. Giờ, sinh vật này lên kế hoạch cho mỗi cuộc săn, thậm chí còn biết tận dụng nỗi sợ nó tiêm nhiễm vào nạn nhân.",["Kẻ địch gần đó đang bị Cô lập khỏi đồng minh sẽ bị đánh dấu. Kỹ năng của Kha'Zix tương tác với mục tiêu bị Cô lập.\nKhi Kha'Zix không bị kẻ địch nhìn thấy, nó nhận được Hiểm Họa Tiềm Tàng, khiến đòn đánh kế tiếp lên tướng địch gây thêm sát thương phép và làm chậm vài giây.","Gây sát thương vật lý lên mục tiêu. Sát thương tăng thêm với mục tiêu bị Cô Lập. Nếu chọn Tiến Hóa Vuốt Kiếm, nó hoàn lại một phần hồi chiêu khi dùng lên mục tiêu bị Cô Lập. Kha'Zix cũng được tăng tầm đánh và tầm Nếm Mùi Sợ Hãi.","Kha'Zix phóng gai nổ gây sát thương vật lý lên kẻ địch trúng phải. Kha'Zix được hồi máu nếu đứng trong bán kính vụ nổ. Nếu chọn Tiến Hóa Chùm Gai, Gai Hư Không bắn ba gai theo hình nón, làm chậm kẻ địch trúng phải, và lộ diện tướng địch trúng phải trong 2 giây. Mục tiêu Cô Lập bị làm chậm nhiều hơn.","Kha'Zix nhảy tới một khu vực, gây sát thương vật lý khi tiếp đất. Nếu hắn chọn Tiến Hóa Tung Cánh, tầm Nhảy được tăng lên và hồi chiêu được hoàn lại khi hạ gục hoặc hỗ trợ hạ gục tướng.","Mỗi cấp cho phép Kha'Zix tiến hóa một trong các kỹ năng, cho chúng hiệu ứng cộng thêm độc đáo. Khi tấn công, Kha'Zix trở nên Vô Hình, kích hoạt Hiểm Họa Tiềm Tàng và tăng Tốc độ Di chuyển. Nếu chọn Tiến Hóa Ẩn Thân, Đột Kích Hư Không tăng thêm thời gian Vô Hình, và có thêm lần sử dụng."]],"kindred":["Kindred đại diện cho hai mặt của cái chết: chia li, nhưng không bao giờ tử biệt. Mũi tên của Cừu nhanh chóng kết thúc những kẻ sớm đã chấp nhận số phận. Sói săn đuổi kẻ nào dám chạy trốn, dùng hàm răng dũng mãnh của nó ngoạm chặt và kết liễu kẻ thù. Mặc dù bản chất của Kindred thể hiện xuyên suốt các vùng đất nơi Runeterra là khác nhau, nhưng mọi người phàm đều phải chọn bộ mặt thật cho cái chết của chính mình.",["Kindred có thể đánh dấu mục tiêu để Đi Săn. Hoàn thành Cuộc Săn sẽ cường hóa vĩnh viễn các kỹ năng cơ bản của Kindred. Cứ mỗi 4 Cuộc Săn thành công, tầm đánh cơ bản của Kindred sẽ được tăng.","Kindred nhào lộn và bắn ra ba mũi tên vào các đối tượng gần nhất.","Sói cuồng loạn, tấn công các kẻ địch xung quanh. Cừu tích cộng dồn khi di chuyển và tấn công. Khi tích đủ, đòn đánh kế tiếp của Cừu hồi máu cho Kindred.","Cừu thận trọng bắn ra một mũi tên, làm chậm mục tiêu. Nếu Cừu tấn công mục tiêu thêm 2 lần nữa, đòn đánh thứ ba của cô sẽ điều khiển Sói nhảy thẳng vào mục tiêu, gây ra một lượng lớn sát thương.","Cừu ngăn cản mọi sinh vật sống trong khu vực khỏi cái chết. Cho đến khi hiệu ứng kết thúc, sẽ không ai có thể chết cả. Khi kết thúc, các mục tiêu sẽ được hồi máu."]],"kled":["Một chiến binh liều lĩnh và cộc tính, gã yordle Kled là hiện thân của lòng dũng cảm điên cuồng đến từ đế chế Noxus. Hắn được lòng những người lính, nhưng lại luôn bị các sĩ quan nghi ngờ và bị giới quý tộc ghét bỏ. Nhiều người kể rằng Kled đã chiến đấu trong mọi chiến dịch mà quân đoàn từng phát động, giành lấy mọi danh hiệu quân đội, và chưa bao giờ lùi bước khỏi một trận chiến. Dù tính xác thực của những câu chuyện ấy thường bị đặt dấu hỏi, song một phần trong huyền thoại về hắn luôn y hệt nhau: xung trận trên con chiến mã “không đáng tin cho lắm”, Skaarl, Kled chiến đấu để bảo vệ những gì thuộc về gã… và gom luôn những gì gã có thể gom.",["Con thú cưỡi tin cẩn của Kled, Skaarl, sẽ chịu sát thương thay hắn. Khi thanh máu Skaarl cạn kiệt, Kled sẽ xuống đi bộ.\nTrong lúc đi bộ, kỹ năng của Kled thay đổi và hắn gây ít sát thương lên tướng hơn. Kled có thể hồi lại can đảm cho Skaarl bằng cách chiến đấu chống kẻ thù. Khi có đủ can đảm, Kled có lại Skaarl với một phần lượng máu gốc.","Kled ném ra một bẫy gấu gây sát thương và bám lấy tướng địch. Nếu bị trói đủ lâu, nạn nhân sẽ chịu thêm sát thương vật lý và bị kéo lại gần hắn.\nKhi xuống thằn lằn, kỹ năng này được thay thế bằng Súng Lục Bỏ Túi, một phát súng tầm xa đẩy lùi Kled và hồi lại can đảm.","Kled được tăng mạnh tốc độ đánh trong bốn đòn tấn công. Đòn thứ tư gây thêm sát thương.","Kled lướt tới, gây sát thương vật lý và được tăng tốc trong thoáng chốc. Kled có thể tái kích hoạt kỹ năng để lao trở lại mục tiêu đầu, gây sát thương lần nữa.","Kled và Skaarl xông tới một vị trí, để lại phía sau con đường tăng tốc đồng thời có được lớp lá chắn. Skaarl đâm sầm vào tướng địch đầu tiên gặp phải."]],"kogmaw":["Chui ra từ một vùng Hư Không xâm thực, sâu giữa Icathia hoang vu, Kog'Maw là một sinh vật tò mò nhưng thối rữa với cái miệng há rộng đầy chất ăn mòn. Sinh vật đặc biệt này cần phải gặm nhấm bất kỳ thứ gì trong tầm với để thực sự hiểu rõ nó. Dù bản chất không xấu, nhưng chính sự ngây thơ của Kog'Maw mới là mối nguy hiểm, bởi nó thường thỏa mãn cơn đói điên cuồng không chỉ để tồn tại, mà còn để thỏa mãn trí tò mò không có điểm dừng.",["4 giây sau khi bị hạ gục, Kog'Maw phát nổ, gây sát thương chuẩn lên kẻ địch xung quanh.","Kog'Maw phun ra chất dịch ăn mòn gây sát thương phép đồng thời làm giảm giáp và kháng phép của mục tiêu trong thời gian ngắn. Kog'Maw cũng được tăng thêm tốc độ đánh.","Kog'Maw được tăng tầm đánh, và đòn đánh của nó gây sát thương phép %i:OnHit% Trên Đòn Đánh tính theo phần trăm máu tối đa của mục tiêu.","Kog'Maw phun một luồng chất độc gây sát thương tất cả kẻ địch trúng phải và để lại một vệt dài làm chậm các kẻ địch đứng trên đó.","Kog'Maw bắn ra đạn sinh học với khoảng cách rất xa gây sát thương phép (tăng mạnh trên kẻ địch còn ít máu) và làm lộ diện các mục tiêu không tàng hình. Ngoài ra, bắn Pháo Sinh Học liên tục trong khoảng thời gian ngắm sẽ tiêu hao thêm Năng lượng."]],"leblanc":["Bí ẩn với cả những thành viên khác của giáo phái Hoa Hồng Đen, LeBlanc là một trong số nhiều cái tên của người phụ nữ đã thao túng các sự kiện từ ngày đầu của Noxus. Sử dụng ma thuật để tạo ra bản sao của chính mình, nữ phù thủy này có thể xuất hiện trước bất kỳ ai, ở bất kỳ đâu, và thậm chí là tại nhiều nơi cùng lúc. Luôn âm mưu gì đó ngoài tầm nhận thức, động cơ thực sự của LeBlanc cũng khó nắm bắt y như nhân dạng của ả vậy.",["Khi Máu LeBlanc xuống dưới 40%, cô trở nên vô hình trong 1 giây và tạo một Ảo Ảnh không gây sát thương tồn tại tối đa 8 giây.","LeBlanc bắn dấu ấn ra, gây sát thương và đánh dấu mục tiêu trong 3,5 giây. Dùng kỹ năng sát thương mục tiêu bị đánh dấu sẽ kích nổ ấn, gây thêm sát thương. Nếu một trong hai sát thương này tiêu diệt mục tiêu, LeBlanc được hoàn trả Năng Lượng tiêu hao và thời gian hồi chiêu còn lại của kỹ năng này.","LeBlanc lướt tới vị trí chỉ định, gây sát thương lên các đơn vị gần đó. Trong 4 giây tiếp theo, cô có thể kích hoạt Biến Ảnh lần nữa để trở về điểm bắt đầu.","LeBlanc tung sợi xích ảo thuật vào vị trí chỉ định. Nếu trúng một đơn vị địch, nó sẽ xích lấy chúng. Nếu mục tiêu vẫn bị xích trong 1.5 giây, LeBlanc trói chân kẻ đó và gây thêm sát thương.","LeBlanc tạo một bản sao dùng phiên bản mô phỏng một trong các kỹ năng cơ bản."]],"leesin":["Bậc thầy võ thuật cổ truyền xứ Ionia, Lee Sin, là một chiến binh sử dụng tinh hoa của loài rồng để đối mặt với bất kỳ thử thách nào. Dù bị mất đi thị giác nhiều năm trước, vị thầy tu này vẫn tiếp tục sứ mệnh cả đời bảo vệ quê hương Ionia chống lại bất kỳ ai dám phá vỡ sự cân bằng thiêng liêng của nơi đây. Những kẻ đánh giá thấp phong thái thiền định của anh sẽ sớm phải chịu những cú đấm bỏng cháy và cả những cú đá xoáy rực lửa.",["Sau khi Lee Sin sử dụng một kỹ năng, 2 đòn đánh kế tiếp tăng Tốc độ Đánh và hồi Nội Năng.","Sóng Âm: Lee Sin chưởng ra một luồng sóng nghịch âm nhằm định vị mục tiêu, gây sát thương vật lí lên kẻ địch đầu tiên trúng phải. Nếu Sóng Âm trúng mục tiêu, Lee Sin có thể sử dụng Vô Ảnh Cước trong 3 giây kế tiếp.\nVô Ảnh Cước: Lee Sin phóng tới kẻ địch trúng phải Sóng Âm, gây sát thương vật lý dựa trên máu đã mất của mục tiêu.","Hộ Thể: Lee Sin lướt đến một đơn vị đồng minh, bảo vệ bản thân khỏi sát thương. Nếu mục tiêu là tướng đồng minh, cả hai đều được bảo vệ. Sau khi sử dụng Hộ Thể, Lee Sin có thể niệm Kiên Định.\nKiên Định: Sự dày công khổ luyện giúp cho Lee Sin tung hoành trên chiến trường. Lee Sin nhận Hút Máu Toàn Phần.","Địa Chấn: Lee Sin dậm xuống đất tạo sóng âm gây sát thương phép và làm lộ diện kẻ địch trúng phải. Nếu Địa Chấn đánh trúng một kẻ địch, Lee Sin có thể thi triển Dư Chấn.\nDư Chấn: Lee Sin làm tê liệt kẻ địch chịu sát thương từ Địa Chấn, làm giảm Tốc Độ Di Chuyển của chúng. Tốc Độ Di Chuyển sẽ hồi phục dần theo thời gian.","Lee Sin tung cước đá văng mục tiêu về phía sau, gây sát thương vật lí lên nạn nhân và bất cứ kẻ địch nào bị va phải. Những kẻ địch mà bị mục tiêu va phải trên đường bay sẽ bị hất văng lên không trung trong một thời gian ngắn. Chiêu thức này được truyền dạy bởi Jesse Perring, mặc dù Lee Sin không đá văng người chơi ra khỏi bản đồ."]],"leona":["Mang trong mình ngọn lửa mặt trời, Leona là chiến binh thánh chiến của Hội Solari, người đã bảo vệ Núi Targon bằng Thiên Đỉnh Kiếm và Khiên Mặt Trời. Làn da cô lấp lánh ánh tinh hỏa, còn đôi mắt rực sáng với sức mạnh của Thượng Giới. Khoác bộ áo giáp vàng cùng một lượng tri thức cổ xưa khổng lồ, Leona đem đến sự giác ngộ cho một số người, và cái chết cho một vài kẻ khác.",["Các kỹ năng sát thương đặt Ánh Sáng Mặt Trời lên kẻ địch trong 1.5 giây. Khi tướng đồng minh gây sát thương lên các mục tiêu này, họ kích phát Ánh Sáng Mặt Trời để gây thêm sát thương phép.","Leona đánh đòn tiếp theo bằng khiên của mình, gây thêm sát thương phép và làm choáng kẻ thù.","Leona nâng cao chiếc khiên giúp giảm sát thương nhận được và gia tăng Giáp và Kháng Phép. Khi hiệu ứng kết thúc lần đầu, nếu xung quanh có kẻ địch cô sẽ gây sát thương phép lên chúng và kéo dài thêm thời gian hiệu lực của hiệu ứng.","Leona phóng ra một lưỡi kiếm mang ánh sáng mặt trời, gây sát thương lên tất cả kẻ địch trên đường thẳng. Khi ánh sáng mờ dần, kẻ địch cuối cùng bị tác động sẽ bị giữ chân trong thời gian ngắn và Leona lướt đến cạnh bên mục tiêu.","Leona triệu hồi sức mạnh của thái dương, gây sát thương lên những kẻ địch trong vùng ảnh hưởng. Những nạn nhân ở khu vực trung tâm sẽ bị choáng, còn những kẻ ngoài rìa sẽ bị làm chậm."]],"lillia":["Bẽn lẽn e thẹn, nàng tiên hươu Lillia lang thang nơi những khu rừng Ionia. Tránh né khỏi ánh mắt của người phàm—giống loài bí ẩn khiến cô sợ hãi nhưng cũng không khỏi bị cuốn hút—Lillia hy vọng rằng sẽ tìm được lý do vì sao những giấc mộng của họ lại không còn được truyền đến Cây Thần Mộng Mị cổ xưa. Mang theo trong tay chiếc mộc trượng ma thuật, cô nỗ lực tìm kiếm những giấc mơ ẩn giấu của nhân loại khắp Ionia. Chỉ như thế, nụ hoa Lillia mới có thể hé nở và giúp con người chinh phục nỗi sợ nhằm tìm thấy tia sáng rực rỡ bên trong họ.",["Tấn công tướng hoặc quái vật bằng kỹ năng sẽ gây thêm một lượng sát thương theo thời gian tương đương Máu tối đa của mục tiêu.","Nội tại sẽ cho phép Lillia nhận cộng dồn tăng Tốc độ Di chuyển mỗi khi tấn công kẻ địch với kỹ năng. Cô có thể kích hoạt để gây sát thương lên những kẻ địch cạnh bên, và gây thêm sát thương chuẩn lên kẻ địch ở ngoài rìa kỹ năng.","Lillia tấn công vào khu vực chỉ định ở gần, và gây lượng lớn sát thương tại điểm trung tâm.","Lillia đẩy hạt cây về phía trước, gây sát thương và làm chậm mục tiêu nó chạm vào. Nếu không trúng gì cả, nó sẽ tiếp tục lăn đến khi chạm vào tường hoặc mục tiêu nào đó.","Lillia khiến tất cả kẻ địch chịu ảnh hưởng bởi Phấn Hoa Mộng Mị trở nên Buồn Ngủ trước khi rơi vào giấc mộng. Những kẻ địch đó sẽ chịu thêm sát thương khi bị ép phải thức dậy."]],"lissandra":["Ma pháp của Lissandra có thể biến sức mạnh của băng tuyết thành một thứ gì đó đen tối và khủng khiếp. Với sức mạnh của thứ băng tuyết đen tối đó, cô ta không chỉ đóng băng mà còn đâm xuyên và nghiền nát những kẻ ngáng đường. Những cư dân phương Bắc, những kẻ lúc nào cũng khiếp sợ, gọi cô là ''Mụ Phù Thủy Băng''. Nhưng sự thật còn khủng khiếp hơn thế: Lissandra là một kẻ muốn thao túng tự nhiên và bao phủ thế giới này trong một kỉ băng hà.",["Khi một tướng địch chết gần chỗ Lissandra, chúng trở thành Nô Lệ Băng. Nô Lệ Băng làm chậm kẻ địch gần đó và vỡ tan sau ít lâu, gây sát thương phép lên các mục tiêu xung quanh.","Quẳng một cây thương băng đi, thứ sẽ tan vỡ khi tiếp xúc với một kẻ địch, gây sát thương phép và làm chậm Tốc độ Di chuyển. Những mảnh vỡ sẽ bay xuyên qua nạn nhân, gây sát thương tương tự lên những kẻ địch khác trúng phải.","Khiến những kẻ địch cạnh bên bị trúng băng giá, gây sát thương phép và trói chân các nạn nhân.","Lissandra tạo ra một vết cào băng giá gây sát thương phép. Tái kích hoạt kĩ năng sẽ biến Lissandra tới vị trí hiện tại của vết cào.","Nếu niệm lên một tướng địch, mục tiêu bị đông cứng và choáng. Nếu niệm lên Lissandra, cô tự bao phủ bản thân trong băng đen, hồi lại máu đồng thời trở nên không thể bị tổn thương hoặc bị chỉ định. Băng đen sau đó mọc ra từ mục tiêu, gây sát thương lên những kẻ địch và làm chậm Tốc độ Di chuyển."]],"locke":["Là một thầy trừ tà phóng đinh tinh thông các nghi thức cấm kỵ, Corvin Locke là hậu duệ của những kẻ nghiên cứu bí thuật Demacia. Sinh ra trong sự dối trá và đạo đức giả, anh sớm nhận ra rằng ác quỷ không phải là nguyên nhân gây ra sự tăm tối của nhân loại, mà chỉ là hậu quả sinh ra từ nó. Giờ đây, Locke xé toạc mọi linh hồn, phơi bày sự tăm tối của nó, với ý định biến thế giới thành một nơi trung thực hơn... từng bước, từng bước một qua việc diệt trừ ác quỷ.",["Các đòn đánh của Locke gây thêm sát thương phép khi đánh, tăng lên dựa trên lượng Máu đã mất của kẻ địch.","Locke chuẩn bị một bộ Đinh Hồn để ném, gây sát thương và đánh dấu kẻ địch trúng phải. Locke có thể tiêu hao các dấu ấn để gây thêm sát thương với các đòn đánh của mình.","Locke thiêu đốt linh hồn, nhận thêm Tốc Độ Đánh và Tốc Độ Di Chuyển, đồng thời tự gây sát thương lên bản thân. Khi hiệu ứng kết thúc, Locke sẽ hồi máu một phần sát thương mà anh ta nhận vào trong thời gian hiệu ứng.","Locke dịch chuyển đến một vị trí trước khi lao tới tấn công mục tiêu tiếp theo, gây sát thương lên kẻ địch bị lướt qua.","Locke ném một cổ vật trói buộc gây sát thương và có thể kết liễu kẻ địch trúng phải. Locke nhận thêm sức mạnh khi phong ấn các tướng địch."]],"lucian":["Lucian, Vệ Binh Ánh Sáng, là một thợ săn hồn ma và quỷ ám, anh sẵn sàng truy cùng diệt tận và hạ gục con mồi bằng cặp súng lục của mình. Sau khi hồn ma Thresh hạ sát vợ mình, Lucian đã dấn thân vào con đường báo thù - ngay cả khi cô sống lại thì cơn thịnh nộ của anh cũng không hề suy giảm. Tàn nhẫn và chuyên tâm, Lucian sẽ sẵn sàng làm mọi thứ để bảo vệ các sinh vật sống khỏi những nỗi kinh hoàng vốn đã chết từ lâu của Màn Sương Đen.",["Mỗi khi Lucian sử dụng kỹ năng, đòn đánh tiếp theo của anh sẽ bắn hai phát đạn Khi nhận được hồi máu hay tạo lá chắn từ đồng minh, hoặc khi một tướng địch gần đó bị làm bất động, hai đòn đánh tiếp theo của Lucian gây thêm sát thương phép.","Lucian bắn ra một tia sáng xuyên thấu qua mục tiêu.","Lucian bắn ra một viên đạn phát nổ thành hình sao, đánh dấu và làm lộ diện kẻ địch. Lucian được tăng Tốc độ Di chuyển về phía kẻ địch bị đánh dấu.","Lucian lướt đi một đoạn ngắn. Các đòn tấn công từ nội tại Xạ Thủ Ánh Sáng sẽ giảm thời gian hồi của Truy Cùng Diệt Tận.","Lucian phóng thích ra một luồng đạn từ vũ khí của mình."]],"lulu":["Pháp sư Yordle Lulu được biết đến với biệt tài tạo ra những ảo ảnh đẹp như mơ cùng những sinh vật huyền ảo mỗi bước chân lang thang khắp Runeterra cùng với người bạn đồng hành Pix của mình. Lulu định hình thực theo ý thích, bẻ cong kết cấu của thế giới và thứ những thứ cô xem là thế giới vật chất, trần tục này. Dù những người coi ma thuật của cô là phi tự nhiên, và tệ nhất là nguy hiểm, cô vẫn tin rằng mọi người đều có thể tận dụng được gì đó từ một chút phù phép.",["Pix bắn tia ma thuật mỗi khi tướng cậu đi theo tấn công 1 kẻ địch. Tia ma thuật đuổi theo mục tiêu nhưng có thể bị các đơn vị khác chặn lại.","Pix và Lulu thay nhau bắn các tia chớp gây sát thương và làm chậm những kẻ địch trúng phải.","Nếu niệm lên một đồng minh, tăng cho họ Tốc độ Di chuyển trong một thời gian ngắn. Nếu niệm lên một kẻ địch, biến nạn nhân thành một sinh vật không thể tấn công hay niệm phép.","Nếu niệm lên đồng minh, Pix sẽ bám vào mục tiêu và tạo lá chắn đồng thời hỗ trợ các đòn tấn công của họ. Nếu niệm lên kẻ địch, Pix sẽ bám vào nạn nhân và sát thương chúng, ngoài ra nó còn làm lộ diện kẻ địch với cả đội của bạn.","Lulu hóa lớn một đồng minh, hất kẻ địch xung quanh mục tiêu lên không đồng thời tăng cho mục tiêu một lượng máu lớn. Trong vòng vài giây kế tiếp, đơn vị đồng minh đó sở hữu hào quang làm chậm kẻ địch xung quanh."]],"lux":["Luxanna Crownguard đến từ một vương quốc xa lạ, Demacia, nơi người đời coi khả năng ma thuật là nỗi sợ và nghi kỵ nó. Lo sợ bị phát hiện và lưu đày vì sở hữu khả năng điều khiển ánh sáng theo ý muốn, cô lớn lên trong nỗi lo lắng và buộc phải giữ bí mật về nó để bảo toàn vị thế của gia tộc. Tuy nhiên, sự lạc quan và yêu đời của Lux đã giúp cô nắm bắt được tài năng độc nhất này và bí mật sử dụng nó để phục vụ quê hương mình.",["Các kỹ năng sát thương của Lux phủ năng lượng lên kẻ địch trong một vài giây. Đòn đánh kế tiếp của Lux đốt cháy năng lượng này, gây thêm sát thương (tùy theo cấp của Lux) lên mục tiêu.","Lux phóng ra một quả cầu ánh sáng làm trói chân và gây sát thương tối đa 2 mục tiêu.","Lux ném chiếc gậy phép của mình làm bẻ cong tia sáng quanh các đơn vị đồng minh chạm phải, bảo vệ họ khỏi sát thương nhận phải.","Bắn một vòng xoáy năng lượng đến vị trí đã chọn, làm chậm kẻ địch cạnh bên. Lux có thể kích nổ gây sát thương tại vị trí đó.","Sau khi tích tụ năng lượng, Lux bắn một dải sáng gây sát thương lên tất cả mục tiêu trong vùng ảnh hưởng. Ngoài ra tuyệt chiêu này còn kích hoạt nội tại của Lux và đặt lại thời gian bùa hại Chớp Lửa Soi Rọi trên mục tiêu."]],"malphite":["Là một sinh vật khổng lồ được tạo nên từ những tảng đá sống, Malphite chật vật duy trì trật tự nơi một thế giới hỗn loạn thường khi. Nó sử dụng sức mạnh nguyên tố vô biên để duy trì và bảo vệ giống loài nhưng cuối cùng đại bại. Giờ đây, Malphite, sinh vật sống sót duy nhất sau sự hủy diệt đã chọn cách chịu đựng tính khí mềm yếu quá đỗi thất thường của người dân Runeterra để tìm ra một vị trí mới xứng đáng với danh xưng sinh vật cuối cùng trong giống loài của mình.",["Malphite được bảo hộ bởi một lớp đá có thể hấp thụ sát thương bằng 10% máu tối đa của hắn. Nếu Malphite không bị tấn công trong vòng vài giây, hiệu ứng tự động lặp lại.","Malphite bắn một mảnh vỡ đất đá đến kẻ địch, gây sát thương khi va chạm và đánh cắp Tốc độ Di chuyển của chúng trong 3 giây.","Malphite dậm mạnh đến nỗi tạo ra một vụ nổ sóng âm. Trong vài giây tới, đòn đánh gây ra dư chấn trước mặt nó.","Malphite đập mạnh xuống đất, sóng chấn động từ điểm va chạm phát ra gây sát thương phép tỉ lệ theo Giáp và giảm Tốc độ Đánh của kẻ địch đi trong một khoảng ngắn.","Malphite phi mình vào khu vực chỉ định với tốc độ cao, gây sát thương và hất tung kẻ địch lên không."]],"malzahar":["Nhà tiên tri hết lòng cống hiến để đạt được sự hợp nhất của mọi sinh mệnh, Malzahar, thực sự tin rằng Hư Không vừa xuất hiện này chính là con đường duy nhất cứu rỗi Runeterra. Trên sa mạc Shurima hoang vắng, hắn đi theo giọng nói thì thầm trong đầu, thẳng đến Icathia cổ xưa. Giữa đống đổ nát của vùng đất, hắn nhìn thẳng vào trái tim tăm tối của Hư Không và được ban tặng sức mạnh cùng mục đích mới. Malzahar giờ coi mình là người dẫn dắt, được trao quyền để đưa kẻ khác đến với Hư Không... hoặc để giải phóng lũ sinh vật đang trú ngụ bên dưới đáy sâu ra ngoài.",["Khi không chịu sát thương hoặc bị khống chế trong một khoảng thời gian, Malzahar nhận lượng lớn giảm sát thương và miễn nhiễm với hiệu ứng khống chế. Hiệu ứng sẽ kéo dài trong một khoảng thời gian ngắn sau khi chịu sát thương.","Malzahar mở ra hai cánh cổng đến Hư Không. Sau thoáng chốc, chúng bắn ra những tia gây sát thương phép và làm câm lặng tướng địch.","Malzahar triệu hồi Bọ Hư Không để tấn công các kẻ địch gần đó.","Malzahar ếm lên tâm trí mục tiêu những ảo ảnh ghê rợn và tàn độc, gây sát thương theo thời gian. Dùng các kỹ năng khác của Malzahar lên mục tiêu sẽ làm mới lại thời gian ám ảnh.\nNếu mục tiêu bị hạ trong lúc đang chịu ám ảnh, nó chuyển sang kẻ địch gần đó và Malzahar được hồi lại Năng lượng. Bọ Hư Không ưu tiên tấn công những đơn vị bị ám ảnh.","Malzahar vận dụng sức mạnh của Hư Không, áp chế tướng địch trong một vùng năng lượng độc hại gây sát thương."]],"maokai":["Maokai là khổng-lồ-cây đầy giận dữ chiến đấu chống đám quái vật phi tự nhiên trên Quần Đảo Bóng Đêm. Sau khi một thảm họa ma thuật phá hủy quê nhà, nó may mắn sống sót nhờ nguồn nước sinh mệnh ngấm trong lõi cây và trở thành kẻ phục hận. Tinh linh hiền hòa trước đây biến mất, Maokai giờ vật lộn trong cuồng nộ để trục xuất tai ương tử linh khỏi Quần Đảo Bóng Đêm và phục hồi vẻ đẹp ngày nào cho nơi nó đang cư ngụ.",["Đòn đánh của Maokai sẽ hồi máu cho ông và gây thêm sát thương, hiệu ứng này có hồi chiêu tương đối. Mỗi khi Maokai sử dụng chiêu thức hoặc trúng chiêu thức từ đối thủ, hồi chiêu này sẽ được giảm.","Maokai đẩy lùi kẻ địch gần đó bằng sóng chấn động, gây sát thương phép và làm chậm.","Maokai biến thành một đám rễ di động, trở nên không thể bị chỉ định và lướt tới mục tiêu. Khi đến nơi, nó trói chân mục tiêu.","Maokai ném một chồi non đến vùng chỉ định để cảnh giới. Hiệu quả hơn khi ném vào bụi.","Maokai triệu hồi một bức tường cây khổng lồ từ từ tiến tới, gây sát thương và trói chân mọi kẻ địch trên đường."]],"masteryi":["Master Yi đã rèn luyện cơ thể và mài giũa trí óc để có thể đưa suy nghĩ và hành động gần như hòa làm một. Tuy với anh bạo lực là giải pháp cuối cùng cho mọi chuyện, nhưng mỗi khi cần ra tay, lưỡi kiếm thanh thoát và sắc lẹm của Yi đều xử lý và kết thúc mọi chuyện vô cùng nhanh gọn. Là một trong những môn đồ cuối cùng của võ phái Wuju xứ Ionia, Yi dành cả đời để tiếp nối di sản ấy— bằng cách dùng Thất Kính Thấu Thị để kiếm tìm những môn đồ tài năng và xứng đáng nhất.",["Sau vài đòn đánh liên tiếp, Master Yi chém hai lần liên tiếp.","Master Yi bay khắp chiến trường với tốc độ lóa mắt, gây sát thương vật lý lên nhiều kẻ địch, đồng thời trở nên không thể bị chỉ định. Tuyệt Kỹ Alpha có thể chí mạng và gây thêm sát thương vật lý lên quái. Đánh thường giảm hồi chiêu Tuyệt Kỹ Alpha","Master Yi nhập thiền, hồi Máu và giảm sát thương gánh chịu trong chốc lát. Ngoài ra, Master Yi sẽ nhận cộng dồn Chém Đôi và ngưng thời gian tác dụng còn lại của Kiếm Thuật Wuju và Chiến Binh Sơn Cước với mỗi giây thiền định.","Tăng thêm sát thương chuẩn cho đòn đánh thường.","Master Yi di chuyển với sự linh hoạt vô bì, tạm thời tăng Tốc độ Di chuyển và Tốc độ Đánh cũng như được miễn nhiễm làm chậm. Khi kích hoạt, hạ gục hoặc hỗ trợ kéo dài thời gian tác dụng của Chiến Binh Sơn Cước. Nội tại giảm hồi chiêu của các kỹ năng khác khi hạ gục hoặc hỗ trợ."]],"mel":["Mel Medarda chính là người thừa kế của dòng họ Medarda, từng là một trong những gia tộc quyền lực nhất Noxus. Cô sở hữu vẻ ngoài duyên dáng của một nữ quý tộc, nhưng ẩn sau đó là một chính trị gia tài ba, luôn nắm tường tận mọi thứ về tất cả những người cô gặp gỡ. Sau cuộc chạm trán với hội Hoa Hồng Đen bí ẩn, Mel đã khám phá ra chân tướng đằng sau sự lừa dối của mẹ cô và lần đầu tiên phải đối mặt với một tình huống nằm ngoài khả năng cô có thể kiểm soát. Với nguồn sức mạnh phép thuật mới được thức tỉnh, cô lên đường trở về nhà để tìm kiếm câu trả lời - và tuy rằng nhiều kẻ cố gắng dập tắt ánh sáng bên trong cô, tâm hồn cô vẫn luôn vô cùng kiên định.",["Mỗi khi sử dụng Kỹ Năng, Mel nhận thêm 3 tia năng lượng (tối đa 9 tia) cho đòn đánh kế tiếp.\nKhi Mel gây sát thương bằng kỹ năng hoặc đòn đánh, cô đặt hiệu ứng Áp Đảo lên kẻ địch, có thể cộng dồn vô hạn. Nếu kẻ địch bị Mel đánh trúng đã tích đủ sát thương Áp Đảo, số cộng dồn sẽ được tiêu hao để kết liễu mục tiêu.","Mel bắn ra hàng loạt tia năng lượng phát nổ xung quanh một vị trí chỉ định, liên tục gây sát thương lên các kẻ địch trong khu vực này.","Mel tạo một rào chắn xung quanh bản thân giúp phản lại đường đạn phe địch về phía kẻ tấn công, ngăn cô nhận sát thương, đồng thời cho cô thêm tốc độ di chuyển.","Mel bắn một quả cầu rực sáng về phía trước, trói chân những kẻ ở chính giữa, đồng thời làm chậm và gây sát thương theo thời gian lên kẻ địch xung quanh nó.","Mel ra đòn lên tất cả kẻ địch bị đánh dấu Áp Đảo bất kể khoảng cách của chúng, gây thêm sát thương với mỗi cộng dồn Áp Đảo.\nSát thương Áp Đảo sẽ tăng theo cấp của Nhật Thực Hoàng Kim."]],"milio":["Milio là một cậu bé nhân hậu sinh ra và lớn lên tại Ixtal. Dù còn rất trẻ, nhưng cậu đã làm chủ ngọn lửa cũng như khám phá ra nguyên lý mới: ngọn lửa dịu êm. Với sức mạnh mới khám phá của mình, Milio muốn giúp gia đình thoát khỏi cảnh lưu đầy bằng cách gia nhập Yun Tal, giống như bà của cậu đã từng làm. Sau hành trình dài xuyên qua những khu rừng Ixtal tới thủ đô của Ixaocan, Milio đã sẵn sàng đối mặt với thử thách Vidalion và gia nhập Yun Tal mà không hề hay biết điều nguy hiểm nào đang chờ đợi phía trước.",["Các kỹ năng của Milio phù phép cho đồng minh khi chạm vào họ, khiến đòn đánh tiếp theo của đồng minh gây thêm sát thương và thiêu đốt mục tiêu.","Sút một quả bóng đẩy lùi kẻ địch. Quả bóng nảy về hướng kẻ địch, gây sát thương và làm chậm kẻ địch trong vùng ảnh hưởng khi va chạm.","Tạo một vùng cường hóa có khả năng hồi máu và tăng Tầm Đánh cho các đồng minh ở bên trong. Vùng này sẽ bám theo đồng minh đứng gần vị trí thi triển nhất.","Milio tạo lá chắn cho một đồng minh, tăng Tốc Độ Di Chuyển của đồng minh đó trong thời gian ngắn. Kĩ năng này có 2 tích trữ.","Milio giải phóng một đợt sóng lửa trị thương có khả năng hồi máu và loại bỏ hiệu ứng khống chế cho đồng minh trong phạm vi."]],"missfortune":["Sarah Fortune nổi bật hơn hẳn giữa đám tội phạm khét tiếng của thành phố cảng Bilgewater vì nhan sắc mỹ miều nhưng lại khiến người khác khiếp sợ vì sự máu lạnh và tàn nhẫn của mình. Khi còn bé, cô đã chứng kiến vua hải tặc Gangplank sát hại gia đình mình. Hàng năm sau, cô đã tàn bạo thổi tung chiến hạm của hắn khi hắn vẫn còn trên boong để trả thù cho những gì đã xảy ra. Chẳng ai dám đánh giá thấp cô vì không ai muốn đụng độ với một đối thủ mưu mẹo và khó đoán... với nhiều khả năng là sẽ phải \"găm\" một hai viên đạn vào bụng.",["Miss Fortune gây thêm sát thương vật lý mỗi khi đánh thường một mục tiêu mới.","Miss Fortune bắn một viên đạn, gây sát thương lên mục tiêu đầu tiên và kẻ địch đứng sau đó. Cả hai đều có thể phải nhận tác động của Đánh Yêu.","Miss Fortune nhận thêm Tốc độ Di chuyển khi không bị tấn công. Kĩ năng này có thể được kích hoạt để tăng Tốc độ Đánh trong một khoảng thời gian. Khi đang hồi chiêu, Đánh Yêu giúp Sải Bước hồi lại nhanh hơn","Miss Fortune bắn một cơn mưa đạn vào một địa điểm, gây sát thương theo từng đợt lên những kẻ địch và làm chậm chúng.","Miss Fortune bắn liên tục hàng loạt đạn theo hình nón phía trước, gây một lượng sát thương lớn lên kẻ địch. Một đợt Bão Đạn có thể chí mạng."]],"mordekaiser":["Hai lần tử, ba lần sinh, Mordekaiser là tên chúa tể tàn bạo từ một kỷ nguyên xa xôi, nắm giữ tà thuật chiêu hồn để trói buộc các linh hồn vào kiếp nô lệ vĩnh cửu. Giờ thì ít ai còn nhớ những cuộc chinh phục thời đầu hay giới hạn sức mạnh của hắn nằm ở đâu—nhưng vẫn còn đó một vài linh hồn cổ xưa ghi khắc nỗi kinh hoàng này, và họ khiếp sợ cái ngày hắn trở lại thống trị cả người sống lẫn kẻ chết.",["Mordekaiser tạo ra một vùng sát thương mạnh mẽ và được tăng Tốc độ Di chuyển sau khi tung 3 đòn đánh hoặc kỹ năng lên tướng hoặc quái rừng.","Mordekaiser đập chùy xuống đất, gây sát thương lên các kẻ địch trúng phải. Sát thương tăng nếu chỉ trúng một mục tiêu.","Mordekaiser tích sát thương hắn gây ra và gánh chịu để tạo một lá chắn. Hắn có thể tiêu thụ lá chắn để hồi máu.","Mordekaiser kéo tất cả kẻ địch trong một khu vực.","Mordekaiser kéo nạn nhân vào không gian khác, đánh cắp một phần chỉ số. Nếu hạ gục mục tiêu, hắn giữ chỉ số đó đến khi mục tiêu hồi sinh."]],"morgana":["Bị giằng xé giữa quyền năng thần thánh và thân xác phàm trần, Morgana đã trói buộc đôi cánh của mình để chọn lấy nhân tính, và chọn cách giáng nỗi đau, sự cay đắng của bản thân lên những kẻ bất trung và biến chất. Cô mặc kệ những luật lệ hay truyền thống mà cô cho rằng bất công, và chính bên trong bóng tối nơi Demacia, cô chiến đấu vì sự thật—dù những kẻ khác luôn muốn kiểm soát nó—với những tấm khiên, hay những sợi xích làm từ lửa bóng tối. Trên tất cả mọi thứ, Morgana thật sự tin rằng những kẻ bị vương quốc trục xuất, hay những tên ngoại tặc một ngày nào đó sẽ trỗi dậy.",["Morgana hút hồn từ kẻ địch, hồi lại máu khi gây sát thương lên tướng, lính to, và quái rừng vừa và lớn.","Morgana trói chân một kẻ địch và gây sát thương phép.","Morgana tạo một vùng đất bị nguyền rủa gây sát thương kẻ địch đứng trong đó. Sát thương tăng theo máu đã mất.","Morgana tạo khiên cho một đồng minh giúp chặn sát thương phép và miễn nhiễm khống chế.","Morgana giải phóng sức mạnh Thiên Giới bên trong cô, mở rộng đôi cánh và bay lên không trung. Cô kết nối những sợi xích hắc ám vào những tướng địch xung quanh, nhận thêm Tốc Độ Di Chuyển. Sợi xích làm chậm và gây một lượng sát thương ban đầu, và sau một khoảng trễ, nó sẽ làm choáng những kẻ địch không thể thoát ra."]],"naafiri":["Những tiếng tru đồng thanh vang vọng khắp các cồn cát ở Shurima. Đây chính là âm thanh của những đàn chó săn sa mạc, loài thú săn mồi theo bầy đàn khát máu và luôn tranh giành quyền săn mồi trên vùng đất cằn cỗi này. Trong số đó, tồn tại một đàn thống trị tất cả, vì động lực của chúng không bắt nguồn từ bản năng săn mồi, mà từ sức mạnh cổ xưa của tộc Darkin.",["Naafiri triệu gọi bầy đàn để tấn công mục tiêu bằng đòn đánh và kỹ năng của ả.","Naafiri phóng tối đa 2 con dao găm, gây chảy máu trên mỗi dao hoặc gây sát thương cộng thêm trên mỗi dao nếu mục tiêu đã bị chảy máu.\nBầy Đàn sẽ nhảy tới tấn công tướng hoặc quái vật đầu tiên bị trúng kỹ năng này.","Naafiri trở nên Không Thể Bị Chỉ Định, cường hóa đàn và triệu hồi thêm bầy đàn, đồng thời nhận thêm Tốc Độ Di Chuyển và Sức Mạnh Công Kích.","Naafiri lao tới và gây sát thương lên kẻ địch trong phạm vi xung quanh ả, triệu gọi bầy đàn quay về và hồi đầy máu cho chúng.","Naafiri cùng bầy đàn lao tới một tướng địch và gây sát thương. Naafiri làm lộ diện những kẻ địch ở gần nếu ả tham gia hạ gục và có thể tái kích hoạt Kỹ Năng này một lần. Lần thi triển thứ hai sẽ cho một lá chắn."]],"nami":["Cô nàng vastaya trẻ ương ngạnh nơi đại dương Nami là người đầu tiên trong giống loài của mình rời bỏ đại dương và liều mình tiến vào đất liền khi hiệp ước xa xựa của họ với tộc Targon bị phá vỡ. Không còn lựa chọn nào khác, cô tự mình dấn thân hoàn thành nghi lễ thiêng liêng để đảm bảo sự an toàn của dân tộc. Giữa những hỗn loạn của thời đại mới, Nami đối mặt với tương lai bất định bằng quyết tâm và một chút ngoan cố, sử dụng cây trượng Kẻ Hiệu Triệu Thủy Triều để gọi ra sức mạnh của chính đại dương.",["Khi Kỹ năng của Nami trúng tướng đồng minh, họ sẽ nhận thêm Tốc độ Di chuyển trong một khoảng ngắn.","Bắn một cái bong bóng khổng lồ vào điểm đã chọn, gây sát thương và làm choáng tất cả nạn nhân trúng phải.","Phóng ra một luồng nước nảy giữa đồng minh và kẻ địch, hồi máu cho đồng minh và sát thương kẻ địch.","Cường hóa một tướng đồng minh trong thoáng chốc, khiến các đòn đánh và kỹ năng của mục tiêu gây thêm sát thương phép và làm chậm mục tiêu.","Tạo ra một cơn Sóng Thần khổng lồ hất văng lên không, làm chậm, và sát thương các kẻ địch trúng phải. Tướng đồng minh đứng trong phạm vi của Sóng Thần sẽ được nhận hiệu ứng Dậy Sóng gấp 2 lần."]],"nasus":["Nasus là một anh hùng vĩ đại, người sở hữu đầu chó thân người - giống như những vị anh hùng thần thánh từng được người dân Shurima tôn kính. Với sự thông minh của mình, ngài chính là hộ thần của tri thức, là một quân sư chiến lược tài ba, trí tuệ của ngài chính là thứ đã dẫn dắt đế chế vĩ đại Shurima trong nhiều thế kỷ. Sau khi lễ Thăng Hoa của Azir thất bại, Nasus trở thành một huyền thoại, nhưng cũng mất đi danh phận và trở thành kẻ lưu vong. Giờ đây khi Đĩa Mặt Trời một lần nữa trỗi dậy, ngài đã quay trở lại, để đảm bảo rằng nó sẽ không bao giờ rơi xuống như trước đây",["Nasus hút năng lượng tinh thần của đối thủ, cho ông thêm Hút Máu.","Nasus tấn công kẻ địch, gây sát thương và cường hóa sức mạnh của các cú Quyền Trượng Linh Hồn về sau nếu ông hạ gục được mục tiêu.","Nasus làm lão hóa mục tiêu, khiến nạn nhân bị giảm Tốc độ Di chuyển và Tốc độ Đánh theo thời gian.","Nasus tạo ra một ngọn lửa tâm linh tại vị trí đã chọn, gây sát thương và làm giảm Giáp của những kẻ địch đứng trên đó.","Nasus giải phóng sức mạnh tối thượng từ bão cát, liên tục sát thương kẻ địch ở gần. Trong thời gian hiệu lực, ông nhận thêm Máu, Tầm Đánh, gây sát thương lên kẻ địch ở gần, và hồi chiêu của Quyền Trượng Linh Hồn được giảm, cũng như được nhận thêm Giáp và Kháng Phép."]],"nautilus":["Một truyền thuyết biệt lập cổ xưa như những cái cầu tàu đầu tiên đắm chìm xuống đáy Bilgewater, kể về gã khổng lồ mang giáp Nautilus không ngừng lang thang trong vùng nước tối ngoài khơi Quần Đảo Lửa Xanh. Bị điều khiển bởi sự phản bội ngày trước, gã luôn ra tay không một lời cảnh báo, vung cái mỏ neo to tướng của gã cứu lấy kẻ khốn khổ, và kéo lũ rác rưởi tham lam xuống cõi diệt vong. Người ta kể rằng gã đến để giải quyết những kẻ quên trả \"tiền lễ Bilgewater\", để kéo chúng xuống tận cùng những cơn sóng cùng gã--như một lời nhắc nhở đanh thép rằng không một ai có thể thoát khỏi vực thẳm.",["Đòn đánh đầu tiên của Nautilus lên mục tiêu gây thêm sát thương vật lý và trói chân chúng trong thoáng chốc.","Nautilus ném mỏ neo về phía trước. Nếu va chạm với tướng, nó sẽ kéo mục tiêu và Nautilus lại với nhau, gây sát thương phép. Nếu va chạm với địa hình, nó sẽ kéo Nautilus đến đó.","Nautilus nhận một Lá chắn tạm thời. Khi còn tồn tại, Đòn đánh của Nautilus sẽ gây sát thương theo thời gian lên mục tiêu và cả những kẻ địch xung quanh.","Nautilus dậm xuống đất và tạo ra ba đợt sóng địa chấn xung quanh bản thân. Mỗi lần đều gây sát thương và làm chậm kẻ địch.","Nautilus bắn ra một cơn sóng chấn động xuống mặt đất đuổi theo kẻ địch. Cơn sóng này sẽ phá nát mặt đất phía trên, hất văng kẻ địch lên trời. Khi đuổi kịp đối phương, cơn sóng bùng nổ, hất mục tiêu lên không và làm choáng chúng."]],"neeko":["Xuất thân từ một bộ tộc vastaya đã biến mất từ lâu, Neeko có thể hòa lẫn vào bất kỳ đâu nhờ khả năng ngụy trang hoàn hảo, thậm chí cô còn hấp thụ được cả trạng thái cảm xúc của người khác để phân biệt là bạn hay thù trong nháy mắt. Không ai dám chắc Neeko ở đâu - hoặc là ai, nhưng kẻ nào định gây hại cho cô sẽ nhanh chóng được chứng kiến sắc màu thực sự bên trong sinh vật nhỏ bé này, và chúng lãnh đủ sức mạnh từ ma thuật tinh linh nguyên thủy cô sở hữu.",["Neeko có thể cải trang thành một tướng đồng minh hoặc các đơn vị khác trên bản đồ. Nhận hiệu ứng bất động/khống chế, sử dụng kĩ năng gây sát thương, gây sát thương lên trụ địch khi không phải là tướng, hoặc hình dạng cải trang của bạn nhận sát thương tương đương với thanh máu của nó sẽ làm mất lớp cải trang.","Neeko ném ra một hạt giống gây sát thương phép thuật. Hạt giống sẽ phát nổ thêm một lần nữa mỗi khi trúng tướng hoặc hạ gục lính.","Neeko tự động gây thêm sát thương phép mỗi đòn đánh thứ ba, tăng nhẹ tốc độ di chuyển. Neeko có thể tạo ra một bản sao di chuyển theo hướng chỉ định và tái kích hoạt để thay đổi hướng di chuyển của bản sao.","Neeko ném một cuộn rễ gây sát thương và trói chân mọi thứ nó đi qua. Nếu cuộn rễ tiêu diệt một kẻ địch hoặc đi qua một tướng, nó trở nên to hơn, nhanh hơn, và trói lâu hơn.","Sau một thoáng chuẩn bị, Neeko nhảy lên không trung, hất tung mọi kẻ địch xung quanh. Khi cô hạ cánh, kẻ địch xung quanh sẽ nhận sát thương và bị làm choáng. Quá trình chuẩn bị sẽ không bị lộ nếu Neeko đang cải trang."]],"nidalee":["Lớn lên giữa rừng già, Nidalee là một thợ săn bậc thầy có thể biến hình thành một chú báo dữ tợn. Nửa người nửa thú, cô quyết liệt bảo vệ lãnh thổ khỏi bất kỳ kẻ xâm phạm nào với những cạm bẫy được thiết lập tinh vi và mũi lao sắc bén. Cô ấy làm tê liệt con mồi của mình truốc khi lao thẳng vào chúng trong dạng báo - chỉ có vài kẻ may mắn sống sót kể câu chuyện về một người phụ nữ hoang dã với bản năng sắc bén, cùng bộ móng vuốt còn sắc bén hơn...",["Đi qua bụi cỏ tăng tốc chạy của Nidalee lên 10% trong 2 giây, tăng lên 30% về phía tướng địch nhìn thấy được trong tầm 1400.\nGây sát thương lên tướng và quái bằng Phóng Lao và Bẫy Rập khiến cô Săn Đuổi các mục tiêu này, cho Tầm Nhìn Chuẩn lên chúng trong 4 giây. Trong thời gian này, Nidalee nhận 10% tốc chạy (tăng lên 30% về phía mục tiêu bị Săn Đuổi) và lần tung chiêu Phóng Lao, Cắn Xé, và Vồ đầu tiên của cô lên chúng được cường hóa.","Trong dạng người, Nidalee phóng một mũi lao gai vào mục tiêu gây sát thương theo quãng đường bay. Trong lốt báo, đòn đánh kế tiếp sẽ làm trọng thương mục tiêu, gây sát thương càng cao khi kẻ địch còn càng ít máu.","Trong dạng người, Nidalee đặt một cái bẫy, kẻ địch dẫm trúng sẽ bị phát hiện và chịu sát thương. Trong lốt báo, cô nhảy tới trước, gây sát thương khi tiếp đất.","Trong dạng người, Nidalee triệu tập tinh linh của loài báo để hồi máu cho đồng đội và giúp tăng Tốc độ Đánh trong thời gian ngắn. Trong lốt báo, cô tát và gây sát thương vào phía trước của mình.","Nidalee hóa báo giúp nhận dàn kĩ năng mới."]],"nilah":["Nilah là một chiến binh khổ hạnh từ một vùng đất xa xôi, tìm kiếm những đối thủ nguy hiểm nhất, khổng lồ nhất trên thế giới để thách thức và tiêu diệt chúng. Có được sức mạnh của mình thông qua cuộc chạm trán với ác quỷ của niềm vui bị giam cầm từ lâu, cô không có cảm xúc nào khác ngoài sự hân hoan không ngừng — một cái giá nhỏ phải trả cho sức mạnh to lớn mà cô đang sở hữu. Chuyển thể con quỷ ở dạng lỏng thành một lưỡi kiếm có sức mạnh vô song, cô ấy giữ thái độ khiêu khích với những mối đe dọa lâu đời đã từ lâu bị đưa vào quên lãng.",["Nilah nhận thêm kinh nghiệm từ việc kết liễu lính, đồng thời cường hóa hiệu ứng hồi máu và lá chắn của đồng minh xung quanh.","Nilah quất lưỡi roi kiếm, gây sát thương lên kẻ địch theo một đường thẳng. Kỹ năng này cũng sẽ tăng tầm đánh cho Nilah trong thoáng chốc.","Nilah tạo một màn nước bao bọc quanh bản thân, tăng tốc độ di chuyển và cho phép cô né tránh tất cả đòn đánh lên bản thân. Đồng minh được Nilah chạm vào trong thời gian hiệu lực cũng sẽ nhận hiệu ứng kỹ năng này.","Nilah lướt về phía mục tiêu, gây sát thương phép lên tất cả kẻ địch cô lướt qua trên đường.","Nilah thực hiện một vũ điệu, xoay vòng chiếc roi kiếm và gây sát thương lên kẻ địch xung quanh trước khi kéo chúng gần lại với vũ khí của mình."]],"nocturne":["Con quỷ sinh ra từ những cơn ác mộng ám ảnh tâm trí mọi loài có tri giác, Nocturne đã trở thành một thế lực tà ác nguyên thủy. Hỗn loạn vây quanh, khuôn mặt trống không với đôi mắt lạnh lẽo cùng những lưỡi dao quái dị. Sau khi tự giải thoát khỏi vương quốc linh hồn, Nocturne đến thế giới tỉnh thức và sống bằng nỗi kinh hoàng chỉ có thể sinh trưởng mạnh mẽ trong hắc ám nguyên bản.",["Mỗi vài giây, đòn đánh kế tiếp của Nocturne gây thêm sát thương vật lý lên các kẻ địch xung quanh và hồi máu cho nó.\nĐòn đánh của Nocturne giảm hồi chiêu kỹ năng này.","Nocturne phóng ra một thanh gươm bóng tối gây sát thương và tạo ra một Vệt Bóng Tối. Các tướng địch trúng chiêu cũng để lại một Vệt Bóng Tối. Khi đứng trên vệt đen đó, Nocturne có thể chạy xuyên vật thể đồng thời được tăng Tốc độ Di chuyển và Sát thương Vật lí.","Nocturne cường hóa thanh gươm của mình, gia tăng Tốc độ Đánh nội tại. Kích hoạt Bóng Đen Bao Phủ cho phép Nocturne tạo ra một chiếc khiên chặn một kỹ năng công kích của đối phương và gia tăng gấp đôi Tốc độ Đánh nội tại nếu thành công.","Nocturne tạo ra một cơn ác mộng lên mục tiêu, gây sát thương mỗi giây đồng thời tạo trạng thái hoảng loạn nếu nạn nhân không thoát ra khỏi tầm hoạt động của kĩ năng khi hết thời gian.","Nocturne giảm tầm nhìn của tất cả tướng đối phương cũng như loại bỏ sự chia sẻ tầm nhìn của chúng trong thời gian hiệu lực. Sau đó hắn có thể phóng tới một tướng địch gần đó."]],"nunu":["Ngày xửa ngày xưa, có cậu bé muốn chứng tỏ mình là anh hùng nên cậu đã đi săn một con quái vật đáng sợ - nhưng cậu phát hiện ra con vật này, một người tuyết cô độc, lại chỉ muốn tìm bạn mà thôi. Kết nối với nhau bằng sức mạnh cổ xưa và tình yêu với cầu tuyết, Nunu cùng Willump ngao du khắp Freljord, hòa mình vào những chuyến phiêu lưu tưởng tượng. Nunu và Willump hy vọng ở đâu đó ngoài kia, họ sẽ tìm thấy mẹ của Nunu. Nếu cứu được bà, có lẽ họ sẽ trở thành anh hùng như mong ước…",["Nunu tăng tốc độ đánh và tốc độ di chuyển cho Willump và một đồng minh gần đó, và khiến đòn đánh của Willump gây sát thương các kẻ địch quanh mục tiêu","Willump cắn kẻ địch một cái, gây sát thương và hồi máu cho bản thân.","Willump tạo ra một quả cầu tuyết ngày một to hơn và nhanh hơn. Cầu tuyết gây sát thương và hất tung kẻ địch.","Nunu ném ra một loạt cầu tuyết gây sát thương và làm chậm mục tiêu. Willump sẽ trói chân những mục tiêu vẫn còn đứng gần nó lúc kỹ năng này kết thúc.","Nunu & Willump tạo ra một cơn bão tuyết cực mạnh trong một khu vực, làm chậm kẻ địch và gây sát thương khủng khiếp khi kết thúc."]],"olaf":["Gã cầm rìu Olaf là một thế lực không thể ngăn cản, gã chẳng mong gì hơn là được hy sinh trong một trận chiến vinh quang. Đến từ bán đảo Lokfar tàn bạo của đất Freljord, gã từng nhận được một lời tiên tri dự đoán về cái chết yên bình của mình - một số phận hèn nhát, và sự sỉ nhục lớn trong tộc của gã. Gã càn quét khắp vùng đất để tìm kiếm cái chết, được cuồng nộ tiếp sức, Olaf sát hại vô số chiến binh và quái thú trên đường tìm kiếm một kẻ có thể ngăn hắn lại. Giờ là một đao phủ trong hàng ngũ Móng Vuốt Mùa Đông, gã tìm kiếm kết thúc của mình trong cuộc đại chiến sắp tới.",["Olaf nhận thêm Tốc Độ Đánh và Hút Máu dựa trên Máu đã mất.","Olaf ném rìu đến điểm chỉ định, gây sát thương lên kẻ địch chúng đi qua, Làm Chậm và giảm Giáp của chúng. Nếu Olaf nhặt được rìu đã ném, hồi chiêu của kỹ năng này sẽ được tái tạo.","Olaf được tăng Tốc Độ Đánh và nhận một Lá Chắn.","Đòn đánh của Olaf mạnh tới mức gây sát thương chuẩn lên cả hắn và mục tiêu, và được trả lại số Máu đã tổn thất nếu hắn tiêu diệt được mục tiêu.","Olaf nhận giáp và kháng phép nội tại. Gã có thể kích hoạt kỹ năng này để trở nên kháng mọi hiệu ứng, miễn là gã tiếp tục tấn công."]],"orianna":["Từng là một cô gái bằng xương bằng thịt, Orianna của hiện tại lại là kỳ quan công nghệ được tạo nên hoàn toàn bằng bánh răng và dây cót. Cô bị bệnh nặng sau một tai nạn ở các quận dưới ở Zaun, và cơ thể dần bị hủy hoại của cô phải được thay thế bởi những cỗ máy tinh xảo, từng chút từng chút một. Đi theo cô là một quả cầu bằng đồng thau được làm ra để bảo vệ mình, Orianna giờ đã được tự do thoải mái khám phá những khung cảnh tuyệt vời của Piltover, và còn hơn thế nữa.",["Đòn đánh của Orianna gây thêm sát thương phép. Sát thương tăng theo số lần đánh của Orianna lên cùng một mục tiêu.","Orianna hiệu lệnh cho khối cầu bắn đến vị trí mục tiêu, gây sát thương phép lên những đơn vị va phải trong đường bay (các đơn vị nối tiếp nhau sẽ nhận ít sát thương hơn). Khối cầu sẽ yên vị tại địa điểm đó.","Orianna hiệu lệnh Quả Cầu của mình phóng ra năng lượng, gây sát thương phép quanh nó. Trường năng lượng tồn dư tăng tốc đồng minh hoặc làm chậm kẻ địch đi qua.","Orianna hiệu lệnh Quả Cầu bám vào một tướng đồng minh, tạo Lá chắn cho họ và gây sát thương phép lên những kẻ địch va phải trên đường bay. Ngoài ra, khối cầu còn tăng Giáp và Kháng Phép cho tướng nó bám vào.","Orianna hiệu lệnh khối cầu phóng thích ra sóng chấn động, gây sát thương phép và hút kẻ địch bay về phía khối cầu sau một khoảng thời gian ngắn."]],"ornn":["Ornn là vị bán thần của nghề rèn và thủ công ở Freljord. Ông đơn độc làm việc trong một lò rèn khổng lồ được tạo nên bởi những hang động dung nham bên dưới ngọn núi lửa Tổ Ấm. Tại đó, ông đun những vạc đá nóng chảy sôi sùng sục để tinh luyện quặng và chế tác những món trang bị có chất lượng vô bì. Khi các vị thần khác - nhất là Volibear - xuất đầu lộ diện và can dự vào việc trần, Ornn đứng lên đưa những kẻ hăng máu này về đúng chỗ, dù là bằng cây búa ông luôn tin tưởng hay bằng sức mạnh rực lửa của núi non.",["Ornn nhận thêm Giáp và Kháng Phép cộng thêm từ mọi nguồn.\nOrnn có thể dùng vàng để rèn trang bị không tiêu thụ ở bất kỳ đâu.\nNgoài ra, ông có thể tạo ra các trang bị tuyệt phẩm cho bản thân và đồng minh.","Ornn dộng xuống đất, tạo ra một khe nứt gây sát thương vật lý và làm chậm kẻ địch. Sau một khoảng trễ ngắn, một cột dung nham trồi lên ở vị trí chỉ định.","Ornn hiên ngang đi tới, thở ra lửa và không thể bị ngăn cản. Kẻ địch trúng luồng lửa cuối bị Nóng Giòn.","Ornn lao tới, gây sát thương lên các kẻ địch ông băng qua. Nếu Ornn đâm vào địa hình, cú va chạm tạo ra một làn sóng chấn động gây sát thương và hất tung kẻ địch.","Ornn triệu hồi một con dê lửa khổng lồ ở địa điểm chỉ định. Sau đó, nó sẽ đi về phía ông với tốc độ tăng dần. Kẻ địch bị con dê băng qua chịu sát thương phép, bị làm chậm và Nóng Giòn. Ornn có thể tái kích hoạt kỹ năng để lao tới con dê, đổi hướng nó theo hướng ông đâm vào, khiến con dê hất tung bất kỳ kẻ địch nó chạy qua, gây cùng lượng sát thương và đặt lại Nóng Giòn."]],"pantheon":["Từng là vật chủ không tình nguyện của Thượng Nhân Chiến Tranh, Atreus đã sống sót khi thực thể quyền năng trong anh bị tiêu diệt bởi một đòn đánh xé rách các vì sao khỏi bầu trời. Đến đúng thời điểm, anh học được cách đón nhận sức mạnh của phàm nhân, và cả sự kiên ngạnh của họ. Atreus giờ chống lại thần linh trong hình hài Pantheon tái sinh, ý chí bất khuất của anh sẽ nạp đầy năng lượng cho vũ khí của vị Thượng Nhân đã ngã xuống trên chiến trường.",["Cứ sau một vài phép hoặc đòn đánh, phép kế tiếp của Pantheon được cường hóa.","Pantheon đâm giáo hoặc ném giáo theo hướng chỉ định.","Pantheon nhảy vào mục tiêu, gây sát thương và làm choáng.","Pantheon giương khiên chặn hết sát thương đến từ trước mặt và liên tục đâm giáo.","Pantheon bay lên trời cao rồi rơi như thiên thạch xuống địa điểm chỉ định."]],"poppy":["Runeterra không hề thiếu các anh hùng dũng cảm, nhưng có rất ít người ngoan cường như Poppy. Mang theo cây búa của Orlon dài gấp đôi mình, cô nàng Yordle này đã dành không biết bao năm để tìm kiếm “Anh hùng xứ Demacia,” một chiến binh huyền thoại được truyền tụng là chủ nhân của thứ vũ khí cô đang nắm giữ. Cho đến lúc đó, cô vẫn cần mẫn xung phong trên chiến trường, đẩy lùi kẻ địch của vương quốc qua từng cú vung búa.",["Poppy ném khiên đập vào mục tiêu rồi nảy ra. Cô có thể nhặt khiên để tạo cho mình một lá chắn tạm thời.","Poppy vung búa, gây sát thương và tạo ra một vùng làm chậm kẻ địch đồng thời phát nổ sau một thời gian.","Poppy nhận thêm Giáp và Kháng Phép nội tại. Điểm thưởng tăng khi cô thấp Máu. Poppy có thể kích hoạt Không Thể Lay Chuyển để ngăn kẻ địch lướt xung quanh và nhận thêm Tốc độ Di chuyển.","Poppy lao tới mục tiêu và đẩy hắn về phía sau. Nếu mục tiêu bị đẩy vào tường, hắn sẽ bị choáng.","Poppy dồn sức mạnh cho một phát búa đẩy bay kẻ địch đi xa."]],"pyke":["Một tay lao thủ nổi tiếng ở cảng giết mổ Bilgewater, Pyke lẽ ra đã chết trong bụng một con thủy quái khổng lồ... và, hắn trở lại. Giờ hắn rình rập trong những hẻm tối của thành phố, sử dụng món quà siêu nhiên mới của mình để đem lại kết cục nhanh gọn và đáng buồn cho những kẻ nào làm giàu bằng cách bóc lột kẻ khác - những cư dân vốn tự hào về việc săn quái vật giờ đã có một con quái vật săn lùng họ.",["Khi Pyke không bị kẻ địch nhìn thấy, hắn hồi phục sát thương do tướng địch gây ra gần đây. Pyke không thể tăng máu tối đa từ bất kỳ nguồn nào, thay vào đó nhận thêm SMCK.","Pyke đâm kẻ địch trước mặt hoặc kéo một kẻ địch về phía hắn.","Pyke ngụy trang và được tăng mạnh Tốc độ Di chuyển giảm dần theo thời gian.","Pyke lướt tới, để lại sau một bóng ma sẽ trở về bên hắn, làm choáng kẻ địch trên đường bay qua.","Pyke bay tới và kết liễu kẻ địch thấp máu, cho phép hắn dùng lại kỹ năng này lần nữa và cộng thêm vàng cho đồng minh hỗ trợ."]],"qiyana":["Trong thành phố giữa rừng già của Ixaocan, Qiyana đang lên kế hoạch cho con đường đến với ngai báu Yun Tal. Đứng cuối trong danh sách kế vị, cô đối mặt với những ai ngáng đường mình bằng sự tự tin và tài năng ma thuật nguyên tố chưa từng có trước giờ. Với vùng đất tuân theo mọi mệnh lệnh của cô, Qiyana thấy mình là pháp sư nguyên tố vĩ đại nhất lịch sử Ixaocan - và do đó, cô không chỉ xứng đáng có một thành phố, mà là cả một đế quốc.",["Đòn đánh đầu tiên của Qiyana lên 1 kẻ địch gây thêm sát thương.","Qiyana vung vũ khí, gây sát thương kèm hiệu ứng tùy theo nguyên tố cô triệu hồi.","Qiyana lướt đến một vị trí, phù phép vũ khí của mình với một nguyên tố. Đòn đánh và kỹ năng của cô gây thêm sát thương khi vũ khí được phù phép.","Qiyana lao tới chỗ kẻ địch, gây sát thương lên mục tiêu.","Qiyana bắn ra một đợt sóng chấn động kích nổ bất kỳ nguyên tố nào trúng phải, làm choáng và gây sát thương kẻ địch đứng gần."]],"quinn":["Quinn là một hiệp sĩ tuần tra tinh nhuệ của Demacia, cô chuyên thực hiện những nhiệm vụ nguy hiểm sâu trong lãnh thổ quân thù. Cô và chú chim đại bàng huyền thoại, Valor, cùng chia sẻ một mối quan hệ không thể tách rời, và kẻ địch của họ thường gục ngã trước khi chúng kịp nhận ra mình đang chiến đấu với không phải một, mà là hai người hùng vĩ đại nhất vương quốc. Mau lẹ và linh hoạt khi cần thiết, Quinn nhắm bắn bằng cây nỏ trong khi Valor đánh dấu những mục tiêu lẩn lút từ trên trời, biến họ trở thành một cặp đôi chết chóc trên chiến trường.",["Valor, đại bàng Demacia của Quinn, định kỳ đánh dấu kẻ địch bằng Chim Săn Mồi. Đòn đánh thường đầu tiên của Quinn lên mục tiêu Chim Săn Mồi sẽ gây thêm sát thương vật lý.","Quinn gọi Valor lướt tới, đánh dấu và gây sát thương những kẻ địch trong vùng ảnh hưởng.","Quinn nhận thêm Tốc Độ Đánh và Tốc Độ Di Chuyển từ nội tại sau khi tấn công mục tiêu Chim Săn Mồi. Kích hoạt để Valor soi sáng một khu vực lớn gần đó.","Quinn lướt tới một kẻ địch, gây sát thương vật lí và làm chậm Tốc độ Di chuyển của nạn nhân. Khi đến nơi cô lộn ngược lại ngắt quãng nạn nhân trong thoáng chốc, rồi đáp xuống cách mục tiêu một khoảng bằng tầm đánh tối đa của bản thân.","Valor giúp Quinn bay với tốc độ cao. Kết thúc kỹ năng này sẽ tung ra Oanh Tạc, gây sát thương lên các kẻ địch xung quanh và đánh dấu Chim Săn Mồi lên tướng."]],"rakan":["Thất thường mà quyến rũ, Rakan là kẻ gây rối nổi tiếng người vastaya và cũng là vũ sư chiến trường vĩ đại nhất trong lịch sử bộ tộc Lhotlan. Đối với dân cao nguyên Ionia, tên anh từ lâu đã đồng nghĩa với những lễ hội hoang dã, những bữa tiệc không thể kiểm soát cùng âm nhạc hỗn loạn. Ít ai ngờ rằng anh cũng là chiến hữu của kẻ nổi loạn Xayah, và hết mình cho lý tưởng của cô.",["Rakan nhận một lá chắn theo chu kỳ.","Bắn một lông vũ ma thuật gây sát thương phép. Bắn trúng tướng hoặc quái khủng cho phép Rakan hồi máu cho đồng đội.","Lướt tới một điểm và hất tung kẻ địch xung quanh.","Bay đến bên tướng đồng minh, cho họ lá chắn. Có thể dùng lần nữa mà không tiêu hao năng lượng trong một khoảng thời gian ngắn.","Nhận thêm Tốc độ Di chuyển, mê hoặc và gây sát thương phép lên kẻ địch chạm phải."]],"rammus":["Nhiều người thần tượng, có kẻ xua đuổi, bí ẩn với tất cả, sinh vật tò mò Rammus luôn luôn khó hiểu. Được lớp vỏ gai bảo vệ, Rammus tạo cảm hứng cho ngày càng nhiều lý thuyết về nguồn gốc của nó, không cần biết nó đặt chân đến nơi nào - từ bán thần, nhà tiên tri thần thánh, đến một con thú tầm thường bị ma thuật làm biến dạng. Dù sự thật có ra sao, Rammus vẫn giữ nguyên ý định của nó và chẳng dừng lại với ai trên đường lang thang giữa sa mạc Shurima.",["Rammus nhận thêm Sức Mạnh Công Kích Cộng Thêm tỉ lệ với Giáp và Kháng Phép của bản thân.","Rammus hóa thành quả bóng, tăng tốc lăn đến kẻ địch, tông vào chúng gây sát thương và làm chậm.","Rammus tiến vào thế thủ, tăng mạnh Giáp và Kháng Phép của bản thân, đồng thời phản lại sát thương lên kẻ địch dám tấn công hắn.","Rammus khiêu khích một tướng địch hoặc quái để chúng xông lên tấn công bất chấp tất cả.","Rammus nhảy lên không trung và đáp đất tại điểm chỉ định, gây sát thương và làm chậm kẻ địch. Nếu sử dụng trong khi đang ở dạng Quả Cầu Tốc Độ, Rammus sẽ hất tung kẻ địch trong vùng trung tâm."]],"reksai":["Rek'Sai là một con thú săn mồi đỉnh cao, một sinh vật Hư Không tàn nhẫn đào hầm dưới mặt đất để phục kích và nuốt chửng những con mồi bất cẩn. Cơn đói vô độ của mụ đã tàn phá cả một vùng của đế chế từng một thời huy hoàng Shurima - thương nhân, lái buôn, thậm chí cả những đoàn người có vũ trang đầy đủ, sẽ đi vòng hàng trăm dặm để tránh mụ và bãi săn của con cháu mụ. Ta chỉ biết khi nhìn thấy Rek'Sai nơi chân trời, cái chết dưới chân chắc chắn đang tới.",["Rek'Sai tăng Nộ khi tấn công kẻ địch với Đòn Đánh và Kỹ Năng cơ bản. Khi Độn Thổ sẽ tiêu hao lượng Nộ này để hồi lại máu.","3 đòn đánh kế tiếp của Rek'Sai gây thêm Sát Thương Vật Lý lên các kẻ địch gần đó.\nKhi Độn Thổ, Rek'Sai bắn ra một nắm đất chứa đầy sức mạnh hư không, gây sát thương và làm lộ diện các kẻ địch trúng phải.","Rek'Sai lặn xuống đất, mở khóa các Kỹ Năng mới và được tăng Tốc Độ Di Chuyển. Ả sẽ không thể tung đòn đánh thường và bị giảm tầm nhìn.\nKhi đang Độn Thổ, Rek'Sai có thể sử dụng Trồi Lên để hất tung và gây sát thương lên những kẻ địch cạnh bên.","Rek'Sai cắn mục tiêu, gây sát thương vật lý hoặc sát thương chuẩn cộng thêm nếu có đầy Nộ.\nKhi Độn Thổ, Rek'Sai tạo ra một đường hầm tồn tại trong thời gian dài và có thể được tái sử dụng. Kẻ địch có thể phá hủy đường hầm bằng cách đứng trên một trong hai đầu hầm.","Rek'Sai đánh dấu mục tiêu khi gây sát thương lên chúng. Ả ta có thể kích hoạt kỹ năng để tạm thời biến mất và lao vào mục tiêu bị đánh dấu, gây sát thương dựa theo máu tối đa của chúng."]],"rell":["Sản phẩm của những thí nghiệm kinh hoàng dưới tay Hội Hoa Hồng Đen, Rell là một món vũ khí sống nổi loạn với mục tiêu lật đổ đế chế Noxus. Trải qua một tuổi thơ đầy đau khổ và ám ảnh, phải chịu đựng những thí nghiệm kinh hoàng khôn tả nhằm hoàn thiện và vũ trang hóa ma thuật điều khiển kim loại trong cô... cho đến khi Rell trốn thoát, hạ sát vô số những kẻ giam cầm cô. Giờ đây, bị xem là một tội phạm nguy hiểm, Rell tấn công bất kì binh lính Noxus nào cô chạm trán, và tìm kiếm những người sống sót trong cái gọi là “học viện” cũ của mình, bảo vệ những kẻ yếu thế và trả mối thù không thể dung thứ với những cựu quản giáo của cô.",["Đòn Đánh và Kỹ Năng của Rell gây thêm sát thương phép và đánh cắp Giáp và Kháng Phép khi trúng mục tiêu.","Rell gây sát thương phép lên các đơn vị theo đường thẳng, phá vỡ lá chắn và làm choáng chúng.","Chiến Mã: Rell Xuống Ngựa, lao xuống đất cùng bộ giáp của mình, Hất Tung kẻ địch và nhận một lớp Lá Chắn lớn. Khi ở dạng chiến giáp, cô nhận thêm Giáp, Kháng Phép, Tốc Độ Đánh và Tầm Đánh nhưng bị Làm Chậm.\nChiến Giáp: Rell biến lớp giáp thành Chiến Mã, được tăng tốc trong thoáng chốc và kẻ địch tiếp theo cô tấn công bị Hất Tung.","Nội tại: Rell nhận Tốc Độ Di Chuyển khi ngoài giao tranh.\nKích hoạt: Rell và một đồng minh nhận Tốc Độ Di Chuyển tăng dần, nhận gấp đôi khi di chuyển về phía kẻ địch và về phía nhau. Đòn Đánh kế tiếp của cô và đồng minh sẽ phát nổ, gây sát thương phép.","Rell bùng nổ năng lượng từ trường, Giật mạnh các kẻ địch ở gần về phía mình. Sau đó liên tục Kéo chúng về phía mình trong một vài giây, gây sát thương phép trong thời gian hiệu lực."]],"renata":["Renata Glasc trỗi dậy từ tro tàn của tuổi thơ, nơi chẳng còn gì ngoài cái tên của ả và những nghiên cứu sinh hóa cha mẹ để lại. Trong những thập kỷ sau đó, ả đã dần trở thành hóa chủ giàu có nhất thành Zaun, một doanh nhân nổi tiếng xây dựng quyền lực bằng cách trói buộc nhu cầu của những kẻ khác. Làm việc cho ả, và ngươi sẽ nhận được bổng lộc vô kể. Chống lại ả, và ngươi sẽ phải hối hận vì điều đó. Nhưng rồi ai thì cũng phải làm việc cho ả ta thôi.",["Đòn đánh của Renata gây thêm sát thương và đánh dấu mục tiêu. Đồng minh của Renata có thể gây sát thương lên mục tiêu đánh dấu để một lần nữa gây thêm sát thương.","Renata bắn ra cánh tay máy, trói chân kẻ địch đầu tiên trúng chiêu, và có thể tái kích hoạt kỹ năng để ném kẻ địch về hướng chỉ định.","Renata tăng sức mạnh cho một đồng minh, trì hoãn cái chết cho họ và có khả năng cứu sống họ nếu họ có được tham gia hạ gục.","Renata bắn ra hai quả tên lửa hóa kỹ, tạo lá chắn cho đồng minh và gây sát thương đồng thời làm chậm kẻ địch trúng chiêu.","Renata phát tán một đám mây hóa chất, khiến những kẻ địch trúng phải trở nên Cuồng Loạn."]],"renekton":["Renekton là một Thể Thăng Hoa tàn bạo khủng khiếp đến từ vùng sa mạc bỏng cháy Shurima. Trước đây, hắn là chiến binh mạnh mẽ nhất đế chế, dẫn dắt quân đội đến hết thắng lợi này sang thắng lợi khác. Tuy nhiên, sau khi đế quốc của ông sụp đổ, Renekton bị giam trong một lăng mộ dưới lớp cát. Dần dần, khi thế giới bên ngoài thay đổi, hắn bị mất trí. Được tự do trở lại, trong cơn điên loạn, hắn bị thôi thúc phải tìm kiếm và tiêu diệt anh trai Nasus, người hắn đổ lỗi trong hàng thế kỷ khi phải sống trong bóng tối.",["Đòn đánh của Renekton sẽ tăng Nộ, tăng mạnh khi thấp máu. Điểm Nộ có thể cường hóa kỹ năng và cho thêm hiệu ứng mạnh mẽ.","Renekton vung vũ khí của hắn, gây sát thương vật lí mức độ vừa phải lên các mục tiêu xung quanh và hồi cho hắn một lượng máu nhỏ dựa trên lượng sát thương đã gây ra. Nếu hắn có trên 50 Nộ, sát thương và lượng máu hồi sẽ tăng lên.","Renekton chém vào mục tiêu 2 nhát, gây sát thương vật lí mức độ vừa phải và làm choáng nạn nhân trong 0.75 giây. Nếu Renekton có trên 50 Nộ, hắn chém vào mục tiêu 3 nhát, phá lá chắn trên mục tiêu, gây sát thương vật lí mạnh hơn và làm choáng nạn nhân trong 1.5 giây.","Renekton lao tới, gây sát thương lên các đơn vị trên đường đi. Khi được tăng cường sức mạnh, Renekton gây thêm sát thương và giảm giáp đơn vị bị trúng đòn.","Renekton hóa thành Khổng lồ, tăng thêm Máu và gây sát thương lên các kẻ địch quanh hắn. Khi đang trong dạng này, Renekton được gia tăng Nộ theo thời gian."]],"rengar":["Rengar là một tên thợ săn chiến lợi phẩm Vastaya hung tợn sống nhờ vào khao khát săn đuổi và giết chóc những sinh vật nguy hiểm. Hắn ta chu du khắp thế giới để tìm kiếm những con quái vật đáng sợ nhất, đặc biệt là lần theo mọi dấu vết của Kha'Zix, thứ sinh vật Hư Không ghê tởm đã cào mất một mắt của hắn. Rengar săn đuổi những con mồi của hắn không vì thức ăn hay danh tiếng, mà chỉ đơn giản là vì vẻ đẹp thuần túy của việc săn đuổi.",["Khi đứng trong bụi cỏ, Rengar nhảy vào mục tiêu bằng đòn đánh thường.\nRengar nhận điểm Hung Tợn khi sử dụng một chiêu thức. Ở số Hung Tợn Tối Đa, kỹ năng tiếp theo của hắn được cường hóa.\nHạ gục tướng địch sẽ cho Rengar thêm chiến lợi phẩm trên Dây Chuyền Răng Nanh, tăng cho hắn thêm sức mạnh công kích.","Đòn đánh kế tiếp của Rengar đâm mạnh vào mục tiêu, gây thêm sát thương.\nHung Tợn cường hóa: tăng thêm sát thương và cho Tốc độ Đánh.","Rengar gầm lên một tiếng, gây sát thương kẻ địch và hồi lại một phần sát thương vừa gánh chịu.\nHung Tợn: thêm hiệu ứng thanh tẩy khống chế.","Rengar ném ra một bola, làm chậm mục tiêu đầu tiên trúng phải trong chốc lát.\nHung Tợn: trói chân mục tiêu.","Bản năng săn mồi của Rengar trỗi dậy, Ngụy Trang nó và làm lộ diện tướng địch gần nhất trong bán kính lớn xung quanh. Khi đang Khao Khát Săn Mồi, Rengar nhận thêm Tốc độ Di chuyển và có thể nhảy vào mục tiêu bị săn đuổi dù không đứng trong bụi cỏ, giảm Giáp của kẻ đó."]],"riven":["Từng là đại kiếm sư trong đội quân của Noxus, Riven giờ sống lưu vong trên vùng đất cô từng cố chinh phục. Thăng tiến trong hàng ngũ nhờ niềm tin vững chắc và sức mạnh tàn bạo của mình, cô được tặng thưởng thanh kiếm cổ ngữ huyền thoại và một chiến đội của riêng mình. Tuy nhiên, trên mặt trận Ionia, niềm tin của Riven vào quê hương đã tan vỡ. Cắt đứt mọi ràng buộc với đế chế, giờ cô tìm kiếm một nơi giữa thế giới đổ nát này, dù cho có tin đồn rằng Noxus đã thay đổi...",["Các kỹ năng của Riven tích sức mạnh cho thanh kiếm, và đòn đánh của cô dùng sức mạnh tích trữ đó để gây thêm sát thương.","Riven có thể tung ra một chuỗi những cú đánh cực mạnh. Kỹ năng này có thể tái kích hoạt 3 lần trong một khoảng thời gian ngắn, và cú đánh thứ ba sẽ hất văng những kẻ địch xung quanh đi.","Riven vận kình lực gây sát thương và làm choáng kẻ địch cạnh bên.","Riven bước tới trước một bước ngắn và chặn sát thương nhận vào.","Riven cường hóa vũ khí của bản thân bằng một luồng năng lượng giúp tăng Sát thương Vật lí và tầm đánh. Ngoài ra, trong khoảng thời gian này, cô có thể sử dụng Chém Gió, một kĩ năng công kích tầm xa cực mạnh."]],"rumble":["Rumble là một nhà phát minh nóng tính. Không sử dụng gì khác ngoài hai bàn tay và một đống phế liệu, gã Yordle này đã làm ra một bộ giáp người máy trang bị đầy đủ lao móc điện và tên lửa tầm xa. Những người khác có thể nhìn thứ tạo vật bằng rác này bằng nửa con mắt, nhưng Rumble chẳng bận tâm vì sau cùng, gã mới là kẻ có súng phun lửa mà.",["Mỗi kĩ năng Rumble sử dụng sẽ tăng cho hắn thanh Nhiệt. Khi đạt đến 50% Nhiệt hắn sẽ tiến vào Ngưỡng Báo Động, khiến tất cả kĩ năng cơ bản của hắn được tăng cường. Khi đạt đến 100% nhiệt, hắn Quá Tải, tăng cho hắn Tốc độ Đánh và các đòn đánh cơ bản gây thêm sát thương, nhưng bù lại không thể sử dụng kĩ năng trong vài giây.","Rumble đốt cháy các kẻ địch trước mặt hắn, gây sát thương phép theo hình nón trong 3 giây. Khi đang trong Ngưỡng Báo Động sát thương sẽ được gia tăng.","Rumble dựng lên một tấm khiên, bảo vệ hắn khỏi sát thương và cho hắn tăng nhanh tốc độ. Khi trong Ngưỡng Báo Động, độ bền tấm khiên và tốc độ sẽ tăng thêm.","Rumble bắn lao móc điện vào mục tiêu, gây sát thương phép và làm chậm Tốc độ Di chuyển, và giảm Kháng Phép. Rumble có thể mang 2 lao móc cùng lúc. Khi đạt Ngưỡng Báo Động, sát thương và làm chậm được tăng thêm.","Rumble khai hỏa một loạt tên lửa, tạo ra một thảm lửa gây sát thương và làm chậm các kẻ địch trúng phải."]],"ryze":["Được nhiều người coi là một trong những phù thủy cao tay nhất Runeterra, Ryze là vị đại pháp sư cổ xưa, già dặn với gánh nặng không tưởng đè trên vai. Sở hữu sức mạnh không giới hạn và vốn hiểu biết sâu rộng về kiến thức thần bí, ông dành cả đời tìm kiếm Cổ Ngữ Thế Giới - những mảnh vụn ma thuật nguyên bản đã từng tạo nên thế giới từ hư không. Ông phải thu thập những ký tự đó trước khi chúng rơi vào tay kẻ xấu, vì Ryze hiểu được nỗi kinh hoàng mà chúng có thể gây ra cho Runeterra.",["Kỹ năng của Ryze gây thêm sát thương dựa trên năng lượng cộng thêm, và năng lượng tối đa được tăng dựa trên một phần sức mạnh phép thuật.","Nội tại: Các kỹ năng khác của Ryze đặt lại hồi chiêu Quá Tải và tích 1 cổ ngữ. Nếu Ryze dùng Quá Tải khi có 2 cổ ngữ, ông được tăng Tốc độ Di chuyển trong thoáng chốc.\nKhi sử dụng, Ryze ném ra một luồng năng lượng gây sát thương cho kẻ địch đầu tiên trúng phải. Nếu mục tiêu có Dòng Chảy, Quá Tải gây thêm sát thương và nảy sang các kẻ địch có Dòng Chảy gần đó.","Ryze bẫy mục tiêu trong ngục cổ ngữ, gây sát thương và làm chậm kẻ đó. Nếu mục tiêu có Dòng Chảy, chúng bị trói.","Ryze bắn ra một quả cầu ma thuật, gây sát thương một kẻ địch và đặt bùa hại lên tất cả kẻ địch gần đó. Kỹ năng của Ryze có thêm hiệu ứng lên kẻ địch dính bùa hại.","Nội tại: Quá Tải gây thêm sát thương lên mục tiêu có Dòng Chảy.\nKhi sử dụng, Ryze tạo cổng dịch chuyển tới một địa điểm gần đó. Sau vài giây, đồng minh đứng trên cổng dịch chuyển được đưa tới điểm chỉ định."]],"samira":["Samira thường đối mặt với tử thần bằng một sự tự tin chẳng hề lay chuyển, kiếm tìm cảm giác phiêu lưu ở bất kỳ nơi nào cô đến. Sau khi ngôi nhà ở Shurima bị tàn phá lúc cô chỉ mới là một đứa trẻ, Samira đã tìm thấy định mệnh đích thực của mình tại Noxus, nơi cô dần nổi danh là một kẻ liều lĩnh luôn nhận những nhiệm vụ nguy hiểm bậc nhất. Mang trong tay khẩu súng lục đen và một thanh kiếm được chế tạo riêng, Samira lao vào những tình huống sinh tử ngàn cân, loại bỏ tất cả những kẻ ngáng đường cô với lửa đạn và kĩ năng kinh người.",["Samira xây dựng combo của mình bằng cách tung ra đòn đánh hoặc kỹ năng độc nhất và không trùng với cái trước đó. Đòn đánh cận chiến của Samira gây thêm sát thương phép. Đòn đánh lên các kẻ địch chịu ảnh hưởng của hiệu ứng Bất Động sẽ giúp Samira lướt tới tầm đánh của mình. Nếu kẻ địch đang bị Hất Tung, cô sẽ tiếp tục giữ chúng trong trạng thái Hất Tung thêm một khoảng ngắn.","Samira bắn ra một viên đạn hoặc chém kiếm, gây sát thương. Nếu sử dụng trong khi Đánh Liều, Samira sẽ tấn công tất cả kẻ địch nằm trên đường lướt của mình khi đến vị trí chỉ định.","Samira xoay vòng lưỡi kiếm quanh mình, gây sát thương lên kẻ địch và phá hủy các đường đạn của chúng.","Samira lướt xuyên một kẻ địch (bao gồm công trình), chém những kẻ địch cô lướt qua và nhận Tốc độ Đánh. Hạ gục tướng địch sẽ tái tạo lại thời gian hồi của kỹ năng này.","Samira giải phóng bão đạn từ vũ khí của mình, điên cuồng tấn công tất cả kẻ địch xung quanh bản thân."]],"sejuani":["Sejuani là mẹ chiến tranh của tộc Móng Vuốt Mùa Đông, một trong những bộ tộc đáng sợ nhất Freljord. Sự sống còn của người dân của cô ấy là một trận chiến liên tục, tuyệt vọng chống lại các nguyên tố, buộc họ phải tấn công người Noxus, Demacia và Avarosans để sống sót qua mùa đông khắc nghiệt.. Sejuani dẫn đầu những cuộc tấn công nguy hiểm nhất trên lưng chú heo Bristle, dùng cây chùy bằng Chân Băng để làm đông cứng rồi đập tan kẻ địch.",["Sau khi rời giao tranh, Sejuani có Băng Giáp giúp tăng Giáp và Kháng Phép cũng như miễn nhiễm làm chậm. Băng Giáp tồn tại thêm chốc lát sau khi Sejuani chịu sát thương. Sejuani có thể sát thương một kẻ địch bị choáng để phá vỡ lớp băng, gây lượng lớn sát thương phép.","Sejuani lao tới, hất tung kẻ địch lên không. Pha lao dừng lại sau khi trúng một tướng địch.","Sejuani vung chùy hai lần, gây sát thương, làm chậm kẻ địch và áp dụng cộng dồn hiệu ứng Băng.","Sejuani đóng băng và làm choáng một tướng địch có tối đa cộng dồn Băng.","Sejuani ném bola đóng băng tướng địch đầu tiên trúng phải và tạo ra một cơn bão băng giá làm chậm các kẻ địch khác."]],"senna":["Mang lời nguyền bị ám ảnh từ thuở nhỏ bởi Màn Sương Đen huyền bí, Senna đã gia nhập tổ chức Vệ Binh Ánh Sáng thần thánh và chống trả quyết liệt - để rồi bị giết bởi hồn ma tàn ác Thresh và linh hồn cô bị giam cầm trong một chiếc đèn lồng. Không chấp nhận từ bỏ hy vọng, từ bên trong đèn lồng, Senna đã học cách sử dụng Màn Sương, sau đó tái sinh trong một hình dạng mới, hoàn toàn thay đổi. Giờ đây nắm giữ cả sức mạnh bóng tối lẫn ánh sáng, Senna hạ quyết tâm dùng chính Màn Sương Đen để chống lại nó - mỗi phát bắn từ vũ khí của cô sẽ cứu chuộc các linh hồn lầm lạc ở bên trong nó.",["Khi có kẻ chết gần chỗ Senna, linh hồn của chúng bị Màn Sương Đen cầm tù. Senna có thể tấn công linh hồn đó để giải thoát và hấp thụ Màn Sương đang trói buộc chúng. Màn Sương giúp cô tăng Sức mạnh Công kích, Tầm Đánh, và Tỉ lệ Chí mạng.\nĐòn đánh của Senna mất nhiều thời gian hơn để bắn, gây thêm sát thương, và tăng cho cô một phần Tốc độ Di chuyển của mục tiêu.","Từ đôi nòng của Súng Thần Tích, Senna bắn ra một chùm ánh sáng và bóng tối kết hợp qua mục tiêu, hồi máu cho đồng minh và gây sát thương kẻ địch.","Senna tung ra làn sóng Sương Đen. Nếu trúng một kẻ địch, nó trói chân kẻ đó và mọi thứ xung quanh sau chốc lát.","Senna biến Sương Đen tích bên trong vũ khí thành cơn bão quanh mình, đón nhận bóng tối và trở thành một bóng ma của nó. Đồng minh bước vào vùng bão được ngụy trang và xuất hiện dưới dạng bóng ma. Bóng ma được tăng Tốc Độ Di Chuyển, không thể bị chọn làm mục tiêu, và che giấu danh tính.","Senna triệu tập đá thần tích của các Vệ Binh đã ngã xuống, biến khẩu súng của cô thành vầng hào quang của ánh sáng và bóng tối. Cô sẽ bắn một tia sáng đi khắp nơi, bảo vệ đồng minh và gây sát thương kẻ địch đứng ở trung tâm."]],"seraphine":["Sinh ra ở thành phố Piltover dù có cha mẹ là người Zaun, Seraphine sở hữu thiên bẩm lắng nghe linh hồn của những người khác—thế giới với cô là một khúc ca, và cô đáp lại lời ca ấy. Dù những âm thanh đó đã từng khiến cô choáng ngợp trong thời niên thiếu, nhưng giờ đây chúng là nguồn cảm hứng cho cô, khi cô biến những âm thanh hỗn loạn thành một bản hòa tấu. Cô trình diễn tại nơi thành phố bên dưới, để nhắc nhở những cư dân ở đây rằng họ không cô độc, và họ mạnh mẽ hơn khi đoàn kết cùng nhau, và trong mắt cô, tiềm năng trong họ là vô tận.",["Mỗi kỹ năng cơ bản thứ ba sẽ khiến Seraphine thi triển nó hai lần. Thêm vào đó, thi triển kỹ năng khi có đồng minh ở gần sẽ giúp đòn đánh kế tiếp của cô nàng được tăng tầm và thêm sát thương phép.","Seraphine gây sát thương trong một khu vực","Seraphine tạo Lá chắn và Tăng tốc cho đồng minh ở gần. Nếu như cô nàng đã có Lá chắn thì sẽ Hồi máu cho cả đồng minh xung quanh.","Seraphine gây sát thương và làm suy yếu hành động di chuyển của kẻ địch trên một đường thẳng.","Seraphine gây sát thương và mê hoặc kẻ địch trúng chiêu, tái tạo lại tầm thi triển với mỗi đồng minh hoặc tướng địch trúng phải."]],"sett":["Sett, thủ lĩnh thế giới ngầm tại Ionia đã nổi lên sau chiến tranh Noxus. Ban đầu, hắn chỉ là một võ sĩ trong đấu trường Navori, nhưng nhanh chóng nổi danh nhờ sức mạnh cùng sự lỳ đòn của mình. Sau khi lọt vào hàng ngũ dân quân, Sett dùng cơ bắp để leo tới đỉnh cao, thậm chí kiểm soát luôn những đấu trường nơi hắn từng lăn xả.",["Đòn đánh của Sett đổi qua lại giữa tay trái và tay phải. Cú đấm tay phải mạnh và nhanh hơn một chút. Sett cũng được tăng tốc độ phục hồi máu dựa theo máu đã mất.","Hai đòn đánh kế tiếp của Sett gây thêm sát thương dựa theo máu tối đa của mục tiêu. Sett cũng được tăng Tốc độ Di chuyển khi đi về phía tướng địch.","Sett tích sát thương gánh chịu dưới dạng Điểm Gan Góc. Khi sử dụng, Sett dùng tất cả Điểm Gan Góc tích trữ để nhận một lá chắn và đấm một vùng rộng, gây sát thương chuẩn ở trung tâm và sát thương vật lý ở hai bên.","Sett kéo tất cả kẻ địch đứng đối diện lại gần, gây sát thương và làm choáng. Nếu kẻ địch đứng hết về một bên, chúng chỉ bị làm chậm thay vì choáng.","Sett ôm theo tướng địch lên không và quật kẻ đó xuống đất, gây sát thương và làm chậm tất cả kẻ địch gần đó khi hạ cánh."]],"shaco":["Được chế tạo từ rất lâu trước đây để làm đồ chơi cho một hoàng tử cô đơn, con rối được phù phép Shaco giờ thích thú trước việc giết chóc và hỗn loạn. Bị ma thuật hắc ám làm tha hóa, nó tìm kiếm niềm vui trên nỗi thống khổ của những linh hồn tội nghiệp bị nó hành hạ. Nó sử dụng đồ chơi và những thủ thuật đơn giản mà hiệu quả đến chết người, cảm thấy tức cười trước kết quả của những \"trò chơi\" đẫm máu nó bày ra, và với những ai nghe được tiếng cười khúc khích giữa đêm, tên Hề Quỷ có thể đã chọn họ làm món đồ chơi tiếp theo rồi đấy.",["Đòn đánh của Shaco và Dao Độc gây thêm sát thương khi tấn công từ phía sau.","Shaco trở nên Vô Hình và dịch chuyển đến chỗ gần đó.\nĐòn đánh đầu tiên trong lúc Vô Hình được cường hóa, gây thêm sát thương và chí mạng nếu đánh từ phía sau.","Shaco tạo một Hộp Hề Ma Quái ẩn. Khi kích hoạt, nó sẽ gây hoảng sợ và tấn công kẻ địch gần đó.","Dao của Shaco làm mục tiêu bị nhiễm độc và làm chậm Tốc độ Di chuyển. Hắn có thể ném dao gây sát thương và nhiễm độc mục tiêu. Dao Độc ném ra gây thêm sát thương nếu mục tiêu dưới 30% máu.","Shaco tạo ra một phân thân cạnh hắn, có thể tấn công kẻ địch gần đó (gây giảm sát thương lên trụ). Khi chết, nó phát nổ, sinh ra ba Hộp Hề Ma Quái nhỏ và gây sát thương lên kẻ địch gần đó."]],"shen":["Shen là thủ lĩnh hội chiến binh bí mật mang tên Kinkou, Mắt Hoàng Hôn tại Ionia. Anh khao khát có thể tránh xa những rối loạn của cảm xúc, định kiến, và cái tôi cá nhân để rồi đi trên con đường vô hình giữa thế giới linh hồn và vật chất. Mang nhiệm vụ duy trì sự cân bằng giữa hai bên, Shen mang thanh kiếm bằng thép và cả bằng năng lượng thần bí chống lại bất kỳ kẻ nào dám đe dọa nó.",["Sau khi dùng kỹ năng, Shen nhận một lá chắn. Dùng kỹ năng lên tướng khác sẽ giảm thời gian hồi của hiệu ứng này.","Shen gọi ra kiếm hồn cùng tấn công, gây sát thương dựa trên tỉ lệ máu tối đa của mục tiêu. Nếu kiếm hồn trúng vào một tướng địch, Shen gây thêm sát thương và được tăng mạnh tốc độ đánh. Tất cả kẻ địch kiếm hồn đánh trúng trên đường trở lại sẽ bị giảm tốc độ di chuyển khi chạy khỏi Shen.","Đòn đánh nhắm vào Shen hoặc đồng minh gần Kiếm Hồn sẽ bị chặn lại.","Shen lướt tới một hướng, khiêu khích kẻ địch trên đường lướt.","Shen che chở cho đồng minh khỏi các sát thương sắp tới, và dịch chuyển đến chỗ họ."]],"shyvana":["Shyvana là một chiến binh bán long đáng sợ. Dù thường xuất hiện với hình dạng người, cô còn thống trị bầu trời ở dạng rồng, thiêu rụi kẻ thù bằng hơi thở rực lửa. Từng cứu mạng thái tử Jarvan IV, Shyvana giờ phục vụ trong đội vệ binh hoàng gia, cố gắng để được những con người đầy ngờ vực của Demacia chấp nhận.",["Tham gia hạ gục tướng địch, lính to và quái lớn sẽ giúp Shyvana nhận các cộng dồn Giáp Vảy Rồng, tăng cường khả năng phòng thủ của cô.","Đòn đánh tiếp theo của Shyvana sẽ tấn công cả mục tiêu lẫn khu vực xung quanh. Kỹ Năng này có thể tái kích hoạt. Khi ở Dạng Rồng, nó nhận thêm một lần kích hoạt nữa, gây lượng sát thương khổng lồ lên một mục tiêu duy nhất.","Shyvana nhận một lá chắn, tăng tốc độ di chuyển, và sau một khoảng thời gian ngắn, khu vực xung quanh cô sẽ phát nổ. Khi ở Dạng Rồng, vụ nổ sẽ hồi máu cho cô nếu trúng tướng địch.","Shyvana phóng ra một quả cầu lửa, phát nổ khi trúng mục tiêu lớn và làm chậm chúng. Ở Dạng Rồng, nó xuyên qua và phát nổ khi trúng kẻ địch lớn, để lại một vệt lửa phía sau.","Shyvana hóa thành Rồng và lao về phía trước, khiến kẻ địch trên đường bay phải bỏ chạy. Khi ở dạng Rồng, cô ấy trở nên to lớn hơn và các kỹ năng cơ bản được cường hóa."]],"singed":["Singed là một nhà giả kim xuất sắc không coi trọng nhiều đến vấn đề đạo đức, với các thí nghiệm khiến cả lũ tội phạm tàn bạo nhất cũng phải lạnh gáy. Bán kỹ năng của mình cho người trả giá cao nhất, hắn ít quan tâm đến cách mà các sáng chế độc hại của mình được sử dụng, vì sự hỗn loạn sau đó cũng là một cuộc thử nghiệm. Sáng chế khét tiếng nhất của hắn là \"shimmer\", cho phép các hóa chủ biến Zaun thành sân chơi cá nhân của chúng, nhưng thúc đẩy bởi sự điên rồ, Singed luôn hướng đến một điều gì đó mới, với mỗi sáng chế lại điên rồ hơn so với lần trước đó...",["Singed bứt tốc khỏi các tướng gần đó, nhận thêm Tốc độ Di chuyển khi đi qua chúng.","Để lại một vệt độc tố sau Singed, gây sát thương lên kẻ địch dẫm vào.","Quăng một hỗn hợp dung dịch keo dính lên mặt đất, làm chậm và sa lầy những kẻ địch bước lên đó.","Sát thương mục tiêu kẻ địch và hất văng đơn vị đó lên không ra phía sau Singed. Nếu mục tiêu rơi vào Keo Siêu Dính của Singed, nạn nhân sẽ bị trói chân.","Singed nốc vào một dung dịch hóa học, tăng các chỉ số của hắn, và khiến Phun Khói Độc áp dụng Vết Thương Sâu."]],"sion":["Từng là một anh hùng chiến tranh của thời kỳ đã qua, Sion được cả Noxus biết đến vì đã xiết cổ lấy mạng một vị vua Demacia bằng hai bàn tay không - nhưng không chịu bị quên lãng, hắn tái sinh để phục vụ đế chế. Cơn cuồng sát của hắn nuốt chửng mọi kẻ trên đường đi dù là bạn hay thù, chứng tỏ hắn đã không còn giữ được nhân tính. Dẫu vậy, với những mảnh giáp ghim trên người, Sion tiếp tục lao vào chiến đấu không cần biết trời đất, cố gắng tìm lại bản thân qua từng cú vung rìu.",["Sau khi bị hạ gục, Sion tạm thời sống lại. Trong thời gian đó, hắn bị rút máu liên tục nhưng đòn đánh trở nên cực nhanh, có hút máu, và gây thêm sát thương dựa theo máu tối đa của mục tiêu.","Sion vận sức tung một cú nện rìu cực mạnh về phía trước mặt gây sát thương lên những kẻ địch trúng chiêu. Nếu hắn vận sức đủ lâu, những nạn nhân trúng phải sẽ bị hất văng lên không và bị choáng.","Sion tạo một lớp khiên lên bản thân và có thể tái kích hoạt nó sau 3 giây để gây Sát thương Phép lên những kẻ địch cạnh bên. Khi Sion tiêu diệt kẻ địch, hắn sẽ được gia tăng Máu tối đa.","Sion bắn ra một luồng sóng năng lượng tầm ngắn gây sát thương và làm chậm đơn vị kẻ địch đầu tiên trúng phải. Nếu tia sóng trúng vào một lính hoặc quái, nạn nhân sẽ bị đẩy lùi, gây sát thương, làm chậm và giảm Giáp tất cả đơn vị nó lướt xuyên qua.","Sion xông xáo lao về hướng đã chọn, và tăng tốc dần theo thời gian. Hắn có thể chuyển hướng chầm chậm theo sự thay đổi vị trí của con trỏ chuột. Khi tông phải một kẻ địch hắn sẽ gây sát thương và hất văng nạn nhân đó lên không dựa trên khoảng cách đã lao đi bao xa."]],"sivir":["Sivir là một thợ săn kho báu và lính đánh thuê nổi danh khắp sa mạc Shurima. Mang trên tay thanh thập tự kiếm huyền thoại, cô đã chiến đấu và chiến thắng vô số trận đánh cho những ai đủ sức chi trả tiền thù lao cao ngất của mình. Được biết đến với lòng kiên định không chút sợ hãi và tham vọng không giới hạn, cô tự hào vì đã khai quật được các kho báu bị chôn giấu trong những lăng mộ chết chóc của Shurima để đổi lấy khoản tiền thưởng hậu hĩnh. Với sức mạnh cổ xưa trỗi dậy trong lòng Shurima, Sivir thấy mình bị giằng xé giữa mâu thuẫn của định mệnh.",["Sivir nhận thêm Tốc độ Di chuyển mỗi khi tấn công tướng địch.","Sivir phóng thanh thập tự gươm của mình đi như một cái boomerang, gây sát thương cả lượt đi lẫn về.","Một vài đòn đánh tiếp theo của Sivir được tăng tốc độ đánh và nảy bật vào các mục tiêu gần đó, giảm sát thương so với đòn đánh gốc.","Tạo một lá chắn ma thuật ngăn chặn kỹ năng đầu tiên trúng vào Sivir. Cô nhận lại máu và tốc độ di chuyển trong thoáng chốc nếu chặn được một kỹ năng.","Sivir dẫn dắt đồng minh trên chiến trường, giúp tăng cho họ một lượng Tốc độ Di chuyển trong thời gian ngắn. Ngoài ra, đòn đánh của Sivir cũng sẽ giảm hồi chiêu kỹ năng của cô."]],"skarner":["Skarner - sinh vật brackern cổ đại khổng lồ được tôn kính ở Ixtal như một trong những thành viên sáng lập của tầng lớp cầm quyền, Yun Tal. Cống hiến tất cả để giữ cho quốc gia của mình an toàn trước phần còn lại của thế giới, Skarner sống trong một căn phòng bên dưới Ixaocan, nơi ông có thể nghe thấy những rung động của trái đất và phát hiện những mối đe dọa tiềm ẩn. Khi các thành viên của Yun Tal bắt đầu hoài nghi về sự cô lập của Ixtal, Skarner ngày càng trở nên hoang tưởng và sẽ làm mọi thứ để giữ an toàn cho Ixtal và người dân của nó - dù với bất kỳ giá nào.",["Đòn đánh, Mặt Đất Vụn Vỡ, Chấn Động và Giam Cầm của Skarner sẽ đặt cộng dồn Rung Chấn lên kẻ địch. Ở cộng dồn Rung Chấn tối đa, kẻ địch sẽ phải nhận sát thương phép theo Máu tối đa trong thời gian tác dụng.","Skarner xé toạc mặt đất, lấy ra một tảng đá giúp cường hóa các đòn đánh và có thể ném đi như một vật thể tấn công cực mạnh.","Skarner nhận 1 lớp lá chắn và tạo ra một cơn động đất gây sát thương và làm chậm kẻ địch.","Skarner lao về phía trước và xuyên qua địa hình. Nếu chạm phải tướng hoặc quái rừng lớn, hắn có thể quật chúng vào bức tường kế tiếp để gây sát thương và làm choáng chúng.","Skarner quật đuôi về phía trước và áp chế tướng địch. Nếu bị bắt giữ, nạn nhân sẽ bị kéo theo Skarner khi hắn di chuyển."]],"smolder":["Ẩn mình giữa những vách đá hiểm trở tại biên giới Noxus, dưới sự trông nom sát sao của mẹ mình, chú rồng non trẻ sẽ phải học cách trở thành một hậu duệ xứng đáng của dòng dõi rồng đế vương Camavor. Với bản tính tinh nghịch và háo hức được trưởng thành, Smolder luôn tìm mọi lý do để luyện tập các kỹ năng mới chớm của mình. Tuy vẫn còn non nớt nhưng cậu ta sở hữu những kỹ năng vô cùng đáng gờm, cùng ngọn lửa sẵn sàng thiêu rụi mọi thứ.",["Đánh trúng tướng địch bằng Hơi Thở Bỏng Cháy cho 1 cộng dồn Long Hỏa. Mỗi cộng dồn sẽ tăng thêm sát thương cho các Kỹ Năng cơ bản của Smolder.","Smolder phun lửa vào một kẻ địch. Khi nhận thêm điểm cộng dồn, kỹ năng này sẽ được cường hóa.","Smolder hắt xì, phun ra một ngọn lửa tí nị, phát nổ khi trúng tướng địch.","Smolder cất cánh bay lên, di chuyển vượt địa hình và công phá kẻ địch thấp máu nhất.","Smolder gọi mẹ xuất hiện và phun lửa từ không trung, gây thêm sát thương và làm chậm kẻ địch ở chính giữa ngọn lửa."]],"sona":["Sona là bậc thầy đàn etwahl của Demacia, người có thể nói bằng những giai điệu du dương tao nhã. Phong thái này giúp cô được nhiều quý tộc bảo trợ, dù có kẻ nghi ngờ âm nhạc của cô là ma thuật - điều cấm kỵ tại Demacia. Im lặng với người ngoài nhưng phần nào được những người bạn đồng hành thân thiết thấu hiểu, Sona tấu lên khúc nhạc của mình không chỉ để xoa dịu các đồng minh bị thương, mà còn để bất ngờ hạ gục kẻ địch.",["Tăng Nhịp: Sona nhận vĩnh viễn điểm hồi kỹ năng cơ bản khi sử dụng tốt các kỹ năng này, lên đến một mốc tối đa. Sau khi đạt tối đa, những lần kích hoạt sau sẽ giảm hồi chiêu hiện tại cho chiêu cuối của cô.\nSức Mạnh Hợp Âm: Sau mỗi vài kỹ năng, Đòn Đánh tiếp theo của Sona gây thêm sát thương phép và có hiệu ứng dựa trên Kỹ Năng cuối cùng Sona vừa kích hoạt.","Sona tấu lên Anh Hùng Ca, bắn ra những luồng sấm âm thanh, gây sát thương phép lên hai kẻ địch gần nhất, ưu tiên tướng và quái. Sona tạm thời có hào quang tăng sát thương ở đòn đánh kế tiếp cho đồng minh đứng trong vùng.","Sona tấu lên Giai Điệu Khích Lệ, bắn ra những luồng âm thanh bảo hộ, giúp hồi máu cho Sona và một vị đồng minh trọng thương cạnh bên. Sona tạm thời có hào quang tạo lá chắn cho đồng minh trong vùng.","Sona tấu lên Bản Nhạc Tốc Độ, tăng Tốc độ Di chuyển cho đồng minh xung quanh. Sona tạm thời có hào quang tăng Tốc độ Di chuyển ở đòn đánh kế tiếp cho tướng đồng minh đứng trong vùng.","Sona tấu lên bản nhạc tối hậu, làm choáng các tướng địch, buộc chúng phải nhảy múa trong tuyệt vọng và chịu sát thương phép."]],"soraka":["Một lữ khách lang thang từ các chiều không gian bên ngoài Núi Targon, Soraka từ bỏ sự bất tử để bảo vệ loài người khỏi chính bản năng bạo lực của họ. Cô nhiệt thành giảng dạy sự đồng cảm và thương xót với bất kỳ ai cô gặp - thậm chí còn cứu chữa cho những kẻ muốn làm hại cô. Và, sau tất cả những gì đã thấy trên thế giới nhiễu nhương này, Soraka vẫn tin rằng người dân Runeterra còn chưa hoàn toàn khai mở hết tiềm năng của mình.",["Soraka chạy nhanh hơn khi hướng về đồng minh thấp máu ở gần.","Sao rơi xuống điểm chỉ định, gây sát thương phép và làm chậm kẻ địch. Nếu một tướng địch bị trúng chiêu, Soraka được hồi Máu.","Soraka hi sinh một phần Máu của bản thân để hồi máu cho một đơn vị đồng minh khác.","Tạo ra một vùng xoáy làm câm lặng tất cả kẻ địch bên trong. Khi vùng xoáy biến mất, tất cả những kẻ địch còn bên trong đều bị trói chân.","Soraka hiệu triệu năng lượng hy vọng, ngay lập tức hồi máu cho bản thân và tất cả tướng đồng minh."]],"swain":["Swain là Nguyên Soái của Noxus, một kẻ cai trị đầy mưu lược của một quốc gia không ngừng bành trướng sức mạnh. Dù bị đánh bại và chịu cảnh tàn tật trong chiến tranh Ionia, hắn vẫn giành quyền kiểm soát đế chế bằng sự quyết đoán đến tàn nhẫn. Giờ, Swain chỉ huy các chiến đội trên tiền tuyến, hành quân chống lại thứ hắc ám mà chỉ hắn thấy được. Trong vòng xoáy của hi sinh và bí mật, bí mật lớn nhất chính là nơi ẩn náu của kẻ thù thực sự.",["Bầy quạ của Swain thu thập Mảnh Hồn giúp hắn hồi máu và vĩnh viễn tăng Máu tối đa.","Swain bắn ra các luồng năng lượng xuyên qua kẻ địch. Kẻ địch sẽ chịu thêm sát thương với mỗi luồng năng lượng trúng phải.","Swain mở ra một con mắt quỷ, tạo nên một vùng nổ sau một thời gian. Vùng nổ gây sát thương và làm chậm kẻ địch. Tướng chịu thêm sát thương, bị lộ diện và cho Swain một Mảnh Hồn.","Swain phóng ra một luồng ma thuật của quỷ. Luồng ma thuật sau đó sẽ trở ngược về phía Swain, và trói chân kẻ địch trúng chiêu. Swain có thể chọn kéo tất cả kẻ địch trúng chiêu lại gần mình. Kỹ năng này hồi nhanh hơn ở dạng Hóa Quỷ","Swain biến hình thành một ác quỷ và hút máu của kẻ địch xung quanh. Swain có thể sử dụng Lửa Quỷ để phóng thích một đợt sóng lửa gây sát thương lên kẻ địch và làm chậm chúng. Dạng quỷ có thể kéo dài mãi mãi miễn là Swain có thể tiếp tục hút máu từ tướng địch."]],"sylas":["Lớn lên ở một khu ổ chuột trong lòng Demacia, Sylas từ xứ Dregbourne đã trở thành Biểu tượng của những góc khuất đen tối nơi Đại Thành. Khi chỉ mới là một đứa trẻ, khả năng phát hiện nguồn ma thuật tiềm tàng của hắn đã sớm thu hút sự chú ý của hội thợ săn ma pháp khét tiếng, và bọn họ đã giam cầm hắn để lợi dụng quyền năng đó cho mục đích của riêng mình. Sau khi trốn thoát và có được tự do, Sylas giờ đây đã chai sạm, trở thành một kẻ phiến loạn, mong muốn dùng ma thuật của chính mình để hủy diệt vương quốc mà hắn đã một thời phục vụ… và đội quân pháp sư bị ruồng rẫy dưới trướng hắn ta đang ngày càng trở nên mạnh mẽ hơn.",["Sau khi dùng kỹ năng, Sylas tích một điểm Kháng Ma Pháp. Đòn đánh của Sylas tiêu thụ 1 điểm để gây thêm sát thương phép lên các kẻ địch xung quanh. Khi Sylas có cộng dồn Kháng Ma Pháp, hắn được tăng tốc độ đánh.","Sylas quật hai sợi xích của gã, chúng sẽ giao nhau tại điểm chỉ định, gây sát thương và làm chậm đối phương\nSau một khoảng trễ, năng lượng ma thuật bùng nổ tại điểm giao nhau, gây thêm sát thương.","Sylas lao mình về phía một kẻ địch bằng năng lượng ma thuật, gây sát thương và hồi máu nếu mục tiêu là tướng.","Sylas lướt tới 1 vị trí. Sylas có thể tái kích hoạt kỹ năng để ném xích ra, kéo hắn tới chỗ kẻ địch trúng phải.","Sylas đánh cắp tuyệt kỹ của đối phương và có thể tự do sử dụng nó."]],"syndra":["Syndra là một pháp sư đáng sợ đến từ Ionia với quyền năng mạnh mẽ đến khó tin. Khi còn bé, cô khiến các trưởng lão trong làng lo lắng vì thứ ma thuật bất kham đó. Họ đưa cô đi học cách kiểm soát, nhưng cuối cùng cô phát hiện ra người đáng lẽ phải chỉ dạy cô lại đang kiềm chế sức mạnh của cô. Biến cảm giác bị phản bội và tổn thương thành những quả cầu năng lượng hắc ám, Syndra thề sẽ tiêu diệt bất kỳ kẻ nào có ý định kiểm soát cô.",["Syndra thu thập các Mảnh Vụn Quyền Năng của cô khi lên cấp và gây sát thương lên kẻ địch, thứ sẽ giúp nâng cấp các kỹ năng của cô.\nQuả Cầu Bóng Tối: Syndra có thể giữ thêm một tích trữ kỹ năng\nÝ Lực: Gây thêm sát thương chuẩn.\nQuét Tan Kẻ Yếu: Tăng độ rộng kỹ năng và làm chậm tất cả mục tiêu\nBùng Nổ Sức Mạnh: Kết liễu kẻ địch thấp máu","Syndra tạo ra một Quả Cầu Bóng Tối gây sát thương phép. Quả cầu sẽ vẫn nằm yên ở vị trí đó và có thể bị thao túng bởi những sức mạnh khác của cô.","Syndra thu vào rồi quẳng đi một Quả cầu Bóng Tối, hoặc lính địch, gây sát thương phép và làm chậm Tốc độ Di chuyển của những nạn nhân trúng phải.","Syndra hất văng kẻ địch và các Quả Cầu Bóng Tối đi gây sát thương phép. Ngoài ra các nạn nhân bị Quả Cầu Bóng Tối va phải sẽ bị choáng.","Syndra oanh tạc một tướng địch với tất cả những Quả Cầu Bóng Tối của cô."]],"tahmkench":["Được biết đến xuyên suốt lịch sử với vô số cái tên, con quỷ Tahm Kench lượn lờ dưới vùng nước của Runeterra, thỏa mãn cơn đói vô độ của nó với nỗi thống khổ của kẻ khác. Dù có thể xuất hiện một cách rất hào nhoáng và kiêu hãnh, hắn thường ngao du khắp nơi trên thế giới vật chất, tìm kiếm những con mồi ngây thơ. Chiếc lưỡi dài của hắn có thể khiến một chiến binh được trang bị đầy đủ giáp bị choáng váng từ hàng chục thước, và rồi bị nuốt trọn trong cái miệng rộng không đáy, vô phương trở lại.",["Đòn đánh của Tahm Kench chứa sức nặng của cơ thể khổng lồ của hắn, được tăng sát thương dựa trên máu tối đa. Gây sát thương lên kẻ địch sẽ cộng dồn Khẩu Vị Độc Đáo. Ở ba cộng dồng, hắn có thể dùng Đánh Chén lên tướng địch.","Tahm Kench quất lưỡi của hắn như một chiếc roi, gây sát thương và làm chậm đơn vị đầu tiên trúng phải và hồi máu cho hắn nếu quất trúng tướng địch.\nÁp dụng một cộng dồn Khẩu Vị Độc Đáo lên tướng địch. Nếu kẻ địch đã có sẵn 3 cộng dồn Khẩu Vị Độc Đáo, chúng sẽ bị làm choáng và tiêu thụ toàn bộ cộng dồn.","Lặn xuống và tái xuất hiện tại vị trí chỉ định, gây sát thương và hất tung tất cả kẻ địch trong vùng.","Nội Tại: Tahm Kench dự trữ một phần sát thương nhận vào, và hồi phục lại một phần lượng máu đó khi ra ngoài giao tranh.\nKích Hoạt: Chuyển tất cả sát thương dự trữ thành một lá chắn tạm thời.","Tahm Kench nuốt chửng một tướng trong vòng vài giây, gây sát thương phép nếu chúng là kẻ địch, và che chắn nếu họ là đồng minh."]],"taliyah":["Taliyah là một pháp sư du mục đến từ Shurima, bị giằng xé giữa sự mơ mộng thiếu niên và trách nhiệm người lớn. Cô đã đi gần như khắp Valoran để tìm hiểu bản chất thực sự của sức mạnh đang lớn dần của mình, dù gần đây đã phải trở lại để bảo vệ bộ tộc. Nhiều người nhầm lẫn sự đồng cảm của cô là yếu đuối và đã phải trả cái giá rất đắt - bởi bên dưới phong thái của một thanh thiếu niên là một ý chí mạnh mẽ đủ sức dời non lấp bể, và một tinh thần mãnh liệt đủ sức khiến mặt đất rung chuyển.",["Taliyah nhận thêm tốc độ di chuyển gần tường.","Taliyah ném một loạt đá về hướng chỉ định, được di chuyển tự do trong khi tung kỹ năng. Kỹ năng này khiến biến mặt đất dưới chân cô thành Đất Bất Ổn. Nếu Taliyah sử dụng Phi Thạch trên Đất Bất Ổn, cô sẽ tiêu thụ nó để ném ra một tảng đá to làm chậm kẻ địch.","Taliyah khiến một vùng đất trồi lên và ném kẻ địch đứng trên nó theo hướng cô chỉ định.","Taliyah tạo ra một bãi mìn đá gây làm chậm. Nếu kẻ địch lướt qua hoặc bị kéo/hất qua chúng, bãi mìn sẽ phát nổ và làm choáng chúng.","Taliyah tạo ra một bức tường siêu dài và lướt trên nó."]],"talon":["Talon là lưỡi dao trong bóng tối, một tay sát thủ tàn nhẫn có thể ra tay mà không báo trước và thoát đi trước khi ai đó kịp báo động. Hắn nổi tiếng nguy hiểm trên đường phố Noxus, nơi hắn buộc phải chiến đấu, giết chóc, và trộm cắp để sống sót. Được gia tộc Du Couteau trứ danh nhận nuôi, giờ hắn thực hiện mọi nhiệm vụ theo lệnh của đế chế, ám sát các thủ lĩnh, tướng quân, và anh hùng của kẻ địch... cũng như bất kỳ tên Noxus nào đủ ngu ngốc làm chủ nhân của hắn chướng tai gai mắt.",["Kỹ năng của Talon làm tướng và quái khủng Trúng Thương, cộng dồn nhiều nhất 3 lần. Khi Talon tấn công một tướng có 3 cộng dồn Trúng Thương, kẻ đó bị chảy máu, chịu sát thương theo thời gian.","Talon đâm vào mục tiêu chỉ định. Nếu chúng trong tầm cận chiến, đòn đánh gây chí mạng. Nếu ngoài tầm cận chiến, Talon sẽ nhảy vào mục tiêu trước khi đâm chúng. Talon hoàn lại một phần máu và hồi chiêu nếu kỹ năng này hạ gục mục tiêu.","Talon phóng ra một loạt dao găm sẽ trở lại chỗ hắn, gây sát thương vật lý mỗi lần đi qua một kẻ địch. Dao găm trở về gây thêm sát thương và làm chậm các đơn vị trúng phải.","Talon nhào lộn qua địa hình hoặc công trình, có khoảng cách tối đa. Kỹ năng này có hồi chiêu thấp, nhưng phải mất rất lâu địa hình đã nhảy qua mới dùng lại được.","Talon tung ra một vòng dao và trở nên Vô Hình, đồng thời tăng thêm Tốc độ Di chuyển. Khi Talon mất Vô Hình, các lưỡi dao tụ hội tại vị trí của hắn. Mỗi khi lưỡi dao di chuyển, Sát Thủ Vô Hình gây sát thương vật lý lên kẻ địch trúng ít nhất một lưỡi dao."]],"taric":["Taric là Thượng Nhân Bảo Hộ, sử dụng sức mạnh khó tin của mình để gìn giữ cho cuộc sống, tình yêu và cái đẹp ở Runeterra. Hổ thẹn sau một lần xao lãng trách nhiệm và bị trục xuất khỏi quê nhà Demacia, Taric leo lên Núi Targon để tìm kiếm sự chuộc tội. Tại đây, anh khám phá ra tiếng gọi từ những vì sao trên bầu trời cao vời vợi kia. Mang trong mình quyền năng của Targon cổ đại, Tấm Khiên Valoran giờ là một cảnh binh miệt mài chống lại sự thối nát xảo quyệt của Hư Không.",["Dùng kỹ năng cường hóa 2 đòn đánh kế tiếp của Taric, gây thêm sát thương phép, giảm hồi chiêu kỹ năng, và đánh liên tiếp.","Hồi máu cho các tướng đồng minh dựa trên số tích trữ. Đòn đánh cường hóa của Can Đảm cho một tích trữ Ánh Sáng Tinh Tú","Nội tại tăng Giáp của Taric và tướng đồng minh có Pháo Đài.\nKích hoạt sẽ tạo lá chắn cho đồng minh và đặt Pháo Đài lên họ chừng nào họ còn đứng gần Taric. Kỹ năng của Taric cũng có thể dùng từ đồng minh có Pháo Đài.","Taric gọi ra luồng sáng tinh tú. Sau khi chờ một thời gian, nó sẽ gây sát thương phép và làm choáng kẻ địch.","Sau thời gian chờ, Taric rót năng lượng vũ trụ vào tướng đồng minh xung quanh, giúp họ miễn nhiễm sát thương trong chốc lát."]],"teemo":["Không chùn bước dù là trước những trở ngại cam go nhất, Teemo trinh sát thế giới với sự nhiệt tình vô bờ bến và một tinh thần vui vẻ. Là một yordle với ý thức đạo đức vững vàng, cậu tự hào tuân theo Điều Lệ Đội Trinh Sát Bandle, đôi khi quá hăm hở đến nỗi không cần biết đến những hậu quả của hành động của mình. Dù nhiều người vẫn đặt dấu hỏi về sự tồn tại của Đội Trinh Sát, nhưng có một điều chắc chắn rằng: đừng đùa với Teemo.",["Nếu Teemo đứng yên và không hành động trong một khoảng thời gian ngắn, hắn sẽ trở nên Vô Hình vô thời hạn. Nếu đang ở trong bụi cỏ, Teemo có thể tiến vào và duy trì trạng thái Vô Hình của mình khi đang di chuyển. Sau khi thoát khỏi trạng thái Vô Hình, Teemo nhận được Yếu Tố Bất Ngờ, tăng Tốc Độ Đánh của hắn trong vài giây.","Làm mờ tầm nhìn của kẻ địch bằng một chất độc cực mạnh, gây sát thương lên mục tiêu đồng thời khiến nạn nhân bị mù trong thời gian hiệu lực.","Teemo chạy lăng xăng xung quanh, tăng nội tại Tốc Độ Di Chuyển của bản thân cho đến khi hắn bị trúng đòn bởi tướng địch hoặc trụ. Teemo có thể chạy nước rút để nhận thêm Tốc Độ Di Chuyển mà không bị mất đi khi trúng đòn trong một khoảng thời gian ngắn.","Mỗi đòn đánh của Teemo sẽ làm mục tiêu bị trúng độc %i:OnHit% Trên Đòn Đánh, gây sát thương khởi điểm, và sát thương mỗi giây trong 4 giây.","Teemo ném ra một bẫy độc phát nổ bằng một trong những cây nấm được cất trong ba lô của cậu. Nếu kẻ dịch dẫm trúng bẫy, nó sẽ phun ra một làn khói độc, làm chậm và gây sát thương theo thời gian. Nếu Teemo ném một cây nấm lên một cây nấm khác, nó sẽ nảy lên, gia tăng thêm tầm ném."]],"thresh":["Tàn ác và xảo quyệt, Thresh là một hồn ma đầy tham vọng và không hề biết mệt mỏi ở Quần Đảo Bóng Đêm. Từng là người coi giữ vô vàn bí mật, hắn đã bị hủy hoại bởi một sức mạnh khủng khiếp vượt trên cả sự sống hay cái chết. Giờ đây, hắn tồn tại bằng cách hành hạ và tra tấn kẻ khác một cách chậm rãi và man rợ. Nạn nhân của hắn phải chịu sự đau đớn cùng cực khi Thresh giày vò linh hồn họ, giam cầm họ trong chiếc lồng đèn ma quái để hành hạ họ vĩnh viễn.",["Thresh có thể thu thập linh hồn của những kẻ địch bị hạ gục ở gần, vĩnh viễn tăng Giáp và Sức mạnh Phép Thuật.","Thresh trói một kẻ địch bằng xích rồi kéo nạn nhân về phía hắn. Kích hoạt kĩ năng này lần thứ hai để kéo Thresh về phía kẻ địch.","Thresh quẳng ra một cái lồng đèn giúp bảo vệ Tướng đồng minh cạnh bên khỏi sát thương. Đồng minh có thể nhấp vào lồng đèn để lướt đến Thresh.","Các đòn đánh của Thresh sẽ gây thêm sát thương dựa trên thời gian chờ giữa hai đòn đánh kéo dài bao lâu. Khi được kích hoạt, Thresh xoáy xiềng xích, hất văng tất cả kẻ địch trúng phải theo hướng của chiêu.","Một bức tường ngục tù làm chậm và sát thương nếu bị phá vỡ."]],"tristana":["Trong khi nhiều Yordle khác dùng năng lượng để khám phá, sáng chế, hoặc chỉ bày trò nghịch ngợm, Tristana luôn thích thú với những chuyến phiêu lưu của các chiến binh vĩ đại. Cô đã nghe nói nhiều về Runeterra, các phe phái, các cuộc chiến, và tin rằng giống loài mình cũng có thể trở thành huyền thoại. Lần đầu đặt chân lên thế giới, cô mang theo khẩu đại bác Bom Thủ, và nhảy thẳng vào chiến trường bằng lòng can đảm và lạc quan không thể lay chuyển.",["Tristana được tăng thêm Tầm Đánh khi lên cấp.","Tốc độ Đánh của Tristana được tăng rất nhiều trong một khoảng thời gian ngắn.","Tristana nhảy đến vị trí mục tiêu, gây sát thương và làm chậm các đơn vị xung quanh nơi tiếp đất trong thoáng chốc.","Khi Tristana tiêu diệt một đơn vị, phát đạn của cô bắn tung ra thành những mảnh nhỏ, gây sát thương lên kẻ địch xung quanh. Có thể kích hoạt để đặt một quả bom lên mục tiêu kẻ địch, thứ sẽ phát nổ sau một thời gian ngắn và gây sát thương lên những đơn vị xung quanh.","Tristana nạp một viên đạn cỡ bự vào vũ khí rồi bắn vào kẻ địch. Gây Sát thương Phép và đẩy lùi mục tiêu. Nếu mục tiêu đang mang trên mình Bọc Thuốc Súng, quả bom sẽ nổ với phạm vi gấp đôi."]],"trundle":["Trundle là một con quỷ to lớn và cực kì xảo quyệt. Không có thứ gì mà hắn không thể đánh bại và bẻ theo ý mình, kể cả Freljord. Bảo vệ lãnh thổ cực kỳ chặt chẽ, hắn săn đuổi bất kỳ ai đủ ngu ngốc để xâm nhập vào địa bàn của hắn. Thế rồi, cây chùy bằng Chân Băng khổng lồ sẽ khiến kẻ địch lạnh thấu xương và xuyên thủng chúng bằng những cột băng lởm chởm, trong lúc Trundle cười ha hả khi máu chúng đổ trên lãnh nguyên.",["Khi có đơn vị địch bị hạ gục ở gần Trundle, hắn được hồi lại một lượng máu theo % Máu tối đa của chúng.","Trundle cắn đối phương, gây sát thương, làm chậm trong thoáng chốc và hút một số Sát thương Vật lí của nạn nhân.","Trundle tạo ra một vùng trên mặt đất giúp gia tăng Tốc độ Di chuyển, Tốc độ Đánh của bản thân đồng thời gia tăng khả năng hồi máu nhận được từ mọi nguồn khi còn ở trong vùng ảnh hưởng.","Trundle tạo ra một cột băng tại vị trí đã chọn, nơi sẽ trở thành một vùng địa hình không thể đi qua, và làm chậm tất cả kẻ địch cạnh bên.","Trundle lập tức đánh cắp một số phần trăm Máu, Giáp và Kháng Phép của mục tiêu. Trong 4 giây kế, số Máu, Giáp và Kháng Phép bị đánh cắp sẽ tăng gấp hai lần."]],"tryndamere":["Bằng sự thịnh nộ cuồng loạn của bản thân, Tryndamere một mình chinh chiến trên khắp vùng hoang mạc lạnh giá, không ngừng thách đấu những chiến sĩ vĩ đại nhất của Freljord để chuẩn bị cho những ngày tăm tối hơn phía trước. Tay man dị đầy giận dữ này từ lâu đã mong muốn trả thù cho sự tuyệt diệt của bộ tộc, dù gần đây hắn đã kết thân với Ashe, mẹ chiến tranh của tộc Hậu Nhân Avarosa, và về một nhà với cô. Sức mạnh gần như phi nhân loại của hắn đã trở thành huyền thoại, và đã đem lại cho hắn cùng đồng minh mới vô số chiến thắng trước những đối thủ sừng sỏ nhất.",["Tryndamere nhận điểm Nộ thông qua mỗi đòn đánh thường, đánh chí mạng, và các cú đánh kết liễu mục tiêu. Nộ tăng Tỉ lệ Chí mạng của hắn và có thể được tiêu thụ để sử dụng kĩ năng Say Máu.","Tryndamere cảm nhận được sự kích thích trên chiến trường, tăng sát thương vật lí mỗi khi hắn chịu sát thương. Hắn có thể niệm Say Máu để sử dụng điểm nộ và hồi máu cho bản thân.","Tryndamere gầm lên khiêu khích, giảm Sát thương Vật lí các tướng xung quanh. Kẻ địch quay lưng lại với Tryndamere bị làm chậm Tốc độ Di chuyển.","Tryndamere lướt tới mục tiêu, gây sát thương lên những kẻ địch trên đường.","Sự khao khát chiến đấu của Tryndamere mạnh tới mức hắn không thể chết, bất kể bị thương tổn bao nhiêu."]],"twistedfate":["Twisted Fate là một tay lừa đảo đã từng đặt chân lên khắp nơi trên thế giới, giành lấy sự căm ghét và cả ngưỡng mộ của những tên nhà giàu ngốc nghếch. Hiếm khi nghiêm túc, hắn đón chào ngày mới với một nụ cười chế giễu và một điệu bộ nghênh ngang. Trong mọi trường hợp, hắn luôn có một con chủ bài giấu nơi tay áo.",["Sau khi tiêu diệt một đơn vị, Twisted Fate lắc xúc xắc 'may mắn' của mình để nhận thêm từ 1 đến 6 vàng.","Phóng ba lá bài theo hình nón, gây sát thương cho mỗi đơn vị nó đi qua.","Twisted Fate chọn một lá bài ma thuật trong bộ bài của mình, sử dụng nó trong đòn đánh kế tiếp, gây thêm hiệu ứng.","Mỗi 4 cú đánh, Twisted Fate gây thêm sát thương. Ngoài ra, Tốc độ Đánh của hắn được gia tăng.","Twisted Fate đoán trước được số phận của kẻ địch, phát hiện tất cả tướng địch, và có khả năng sử dụng Dịch Chuyển, khiến cho Twisted Fate có thể biến đến bất kì vị trí nào trong 1.5 giây."]],"twitch":["Sinh ra là một con chuột xứ Zaun mê đắm sự dơ bẩn, Twitch chẳng e ngại phải bẩn tay. Nhắm thẳng cây nỏ hóa kỹ vào trái tim mạ vàng của Piltover, nó đã thề sẽ cho cả thành phố bên trên biết nó ghê gớm đến mức nào. Luôn luôn lén lút, mỗi khi không cắm rễ quanh Hầm Thải, hắn đào bới trong đống rác người ta bỏ đi để tìm kiếm kho báu... và có thể cả một cái sandwich mốc nữa.",["Các đòn đánh cơ bản của Twitch khiến mục tiêu bị trúng độc %i:OnHit% Trên Đòn Đánh và phải chịu sát thương chuẩn mỗi giây.","Twitch được Ngụy Trang trong chốc lát và nhận thêm Tốc độ Di chuyển. Khi hết Ngụy Trang, Twitch nhận thêm Tốc độ Đánh trong chốc lát.\nKhi một tướng địch có Độc Chết Người bị hạ gục, hồi chiêu Đột Kích được hoàn lại.","Twitch làm bùng nổ độc suy nhược trong một khu vực, làm chậm kẻ địch và buộc các nạn nhân bị nhiễm độc.","Twitch kích hoạt thứ dịch bệnh chết người trên những nạn nhân đã bị hạ độc.","Twitch xả toàn bộ sức mạnh của chiếc nỏ, bắn ra những mũi tên bay cực xa, xuyên qua tất cả các mục tiêu trúng phải."]],"udyr":["Lữ khách tinh linh mạnh mẽ nhất từng sống, Udyr kết giao với tất cả các linh hồn của Freljord, cho dù bằng cách thấu hiểu nhu cầu của họ, hoặc bằng cách truyền tải và chuyển hóa năng lượng thanh tao của họ thành phong cách chiến đấu nguyên thủy của mình. Ông tìm kiếm sự cân bằng từ bên trong, để tâm trí của mình không bị lạc giữa những người khác, nhưng Udyr cũng tìm kiếm sự cân bằng bên ngoài — vì cảnh quan huyền bí của Freljord chỉ có thể phát huy mạnh mẽ với sự phát triển đến từ xung đột và đấu tranh, và Udyr biết rằng phải có sự hy sinh để giữ chân hòa bình tại nơi đây.",["Udyr có 4 Kỹ Năng cơ bản giúp thay đổi giữa các Thế Võ, và có thể Tái Kích Hoạt 1 Kỹ Năng để tái tạo nó kèm theo hiệu ứng Chiêu Cuối. Ngoài ra, sau khi sử dụng Kỹ Năng, 2 đòn đánh tiếp theo của Udyr được tăng Tốc Độ Đánh.","Udyr nhận thêm tốc độ đánh và hai đòn đánh tiếp theo gây thêm sát thương vật lý. Tái Kích Hoạt: Nhận thêm tốc độ đánh, và hai đòn đánh tiếp theo của gã sẽ phóng sét vào kẻ địch.","Udyr nhận một lá chắn và hai đòn đánh tiếp theo sẽ hồi máu cho gã Tái Kích Hoạt: Nhận một lá chắn lớn hơn và được hồi máu theo máu tối đa trong vài giây tiếp theo.","Udyr nhận một lượng lớn tốc độ di chuyển, đòn đánh đầu tiên của gã lên mỗi mục tiêu sẽ gây Choáng. Tái Kích Hoạt: Nhận thêm tốc độ di chuyển và được miễn nhiễm hiệu ứng bất động trong vài giây.","Udyr triệu hồi một cơn bão tuyết bao bọc quanh bản thân, gây sát thương và làm chậm kẻ địch. Tái Kích Hoạt: Cường hóa và giải phóng cơn bão, khiến nó đuổi theo kẻ địch và gây thêm sát thương."]],"urgot":["Từng là tên đao phủ đáng sợ của Noxus, Urgot bị chính đế quốc mình phục vụ phản bội. Giữa đống xiềng xích, hắn buộc phải học hỏi ý nghĩa thực sự của sức mạnh ở Đáy Sông – một hầm mỏ kiêm nhà tù sâu bên dưới Zaun. Thoát ra từ một thảm họa khiến cả thành phố rơi vào hỗn loạn, giờ hắn phủ cái bóng đầy đe dọa lên thế giới tội phạm ngầm. Trừng phạt các nạn nhân bằng chính đống xích từng trói buộc mình, hắn sẽ thanh lọc những kẻ không xứng đáng khỏi ngôi nhà mới, biến nó thành luyện ngục của nỗi đau.",["Đòn đánh của Urgot và Càn Quét kích hoạt đại bác gắn ở chân càng theo chu kỳ, gây sát thương vật lý.","Bắn một lựu đạn vào điểm chỉ định, gây sát thương vật lý lên các kẻ địch gần đó và làm chậm chúng.","Urgot tự làm chậm trong lúc xả đại bác vào kẻ địch xung quanh. Ưu tiên tướng địch vừa trúng chiêu của Urgot và kích hoạt Đại Bác Cộng Hưởng.","Urgot lao tới, tạo lá chắn cho bản thân và giẫm đạp lên những kẻ địch không phải tướng. Nếu bắt được một tướng địch, hắn dừng lại và ném kẻ đó ra sau.","Urgot bắn ra một mũi khoan hóa kỹ, cắm vào tướng địch đầu tiên trúng phải. Nếu tướng đó tụt xuống dưới ngưỡng máu nhất định, Urgot có thể kết liễu nạn nhân."]],"varus":["Thuộc chủng tộc Darkin cổ xưa, Varus là một kẻ sát nhân thích hành hạ đối thủ và khiến họ phát điên trước khi tung mũi tên kết liễu. Vào cuối Chiến Tranh Darkin, hắn bị cầm tù, nhưng hắn đã trốn thoát sau nhiều thế kỷ trong cơ thể mới được kết hợp từ hai thợ săn Ionia - người đã vô tình thả Varus ra và rồi bị nguyền rủa phải cầm cây cung chứa năng lượng trói buộc của hắn. Varus giờ tìm kiếm những kẻ đã giam hãm hắn để trút cơn hận thù, nhưng những linh hồn phàm tục bên trong hắn vẫn cố kháng cự trên mỗi bước đi.",["Mỗi khi hạ gục hay hỗ trợ hạ gục đối phương, Varus nhận lượng Sức Mạnh Công Kích và Sức Mạnh Phép Thuật tạm thời. Sát thương cộng thêm nhận được sẽ nhiều hơn nếu đối phương là tướng.","Varus kéo cung rồi bắn ra một phát cực mạnh. Tầm bắn và sát thương tăng theo thời gian kéo cung.","Nội tại: Đòn tấn công của Varus gây thêm sát thương phép và đặt cộng dồn Tên Độc. Các kĩ năng của Varus kích nổ Tên Độc, gây sát thương phép dựa trên máu tối đa của mục tiêu. Kích hoạt: Varus cường hóa Mũi Tên Xuyên Phá kế tiếp.","Varus bắn ra một làn mưa tên gây sát thương vật lí và yểm bùa mặt đất, khiến đối phương bị làm chậm và giảm khả năng tự hồi phục của chúng.","Varus tung ra một sợi tua có khả năng trói mục tiêu tướng đầu tiên đụng phải, sau đó dài ra và tiếp tục trói những mục tiêu chưa bị ảnh hưởng xung quanh."]],"vayne":["Shauna Vayne là một thợ săn quái vật đáng gờm của Demacia, người dành cả đời tìm kiếm và tiêu diệt con quỷ đã sát hại gia đình cô. Trang bị cây nỏ gắn trên cổ tay cùng một trái tim khao khát báo thù, cô chỉ thực sự hạnh phúc khi hạ sát những kẻ thực hành hoặc những tạo vật của nghệ thuật hắc ám, tấn công từ trong bóng tối với một chùm mũi tên bạc.",["Vayne săn lùng những kẻ xấu xa không ngừng nghỉ, cô được tăng Tốc Độ Di Chuyển khi đi về phía các tướng địch ở gần.","Vayne lộn đi một quãng ngắn. Đòn đánh kế tiếp của cô gây thêm sát thương.","Đầu mũi tên của Vayne được bọc trong một thứ kim loại hiếm có thể khắc chế những thứ xấu xa. Ba đòn đánh hoặc kỹ năng liên tiếp lên cùng một mục tiêu gây thêm sát thương chuẩn theo phần trăm máu tối đa của mục tiêu.","Vayne rút ra chiếc nỏ to bản từ sau lưng, bắn một mũi tên cực đại vào mục tiêu, gây sát thương và đẩy lùi nạn nhân. Nếu mục tiêu bị va phải địa hình, nạn nhân sẽ bị choáng và chịu thêm sát thương.","Chuẩn bị sẵn sàng cho cuộc đối đầu ác liệt, Vayne được tăng Sức mạnh Công kích, có thể Vô Hình khi Nhào Lộn, giảm hồi chiêu Nhào Lộn, và thêm Tốc độ Di chuyển từ Thợ Săn Bóng Đêm."]],"veigar":["Bậc thầy ma thuật đen Veigar đã đón nhận thứ sức mạnh mà ít kẻ phàm nào dám đến gần. Là một cư dân tự do tự tại của Thành Phố Bandle, hắn khao khát vượt qua giới hạn của phép thuật Yordle, và chuyển đổi nó sang dạng một cuốn cổ thư bị chôn giấu hàng ngàn năm. Giờ Veigar là một sinh vật cao ngạo sở hữu niềm say mê vô tận với những bí ẩn của vũ trụ, và thường bị kẻ khác đánh giá thấp - nhưng dù hắn tin mình thực sự xấu xa, hắn vẫn có trong mình chút đạo đức khiến vài người phải tự hỏi động cơ sâu xa hơn của hắn là gì.",["Veigar là kẻ xấu xa tà ác vĩ đại nhất từng tồn tại trên Runeterra - và hắn ngày một vĩ đại hơn! Dùng kỹ năng trúng tướng hoặc tham gia hạ gục giúp Veigar tăng vĩnh viễn Sức mạnh Phép thuật.","Phóng thích năng lượng bóng tối gây sát thương phép lên hai kẻ địch đầu tiên trúng chiêu. Nếu đơn vị đó bị hạ gục, Veigar được tăng Sức mạnh Phép thuật.","Veigar gọi một cục thiên thạch đen khổng lồ rơi xuống địa điểm chỉ định, gây sát thương phép khi chạm đất. Cộng dồn Quỷ Quyệt giảm hồi chiêu của Thiên Thạch Đen.","Veigar xoắn vặn không gian, tạo ra một lồng giam Làm choáng kẻ địch dám bước qua.","Phóng chưởng vào tướng địch, gây lượng sát thương phép cực lớn, tăng theo lượng máu đã mất của mục tiêu."]],"velkoz":["Không rõ Vel'Koz có phải sinh vật Hư Không đầu tiên xuất hiện tại Runeterra không, nhưng chắc chắn chẳng có sinh vật nào có trí tuệ đầy tính toán và tàn nhẫn như nó. Trong khi các đồng loại ngấu nghiến hay hủy hoại mọi thứ xung quanh, nó quan sát và nghiên cứu thế giới vật chất - và những sinh vật kỳ lạ hiếu chiến sống tại đó - để xem có nhược điểm nào Hư Không tận dụng được không. Nhưng Vel'Koz không phải một kẻ quan sát bị động, nó đáp trả mọi nguy hiểm với tia plasma chết chóc, hoặc phân rã chúng thành từng nguyên tử một.",["Các kỹ năng cơ bản của Vel'Koz đặt Phân Rã Hữu Cơ lên kẻ địch khi trúng đích. Nếu tích đủ 3 điểm cộng dồn, kẻ địch sẽ phải chịu một lượng sát thương chuẩn.","Vel'Koz bắn tia plasma tách làm đôi khi tái kích hoạt hoặc khi trúng kẻ địch. Tia plasma làm chậm và gây sát thương.","Vel'Koz mở ra một vết rách không gian dẫn tới vùng hư không, gây một lượng sát thương bộc phá khởi điểm, sau đó sẽ gây sát thương theo thời gian lên những nạn nhân bên trong vệt rách không gian đó.","Vel'Koz khiến một khu vực phát nổ, hất văng kẻ địch lên không, và đầy lùi nhẹ những kẻ địch cạnh bên.","Vel'Koz phóng thích ra một luồng năng lượng tích tụ theo con trỏ chuột trong 2.5 giây sát thương kẻ địch. Tướng địch bị Soi Chiếu sẽ chịu sát thương chuẩn."]],"vex":["Nơi trung tâm Quần Đảo Bóng Đêm, có một yordle cô độc lê bước trong màn sương hắc ám, hài lòng với nỗi thống khổ đến ảm đạm của nó. Chẳng bao giờ có chút sức sống, và chỉ đồng hành với mỗi cái bóng hùng mạnh của chính mình, Vex trốn tránh khỏi mọi sự tích cực và niềm hạnh phúc nơi thế giới bên ngoài, và nhất là lũ “tầm thường” đáng ghét đang tận hưởng những điều đó. Dù không có tham vọng gì cả, cô ta sẽ nhanh chóng dẹp bỏ sắc màu hay hạnh phúc, ngăn chặn tất cả những kẻ thích chõ mũi với thứ ma thuật đầy sự khó chịu.",["Cứ sau một khoảng thời gian nhất định, Vex sẽ trở nên Bực Bội, khiến cho Kỹ Năng cơ bản tiếp theo hoảng sợ kẻ địch và gián đoạn lướt của chúng. Mỗi khi có kẻ địch lướt đi ở gần, Vex đánh dấu lên chúng và có thể kích nổ nó để gây thêm sát thương, đồng thời, giảm thời gian hồi của trạng thái Bực Bội.","Phóng ra một đường đạn gây sát thương, tăng tốc cực mạnh trên đường bay.","Nhận một lá chắn và gây sát thương lên các kẻ địch gần kề.","Triệu hồi một vùng gây sát thương và làm chậm, đồng thời áp dụng hiệu ứng Buồn Bã lên chúng.","Bắn ra đường đạn đánh dấu tướng địch. Tái kích hoạt để lướt tới và gây sát thương."]],"vi":["Lớn lên trên những khu phố ổ chuột của Zaun, Vi là một cô gái nóng tính, bốc đồng, đáng sợ, và không có nhiều sự tôn trọng với những nhà cầm quyền. Cô ấy luôn là một kẻ sống sót tinh khôn, cả từ những vụ gây rối thời trẻ ở khu trên và một thời gian dài trong Trại Stillwater. Hiện tại làm việc cùng đội Cảnh Binh Piltover để gìn giữ hòa bình thay vì phá vỡ nó, vũ khí của cô là đôi găng tay hextech mạnh mẽ có thể đấm xuyên qua tường, và cả lũ tội phạm, một cách dễ dàng.",["Lá chắn của Vi được tích tụ theo thời gian. Nó sẽ được kích hoạt khi Vi tấn công kẻ địch với một kỹ năng của mình.","Vi vận sức mạnh rồi tung một cú đấm bùng nổ đẩy cô về phía trước. Các kẻ địch trúng chiêu sẽ bị hất văng đi và chịu thêm một cộng dồn Cú Đấm Phá Giáp.","Cú đấm của Vi phá Giáp của mục tiêu, gây thêm sát thương đồng thời tăng cho cô thêm Tốc độ Đánh.","Đòn đánh kế tiếp của Vi xuyên thấu qua mục tiêu, gây sát thương lên cả những đơn vị sau nạn nhân chính.","Vi lao đến một kẻ địch, hất văng những kẻ cản đường sang hai bên. Khi đến bên kẻ địch cô hất văng mục tiêu lên không rồi nhảy bật lên nện nạn nhân xuống mặt đất."]],"viego":["Từng là người trị vì của một vương quốc đã lụi tàn từ lâu, Viego đã chết từ hàng ngàn năm trước trong nỗ lực mang vợ mình trở về từ cõi chết, và rồi hắn đã châm ngòi cho một thảm họa ma thuật mang tên Đại Suy Vong. Biến đổi thành một hồn ma hùng mạnh, bị đày đọa bởi khát khao đến ám ảnh đối với nữ hoàng đã chết, Viego giờ đây trở thành Hắc Diệt Đế Vương, dẫn đầu Màn Sương Đen chết chóc, lùng sục khắp Runeterra để tìm kiếm phương thuốc hồi sinh nàng, và hủy diệt tất cả mọi thứ trên con đường của mình, với Sương Đen không ngừng tuôn ra từ trái tim tàn độc, vụn vỡ của hắn.",["Kẻ địch gục ngã dưới chân Viego sẽ trở thành những hồn ma. Khi tấn công một hồn ma, Viego sẽ tạm thời chiếm hữu thể xác của kẻ địch bị hạ gục, hồi máu bằng một phần máu tối đa của mục tiêu đó, được sử dụng các kỹ năng cơ bản cũng như sở hữu trang bị của chúng. Chiêu cuối của kẻ địch sẽ được thay thế bằng một lần sử dụng miễn phí chiêu cuối của Viego.","Lưỡi gươm ma quái của Viego gây sát thương cộng thêm theo phần trăm máu hiện tại của kẻ địch Trên Đòn Đánh, và tấn công hai lần đối với những kẻ địch vừa trúng Kỹ Năng của gã, đồng thời Hút Máu.\nViego có thể kích hoạt Kỹ Năng này để đâm thanh cự kiếm của mình, gây sát thương lên kẻ địch phía trước mặt.","Viego vận sức trước khi lướt về phía trước, phóng thích một Màn Sương Đen dày đặc làm choáng kẻ địch đầu tiên trúng chiêu.","Viego hạ lệnh cho Màn Sương Đen ám ảnh và bao bọc một mảng địa hình. Viego có thể ẩn nấp trong Màn Sương như một bóng ma, nhận được Ngụy Trang, tốc độ di chuyển, và tốc độ đánh.","Viego dịch chuyển đến một vị trí gần đó và gây sát thương kết liễu một tướng địch ở điểm đến, giải phóng một đợt sóng năng lượng hủy diệt đồng thời hất văng các đồng minh của chúng đang ở gần ra xung quanh."]],"viktor":["Sau khi tiến hóa hoàn toàn khỏi cơ thể cũ trước đây, Viktor đón nhận sự Tiến Hóa Huy Hoàng của mình và trở thành một vị thánh cứu thế trong mắt những tín đồ của hắn. Hắn hy sinh nhân tính của chính mình với logic rằng loại bỏ cảm xúc sẽ loại bỏ đau khổ - và giờ đây mong muốn của hắn đem sức mạnh của lõi công nghệ ra thế giới, ngay cả khi mọi người không hiểu được lợi ích của chúng. Rốt cuộc, đối với bậc thầy bí thuật này, bạo lực chỉ là một biến số cần thiết để giải quyết các vấn đề mà thôi.",["Viktor nhận được Mảnh Vỡ Hextech mỗi khi tiêu diệt một kẻ địch. Với mỗi 100 Mảnh Vỡ Hextech kiếm được, Viktor vĩnh viễn nâng cấp 1 kỹ năng kích hoạt. Sau khi đã nâng cấp tất cả kỹ năng cơ bản, hắn có thể thu thập 100 Mảnh Vỡ Hextech để nâng cấp chiêu cuối của mình.","Viktor chưởng một kẻ địch gây sát thương phép và nhận được lá chắn đồng thời cường hóa đòn đánh thường kế tiếp của hắn.\nNâng Cấp: Lá chắn của Chuyển Hóa Năng Lượng mạnh hơn 60% và Viktor được tăng Tốc Độ Di Chuyển khi tung chiêu.","Viktor tạo ra một trường trọng lực làm chậm tất cả những kẻ địch trong vùng ảnh hưởng. Nếu kẻ địch đứng trong trường lực quá lâu, chúng sẽ bị làm choáng.\nNâng Cấp: Kỹ năng của Viktor làm chậm kẻ địch trúng chiêu.","Viktor sử dụng cánh tay cơ hóa bắn ra một Tia Hextech cắt xuyên chiến trường theo một đường thẳng, gây sát thương phép lên tất cả kẻ địch trên đường cắt.\nNâng Cấp: Một vụ nổ sẽ tiếp nối cú cắt của Tia Hextech, gây sát thương phép.","Viktor tạo ra một cơn Bão Arcane trên chiến trường, gây sát thương phép và làm gián đoạn việc niệm phép của kẻ địch. Cơn bão định kỳ gây sát thương phép lên tất cả kẻ địch ở gần và có thể được điều khiển bởi Viktor.\nNâng Cấp: Bão Arcane sẽ di chuyển nhanh hơn 25% và mỗi khi tướng bị hạ gục sau khi nhận sát thương từ nó, cơn bão sẽ tăng kích cỡ và kéo dài thời gian tác dụng."]],"vladimir":["Con quỷ thèm khát máu người, Vladimir đã giao rắc ảnh hưởng lên Noxus từ những ngày đầu của đế chế. Bên cạnh việc kéo dài sự sống một cách phi tự nhiên, sự tinh thông trong huyết thuật cho phép hắn kiểm soát tâm trí và cơ thể kẻ khác dễ dàng như của chính hắn vậy. Trong những bữa tiệc xa hoa của đám quý tộc Noxus, khả năng này cho phép hắn thiết lập một giáo phái cuồng tín xoay quanh chính mình - còn trong những con hẻm tối tăm, nó cho phép hắn rút cạn máu kẻ thù.",["Mỗi 30 Máu cộng thêm cho Vladimir thêm 1 Sức Mạnh Phép Thuật và mỗi điểm Sức Mạnh Phép Thuật cho Vladimir 1,6 Máu cộng thêm. (không cộng dồn với chính nó)","Vladimir hút máu từ nạn nhân của hắn. Khi đạt mức tối đa, Truyền Máu sẽ được tăng nhiều sát thương và hồi máu trong thời gian ngắn.","Vladimir lặn vào một vũng máu và không thể bị định vị trong 2 giây. Ngoài ra, kẻ địch trúng phải vũng máu sẽ bị làm chậm đồng thời Vladimir cũng rút máu từ chúng.","Vladimir dùng máu để tích tụ sức mạnh, khi phóng thích, sẽ gây sát thương lên khu vực quanh hắn nhưng có thể bị chặn bởi đơn vị địch.","Vladimir tiêm nhiễm một khu vực bằng dịch bệnh. Kẻ địch bị nhiễm sẽ chịu thêm sát thương trong thời gian đó. Sau vài giây, Máu Độc gây sát thương phép lên kẻ địch bị nhiễm và hồi máu cho Vladimir với mỗi Tướng địch trúng phải."]],"volibear":["Đối với những kẻ thờ phụng mình, Volibear là hiện thân của bão tố. Hủy diệt, hoang dã, và kiên định đến điên dại, ngài đã xuất hiện từ rất lâu trước khi giống loài phàm nhân đặt chân lên những lãnh nguyên xứ Freljord, và kiên quyết bảo vệ vùng đất mà ngài cùng giống loài á thần của ngài đã tạo ra. Nuôi trong lòng mối hận thù với nền văn minh mới và sự yếu đuối mà nó mang đến, ngài giờ đây chiến đấu để mang những tín ngưỡng cũ trở lại - nơi vùng đất vẫn chưa hề được thuần hóa, và sự vấy máu được tự do diễn ra - bằng cách toàn diệt những kẻ chống đối, với nanh, với vuốt, và cơn thịnh nộ của sấm.",["Các đòn tấn công và kỹ năng sẽ tăng Tốc độ Đánh cho Volibear, rồi sau đó cường hóa nó, giúp gây thêm sát thương phép ở mỗi Đòn lên kẻ địch gần kề.","Volibear tăng tốc khi di chuyển về phía kẻ địch, Làm Choáng và gây sát thương lên mục tiêu đầu tiên Tấn công.","Volibear tấn công kẻ địch, áp dụng hiệu ứng đòn đánh và đặt dấu ấn lên chúng. Tái sử dụng kỹ năng lên cùng mục tiêu sẽ giúp Volibear gây thêm sát thương và Hồi lại máu.","Volibear triệu hồi sấm chớp tại khu vực chỉ định, gây sát thương và Làm chậm kẻ địch, đồng thời, tạo một lớp Lá chắn nếu Volibear đứng trong vùng ảnh hưởng.","Volibear nhảy tới vị trí chỉ định, Làm chậm và gây sát thương lên kẻ địch phía dưới, đồng thời, nhận một lượng Máu cộng thêm. Trụ bảo vệ của phe địch gần khu vực Volibear nhảy tới sẽ tạm thời bị vô hiệu hóa."]],"warwick":["Warwick là một con quái vật lẩn khuất trong những con hẻm xám của Zaun. Bị biến đổi sau những thí nghiệm đau đớn, cơ thể hắn giờ được gắn kết bởi một hệ thống phức tạp đầy khoang chứa và máy bơm, hóa chất cuồng nộ ngập đầy mạch máu của hắn. Vọt ra từ bóng tối, hắn săn lùng những tên tội phạm đang khủng bố thành phố. Máu là thứ hấp dẫn Warwick, và cũng là thứ khiến hắn hóa điên... và những kẻ chảy máu thì xác định đừng có mong trốn thoát.",["Đòn đánh của Warwick gây thêm sát thương phép. Nếu Warwick còn dưới 50% máu, hắn hồi lại lượng tương ứng. Nếu Warwick còn dưới 25% máu, hồi máu nhân ba.","Warwick xồ tới cắn mục tiêu, gây sát thương dựa trên máu tối đa của chúng và hồi máu theo sát thương gây ra.","Warwick ngửi được kẻ địch dưới 50% máu, nhận thêm Tốc Độ Di Chuyển và tốc độ đánh lên chúng. Khi chúng còn dưới 25% máu, hắn hóa điên và các hiệu ứng được nhân ba.","Warwick được giảm sát thương gánh chịu trong 2.5 giây. Khi kết thúc, hoặc tái kích hoạt, hắn gầm thét, khiến kẻ địch gần đó bỏ chạy trong 1 giây.","Warwick nhảy xổ về một hướng (tỉ lệ với Tốc độ Di chuyển cộng thêm), áp chế kẻ địch đầu tiên nó chạm phải trong 1.5 giây."]],"wukong":["Ngộ Không là một chiến binh tinh quái người Vastayan biết tận dụng sức mạnh, sự nhanh nhẹn cũng như trí thông minh của mình để khiến đối phương hỗn loạn sau đó chiếm thế thượng phong. Sau khi tìm được một người bạn chí cốt, một chiến binh được biết đến với cái tên Master Yi, Ngộ Không trở thành môn sinh cuối cùng của môn võ truyền thống Wuju. Với cây gậy ma thuật trên tay, Ngộ Không mong có thể bảo vệ Ionia khỏi sự lụi tàn.",["Ngộ Không nhận cộng dồn, tăng giáp và hồi máu tối đa khi giao tranh với tướng cũng như quái vật.","Đòn đánh kế tiếp của Ngộ Không được tăng tầm, gây thêm sát thương và giảm giáp của mục tiêu trong vài giây.","Ngộ Không trở nên Vô Hinh và lướt về hướng chỉ định, để lại một phân thân tấn công kẻ địch gần đó.","Ngộ Không phóng tới kẻ địch chỉ định và ra lệnh cho phân thân tấn công kẻ địch gần mục tiêu, gây sát thương lên tất cả kẻ địch trúng chiêu.","Ngộ Không làm cho thiết bảng dài ra rồi múa nó quanh bản thân, nhận thêm Tốc độ Di chuyển.\nTất cả kẻ địch dính chiêu sẽ chịu sát thương và bị hất tung."]],"xayah":["Chuẩn xác đến chết người, Xayah là một nhà cách mạng vastaya đang đích thân tiến hành cuộc chiến để giải cứu bộ tộc. Cô sử dụng tốc độ, sự tinh quái, và bộ lông vũ sắc như dao để tiêu diệt mọi kẻ ngáng đường. Xayah chiến đấu cùng chiến hữu và cũng là chồng cô, Rakan, để bảo vệ chủng loài đang dần suy yếu của mình, và phục hồi vinh quang xưa cũ của họ.",["Sau khi dùng kỹ năng, các đòn đánh kế tiếp của Xayah sẽ đánh trúng tất cả mục tiêu trên đường bay và để lại Lông Vũ.","Xayah phi ra hai dao gây sát thương và để lại Lông Vũ trên đất.","Xayah tạo một cơn bão phi dao tăng Tốc Độ Đánh và sát thương, đồng thời cho cô Tốc Độ Di Chuyển nếu tấn công một tướng.","Xayah triệu hồi tất cả Lông Vũ rơi trên đất, gây sát thương và trói chân kẻ địch'","Xayah nhảy lên không, không thể bị chỉ định và quăng ra một loạt phi dao, để lại Lông Vũ trên mặt đất."]],"xerath":["Xerath là Pháp Sư Thăng Hoa của Shurima cổ đại, một thực thể năng lượng huyền bí bị giằng xé trong những mảnh vỡ của một cỗ quan tài ma thuật. Trong hàng thiên niên kỷ, hắn mắc kẹt dưới lớp cát, nhưng khi Shurima trỗi dậy, hắn được giải thoát. Bị sức mạnh làm cho điên loạn, giờ hắn tìm cách chiếm đoạt tất cả những gì hắn tin là của mình và thay thế những nền văn minh đang hiện diện trên thế giới bằng thứ hắn tưởng tượng ra.",["Đòn đánh thường của Xerath hồi Năng Lượng theo định kì. Mỗi khi Xerath kết liễu 1 đơn vị, hồi chiêu sẽ giảm đi.","Bắn một dải năng lượng tầm xa, gây sát thương phép lên tất cả mục tiêu trúng phải.","Tạo ra một vùng năng lượng thần bí gây sát thương phép và làm chậm các kẻ địch đứng trong đó. Mục tiêu ở tâm chịu thêm sát thương và làm chậm.","Gây sát thương phép lên một kẻ địch và làm choáng nạn nhân đó.","Xerath tự cố định vị trí của bản thân rồi nhận được nhiều lần công kích ma pháp trên diện rộng với tầm thi triển cực xa."]],"xinzhao":["Xin Zhao là một chiến binh cực kỳ trung thành với triều đại Lightshield. Từng bị đày vào trường đấu Noxus, anh đã sống sót qua hàng ngàn trận chiến. Sau khi được quân đội Demacia trả lại tự do, anh đã thề hiến dâng mạng sống và cả sự trung kiên của mình cho họ. Cầm trên tay cây thương ba mũi yêu thích, Xin Zhao giờ chiến đấu cho quê hương mới, sẵn sàng thách thức mọi đối thủ dù hùng mạnh đến đâu.",["Mỗi đòn đánh thứ ba gây thêm sát thương và hồi máu cho Xin Zhao.","Ba đòn đánh kế tiếp của Xin Zhao gây thêm sát thương. Đòn đánh thứ ba hất tung kẻ địch.","Xin Zhao dùng thương chém ra trước mặt, sau đó đâm tới, làm chậm kẻ địch bị trúng đòn và đánh dấu Thách Thức mục tiêu","Xin Zhao lao vào một kẻ địch, tăng cho bản thân Tốc Độ Đánh và gây sát thương lên tất cả kẻ địch xung quanh, thoáng làm chậm chúng. Kỹ Năng này được tăng thêm tầm lên mục tiêu bị Thách Thức.","Xin Zhao sẽ thách thức một kẻ địch mà anh ta vừa gây sát thương. Khi kích hoạt, Xin Zhao gây sát thương lên các kẻ địch gần đó dựa theo máu hiện tại của chúng và đẩy lùi những mục tiêu không bị thách đấu, trở nên miễn nhiễm sát thương từ các tướng đừng ngoài vòng tròn được tạo ra."]],"yasuo":["Một người Ionia đầy kiên định, chàng kiếm sĩ Yasuo được rèn luyện để sử dụng gió làm vũ khí tấn công kẻ thù. Khi còn trẻ, anh bị kết oan tội sát hại sư phụ - không thể chứng minh mình vô tội, anh buộc phải xuống tay với chính anh trai để tự vệ. Sau này, hung thủ thực sự đã lộ diện, nhưng Yasuo vẫn không thể tha thứ cho bản thân về những gì mình đã làm, và giờ lãng du khắp quê hương chỉ với ngọn gió dẫn đường.",["Tỉ lệ Chí mạng của Yasuo được gia tăng. Ngoài ra, Yasuo tích lá chắn mỗi khi di chuyển. Lá chắn kích hoạt khi anh chịu sát thương từ tướng hoặc quái.","Đâm tới, sát thương tất cả kẻ địch trên đường thẳng.\nKhi trúng, cho một cộng dồn Tụ Bão trong vài giây. Ở 2 cộng dồn, Bão Kiếm bắn ra lốc xoáy hất kẻ địch Lên Không.\nBão Kiếm được coi như đòn đánh thường.","Tạo tường gió chặn các luồng đạn của kẻ địch trong 4 giây.","Lướt xuyên qua mục tiêu, gây sát thương phép. Mỗi lần lướt sẽ tăng sát thương của lần lướt kế tiếp (có giới hạn tối đa).\nKhông thể dùng lên cùng một kẻ địch trong vài giây.\nNếu dùng Bão Kiếm khi đang lướt, nó sẽ tấn công theo hình tròn.","Dịch chuyển đến chỗ một tướng địch đang bị Hất Lên Không, gây sát thương vật lý và giữ tất cả những kẻ địch cùng bị Hất Lên Không ở xung quanh trên không thêm một chút. Hồi đầy thanh Nhịp nhưng xóa hết cộng dồn của Tụ Bão.\nTrong một khoảng thời gian sau đó, những đòn chí mạng của Yasuo sẽ nhận một lượng lớn Xuyên Giáp Cộng Thêm."]],"yone":["Trong cuộc đời trước kia, anh từng là Yone - người anh trai của Yasuo, và là môn đồ nổi tiếng của trường kiếm trong làng. Nhưng sau khi bị hạ sát bởi chính tay người em trai mình, anh đã bị săn đuổi bởi một thực thể tà ác nơi linh giới, và buộc phải hạ gục nó bằng chính lưỡi kiếm của nó. Giờ đây, bị nguyền rủa bởi chiếc mặt nạ gắn chặt lên khuôn mặt mình, Yone không ngừng săn đuổi lũ quỷ dữ nhằm tìm kiếm lời giải cho thứ mà anh đã trở thành.",["Yone gây sát thương phép ở mỗi đòn Tấn công thứ hai. Bên cạnh đó, tỉ lệ chí mạng cũng được tăng.","Đâm tới, gây sát thương lên tất cả kẻ địch trên một đường thẳng.\nKhi đánh trúng, tăng 1 điểm cộng dồn Tụ Bão trong vài giây. Khi đạt 2 cộng dồn, lần sử dụng Tử Kiếm tiếp theo sẽ giúp Yone lướt về phía trước cùng một cơn gió, Hất Tung kẻ địch.","Chém về phía trước, gây sát thương lên tất cả kẻ địch theo hình nón. Tạo một lớp lá chắn cho Yone và giá trị của lớp lá chắn này sẽ tăng lên dựa trên số tướng địch trúng chiêu.\nThời gian hồi và thời gian thi triển của Trảm Hồn sẽ tỉ lệ với tốc độ đánh.","Linh hồn của Yone rời khỏi thể xác phía sau và tăng Tốc Độ Di Chuyển. Khi kỹ năng kết thúc, linh hồn của Yone sẽ buộc phải quay trở lại và gây một lượng sát thương dựa trên lượng đã gây ra ở dạng linh hồn.","Yone dịch chuyển ra phía sau kẻ địch cuối cùng trên đường thẳng với một cú chém đoạt mệnh, đồng thời, kéo chúng về phía mình."]],"yorick":["Kẻ sống sót cuối cùng của một giáo phái đã bị quên lãng từ lâu, Yorick vừa được ban phước vừa bị nguyền rủa với quyền năng dẫn dắt những kẻ đã chết. Mắc kẹt trên Quần Đảo Bóng Đêm, bạn đồng hành duy nhất của hắn là những thi thể thối rữa và những hồn ma rú rít mà hắn thu thập được. Hành động đáng sợ của Yorick đã đi ngược hoàn toàn mục đích cao quý của hắn: giải phóng cho quê nhà khỏi lời nguyền Đại Suy Vong.",["Đoàn Quân Quỷ Ám: Yorick có thể triệu hồi Ma Sương ra tấn công các kẻ địch gần đó.","Yorick gây thêm sát thương trong đòn đánh kế tiếp và hồi máu lại cho hắn. Nếu mục tiêu là tướng hoặc quái lớn, hoặc nếu mục tiêu bị hạ gục, một nấm mộ sẽ mọc lên.","Yorick dựng lên bức tường có thể phá hủy ở vị trí chỉ định chặn đường di chuyển của kẻ địch.","Yorick ném ra một đám Sương Đen gây sát thương, giảm giáp, làm chậm và đánh dấu kẻ địch. Đơn vị được triệu hồi nhận thêm tốc độ di chuyển khi di chuyển hướng về phía các mục tiêu bị đánh dấu.","Yorick triệu hồi Thánh Nữ Sương Mù khiến các đòn đánh của Yorick lên mục tiêu của Thánh Nữ gây thêm sát thương. Thánh Nữ cũng tự động gọi Ma Sương từ các kẻ địch đã gục ngã."]],"yunara":["Với lòng trung thành tuyệt đối dành cho Ionia, Yunara đã dành hàng thế kỷ ẩn dật nơi linh giới để rèn luyện kỹ năng cùng Aion Er'na, một di vật huyền thoại của Kinkou. Bất chấp tất cả những gì mình đã hy sinh, lời thề của Yunara nhằm xóa bỏ bất hòa và xung đột trên mảnh đất này vẫn còn nguyên vẹn, giống như niềm tin của cô vậy. Nhưng thế giới đang chờ đợi cô lúc này - cùng với cái bóng của một mối hiểm họa cổ xưa vừa trỗi dậy - sẽ thử thách từng chút ý chí trong cô.",["Đòn Đánh Chí Mạng của Yunara gây thêm sát thương phép.","Yunara nhận Tốc Độ Đánh, sát thương cộng thêm Trên Đòn Đánh và Đòn Đánh sẽ lan sang các kẻ địch ở gần.","Yunara tung ra một chuỗi hạt nguyện xoay tròn gây sát thương và làm chậm kẻ địch. Khi đang ở trong Trạng Thái Siêu Phàm, thay vào đó cô bắn ra một luồng tia laser gây sát thương và làm chậm kẻ địch.","Yunara nhận Tốc Độ Di Chuyển và có thể Đi Xuyên Vật Thể. Khi ở trong trạng thái Siêu Phàm, thay vào đó cô sẽ lướt theo hướng chỉ định.","Yunara tiến vào Trạng Thái Siêu Phàm và các Kỹ Năng cơ bản của cô được nâng cấp."]],"yuumi":["Cô mèo ma thuật Yuumi từng là thú cưng của một huyền sư yordle tên Norra ở Thành Phố Bandle. Khi chủ nhân mất tích một cách đầy bí ẩn, Yuumi đồng hành cùng Cuốn Sách Ngưỡng Cửa tìm kiếm nữ chủ nhân qua các cổng dịch chuyển bên trong mỗi trang sách. Khao khát được yêu thương, Yuumi luôn tìm cách kết bạn trong suốt chuyến hành trình, bảo vệ họ bằng những lớp lá chắn sáng lung linh và quyết tâm cao độ. Dù Sách không ngừng giữ cô tập trung vào nhiệm vụ, Yuumi vẫn hay bị thu hút bởi những vui thú đời thường, như ngủ và cá. Tuy nhiên, cuối cùng cô sẽ tiếp tục sứ mệnh của mình thôi.",["Định kỳ, khi Yuumi đánh trúng tướng địch bằng đòn đánh hoặc kỹ năng, cô sẽ hồi máu cho bản thân và đồng minh tiếp theo mà cô Quấn Quýt cùng.\nKhi đang Quấn Quýt, Yuumi tạo một liên kết đặc biệt với đồng minh của cô. Đồng minh với liên kết mạnh mẽ nhất sẽ cường hóa các kỹ năng của Yuumi khi cô Quấn Quýt cùng họ.","Yuumi bắn ra một mũi tên, gây sát thương và làm chậm mục tiêu đầu tiên trúng phải. Sát thương và làm chậm sẽ được cường hóa nếu mất ít nhất 1,35 giây trước khi trúng vào mục tiêu. Khi đang bám theo Bạn Chí Cốt, hiệu ứng làm chậm sẽ luôn được cường hóa và cho đồng minh của cô sát thương Trên Đòn Đánh.\nKhi đang Quấn Quýt, mũi tên có thể được điều khiển bằng trỏ chuột trong thoáng chốc.","Yuumi lướt tới một đồng minh mục tiêu, trở nên không thể bị chỉ định bởi bất kỳ thứ gì ngoài trụ. Khi đang bám theo Bạn Chí Cốt, cô nhận thêm Sức Mạnh Hồi Máu & Tạo Lá Chắn, đồng thời cho Đồng Đội của cô hồi máu Trên Đòn Đánh.","Tạo lá chắn cho Yuumi và tăng Tốc Độ Di Chuyển & Tốc Độ Đánh. Nếu đang Quấn Quýt, cô chuyển hiệu ứng này cho đồng minh.","Yuumi bắn ra 5 đợt sóng gây sát thương lên kẻ địch và hồi máu cho đồng minh. Yuumi có thể di chuyển, Quấn Quýt và dùng Tăng Động khi đang vận. Khi đang bám trên Bạn Chí Cốt, kỹ năng này đồng thời hướng theo con trỏ chuột của cô."]],"zaahen":["Một vị thần sa ngã sở hữu cả quyền năng thiêng liêng lẫn sức mạnh hắc ám, Zaahen săn lùng những Darkin đồng loại trong khi chống lại sự tha hóa đang đe dọa nuốt chửng mình. Từng tự nguyện phong ấn bản thân trong thanh đại đao để giữ mình khỏi cơn điên loạn, giờ đây hắn đã tự do, mang trái tim cao thượng nhưng mục đích thì tàn bạo. Zaahen bị cuốn vào cuộc chiến vĩnh hằng trong tâm trí... nhưng chừng nào còn đứng vững, hắn sẽ vượt lên trên tất cả những kẻ muốn hủy diệt Runeterra.",["Đòn đánh và kỹ năng của Zaahen lên tướng địch sẽ cho hắn cộng dồn Quyết Đoán, giúp tăng Sức Mạnh Công Kích mỗi cộng dồn. Khi Quyết Đoán đã đầy, Zaahen nhận thêm Sức Mạnh Công Kích và có thể hồi sinh.","Zaahen chém 2 lần trên đòn đánh kế tiếp, gây thêm sát thương và hồi máu cho bản thân. Zaahen có thể tái kích hoạt kỹ năng này để khiến đòn đánh kế tiếp gây thêm sát thương và hất tung mục tiêu.","Zaahen đâm đao về một hướng, gây sát thương lên các kẻ địch trúng đòn, sau đó kéo chúng về phía hắn.","Zaahen lướt tới một vị trí và quét đao xung quanh bản thân.","Zaahen nhảy lên rồi đâm xuống, gây sát thương lên kẻ địch và hồi máu bằng một phần sát thương gây ra."]],"zac":["Zac là sản phẩm của một lần rò rỉ chất độc và nó đã thấm qua màng hóa-kỹ, đọng lại tại một hang động biệt lập sâu dưới Hầm Thấp Zaun. Dù mang xuất thân hèn mọn, Zac đã phát triển thành một thực thể biết suy nghĩ và hắn cư ngụ trong các đường ống của thành phố, thỉnh thoảng lộ mặt giúp đỡ những ai không thể tự cứu mình hoặc tái thiết cơ sở hạ tầng đã hỏng hóc của Zaun.",["Mỗi khi Zac công kích trúng một kẻ địch bằng kĩ năng của mình, hắn tự tách ra một mẩu của bản thân, thứ có thể tái hấp thu để được hồi Máu. Khi bị hạ gục, Zac tự tách ra làm 4 mảng tế bào, và chúng có thể hợp nhau trở lại. Nếu còn bất kì mảnh nào tồn tại sau 8 giây, hắn sẽ được tái sinh với lượng Máu dựa trên số Máu của các mảng tế bào còn sống. Mỗi mảng tế bào có một lượng phần trăm Máu tối đa của Zac, cũng như cả Giáp và Kháng Phép. Kĩ năng này có 5 phút thời gian hồi.","Zac duỗi dài tay, làm chậm và gây sát thương lên những kẻ địch cạnh bên.","Zac gây sát thương phép theo phần trăm máu tối đa của mục tiêu.","Zac gắn tay lên mặt đất rồi rút nhanh về, giúp hắn bắn về phía trước.","Zac nảy bốn lần, hất tung kẻ địch trúng phải và làm chậm chúng."]],"zed":["Tàn nhẫn và không khoan nhượng, Zed là thủ lĩnh Hội Bóng Tối, một tổ chức hắn sáng lập với ý đồ quân sự hóa võ thuật truyền thống Ionia nhằm đánh đuổi bọn Noxus xâm lược. Trong chiến tranh, hắn liều mạng mở khóa phân thân bóng tối - một thứ ma thuật mạnh mẽ nhưng không kém phần nguy hiểm và tha hóa. Zed đã làm chủ mọi cấm thuật để hủy diệt bất kỳ thứ gì hắn xem là hiểm họa cho quốc gia, hoặc cho Hội Bóng Tối.",["Đòn đánh cơ bản của Zed gây thêm Sát thương Phép lên kẻ địch thấp máu. Hiệu ứng này chỉ có thể xảy ra một lần mỗi vài giây lên tướng địch.","Zed cùng phân thân bóng tối xoáy kiếm về phía trước, gây sát thương lên các đơn vị bị kĩ năng bay xuyên qua.","Phân thân của Zed lướt tới trước rồi yên vị trong 5 giây, nó thể bắt chước các kĩ năng hắn tung ra. Zed có thể tái kích hoạt kĩ năng để đổi chỗ với phân thân.","Zed cùng Phân Thân xoáy lưỡi kiếm, bắn ra một luồng sóng năng lượng hắc ám. Sóng kiếm xoáy của phân thân gây hiệu ứng làm chậm. Những nạn nhân trúng phải Đường Kiếm Bóng Tối của phân thân sẽ bị làm chậm.","Zed để lại một cái bóng sau lưng rồi lướt tới tướng mục tiêu, khắc dấu ấn tử thần lên nạn nhân. Sau 3 giây, dấu ấn sẽ kích nổ, gây một số phần trăm sát thương Zed đã gây ra khi dấu ấn còn trong thời gian hiệu lực. Nếu tướng địch chết dưới tác dụng của Dấu Ấn Tử Thần, Zed có thể đánh cắp một phần Sức mạnh Công kích của nạn nhân."]],"zeri":["Là một cô gái trẻ cứng đầu thuộc tầng lớp lao động của Zaun, Zeri sử dụng ma thuật điện thiên bẩm để sạc năng lượng của chính mình cũng như khẩu súng được chế tác đặc biệt của cô. Nguồn năng lượng bất ổn ấy phản ảnh lên tâm trạng của cô, cùng những tia chớp đại diện cho cách sống vội vàng của cô. Đồng cảm sâu sắc với những người khác, Zeri mang theo tình yêu thương của gia đình và quê nhà vào trong mỗi trận chiến. Dù cho sự hăng hái của cô đôi khi phản tác dụng, nhưng Zeri luôn tin vào một chân lý bất di bất dịch: đứng lên vì cộng đồng, và họ sẽ đứng lên cùng bạn.",["Đòn Đánh của Zeri gây sát thương phép và được tính như một Kỹ Năng. Di chuyển và sử dụng Súng Điện Liên Hoàn sẽ tích trữ năng lượng cho Ba Lô Tụ Điện của Zeri. Khi sạc đầy, Đòn Đánh kế tiếp của cô sẽ gây thêm sát thương.","Súng Điện Liên Hoàn bắn ra một loạt 7 tia điện gây sát thương lên kẻ địch đầu tiên trúng phải. Kỹ Năng này được tính như một Đòn Đánh.","Zeri bắn ra một xung điện gây sát thương và làm chậm kẻ địch đầu tiên trúng chiêu. Nếu xung điện chạm vào một bức tường, nó sẽ mở rộng thành một luồng điện tầm xa.","Zeri lướt đi một quãng ngắn và cường hóa cho Súng Điện Liên Hoàn, khiến nó xuyên qua kẻ địch. Cô sẽ nhào lộn qua và lướt dọc theo bất kì địa hình nào mà mình chạm vào.","Zeri giải phóng một vụ nổ điện năng và khiến bản thân quá tải, tăng sát thương và Tốc Độ Di Chuyển cho bản thân. Hiệu ứng quá tải sẽ mạnh hơn mỗi khi cô tấn công tướng địch. Khi quá tải, Súng Điện Liên Hoàn sẽ trở thành một loạt ba tia điện được bắn ra nhanh hơn và phóng điện giữa các kẻ địch."]],"ziggs":["Với tình yêu hỏa pháo cùng bom, gã Yordle Ziggs là một kẻ đáng gờm. Khi làm trợ lý sáng chế ở Piltover, gã thấy nhàm chán trước cuộc sống dễ đoán ở đây và kết bạn với một bom thủ tóc xanh tên Jinx. Sau một đêm dài quậy phá trong thành phố, Ziggs nghe lời khuyên của cô và chuyển tới Zaun, nơi gã được tự do khám phá những gì mình đam mê, khủng bố cả các Hóa-Chủ lẫn thường dân trong hành trình vô tận tìm cách thổi tung mọi thứ của hắn.",["Theo chu kỳ, đòn đánh kế tiếp của Ziggs gây thêm sát thương phép. Hồi chiêu giảm mỗi khi Ziggs dùng một kỹ năng.","Ziggs quẳng ra một trái bom nảy gây sát thương phép.","Ziggs quẳng ra một khối chất nổ sẽ tự nổ sau một khoảng thời gian, hoặc khi kĩ năng được tái kích hoạt. Vụ nổ gây sát thương phép lên kẻ địch và hất văng chúng đi. Ziggs cũng bị hất văng, nhưng không chịu sát thương.\nZiggs có thể dùng Gói Chất Nổ để phá hủy trụ địch.","Ziggs rải ra những quả mìn sẽ phát nổ khi tiếp xúc với kẻ địch, gây sát thương phép và làm chậm nạn nhân. Nếu mục tiêu giẫm nhiều quả mìn, những quả từ thứ hai trở đi gây ít sát thương hơn.","Ziggs triển khai vũ khí tối thượng của mình, Siêu Bom Địa Ngục, rồi ném đi một khoảng cách cực xa. Những kẻ địch trong phạm vi vụ nổ chịu sát thương nhiều hơn những kẻ ở ngoài tầm tác động."]],"zilean":["Từng là một pháp sư Icathia hùng mạnh, Zilean trở nên ám ảnh về việc du hành thời gian sau khi chứng kiến quê hương bị Hư Không phá hủy. Không thể chịu đựng dù chỉ một phút mất mát thảm khốc đó, ông triệu gọi một luồng ma thuật cổ xưa để tiên đoán mọi khả năng có thể. Trở nên bất tử, giờ Zilean lướt qua quá khứ, hiện tại, và tương lai, bẻ cong và thay đổi dòng thời gian xung quanh ông, không ngừng tìm kiếm một khoảnh khắc có thể quay ngược tất cả và xóa bỏ sự hủy diệt của Icathia.",["Zilean tích trữ thời gian dưới dạng Kinh Nghiệm và có thể tăng nó cho đồng minh. Khi có đủ Kinh Nghiệm để lên cấp cho một đồng minh, ông có thể ấn phải vào tướng đó để bắt đầu quá trình. Zilean đồng thời nhận một lượng Kinh Nghiệm tương ứng.","Ném một quả bom vào vùng chỉ định, thứ sẽ bám dính lấy bất kì đơn vị nào dám lại gần nó (ưu tiên Tướng). Quả bom sẽ phát nổ sau 3 giây, gây sát thương ra xung quanh. Nếu Bom Hẹn Giờ được kích nổ sớm hơn bởi một quả Bom Hẹn Giờ khác, nó sẽ làm choáng các nạn nhân.","Zilean có thể chuẩn bị trước cho những bất trắc trong tương lai, giảm thời gian hồi chiêu các kĩ năng cơ bản của nó.","Zilean bẻ cong thời gian quanh một đơn vị, giảm tốc độ di chuyển nếu đó là kẻ địch và gia tăng nếu đó là đồng minh trong một thời gian ngắn.","Zilean ếm bùa bảo vệ lên tướng đồng minh, giúp hồi sinh nạn nhân nếu mục tiêu chẳng may bị hạ gục trong thời gian hiệu lực."]],"zoe":["Là hiện thân của sự tinh quái, trí tưởng tượng, và thay đổi, Zoe nắm giữ vai trò sứ giả vũ trụ của Targon, truyền bá những sự kiện trọng đại có thể thay đổi thế giới. Chỉ sự hiện diện của cô thôi đã đủ bẻ cong thực tại, đôi khi gây ra những biến cố vô tình. Có lẽ điều này giải thích cho thái độ thờ ơ với trách nhiệm của Zoe, cho cô thật nhiều thời gian tập trung chơi đùa, chơi khăm người thường, hoặc không thì tự giải khuây. Cuộc gặp gỡ Zoe có thể trở nên rất vui vẻ và tràn đầy sức sống, nhưng lúc nào nó cũng ẩn giấu nhiều thứ hơn vẻ ngoài và thường là cực kỳ nguy hiểm.",["Đòn đánh kế tiếp của Zoe sau khi tung chiêu gây thêm sát thương phép.","Zoe bắn ra một luồng phép có thể đổi hướng giữa chừng. Càng bay được nhiều càng gây thêm sát thương.","Zoe có thể nhặt lấy những mẩu Phép Bổ Trợ và trang bị kích hoạt của kẻ địch rồi tự mình dùng chúng một lần. Mỗi khi dùng một Phép Bổ Trợ, cô gọi ra ba luồng phép bắn vào mục tiêu gần nhất.","Khiến mục tiêu trở nên lơ mơ, rồi chìm vào giấc ngủ. Khi trong trạng thái ngủ, mục tiêu sẽ bị giảm Kháng Phép. Nguồn sát thương đầu tiên phá vỡ giấc ngủ sẽ được nhân đôi (với giới hạn tối đa nhất định).","Bay tới một vị trí gần đó trong 1 giây. Rồi bay trở về."]],"zyra":["Sinh ra từ một thảm họa ma thuật cổ xưa, Zyra là cơn thịnh nộ của tự nhiên thành hình - nửa người nửa thực vật, nhen nhóm những sự sống mới trên từng bước chân. Cô xem những kẻ phàm tục ở Valoran chỉ là con mồi cho đống hoạt giống của mình, và chẳng nghĩ gì khác ngoài việc tàn sát chúng với những chùm dây gai chết chóc. Dù ý định thực sự của cô chưa được tiết lộ, Zyra vẫn đi khắp thế giới, thỏa mãn những thôi thúc nguyên thủy nhất của mình là xâm chiếm và bóp nghẹt mọi sự sống khác khỏi nó.A",["Hạt giống sinh ra quanh Zyra theo chu kỳ, nhanh hơn mỗi khi Zyra lên cấp. Zyra có thể dùng Bó Gai Chết Chóc hoặc Rễ Cây Trói Buộc gần hạt giống để giúp chúng trưởng thành chiến đấu cho Zyra.","Zyra quẳng một bó gai vào vị trí đã chọn. Chỉ một lúc sau, nó sẽ phát nổ, bắn gai lên tất cả kẻ địch cạnh bên. Nếu niệm lên một hạt giống, Bó Gai Chết Chóc sẽ hóa thành Cây Phun Gai, bắn liên tục vào những kẻ địch từ xa.","Zyra đặt một hạt giống tồn tại 60 giây. Dùng Bó Gai Chết Chóc và Rễ Cây Trói Buộc gần hạt giống sẽ biến chúng thành cây chiến đấu cho Zyra. Zyra có thể tích trữ nhiều hạt giống một lúc, và hạ gục kẻ địch giảm thời gian sạc lại của Sum Sê.","Zyra phóng dây leo qua mặt đất để bắt giữ mục tiêu, gây sát thương phép và trói chân kẻ địch khi chúng đi qua. Nếu dùng chiêu gần hạt giống, Rễ Cây Trói Buộc biến thành Cây Quất Roi, có đòn đánh tầm xa làm chậm Tốc độ Di chuyển của địch.","Zyra gọi ra một bụi cây kì dị tại vị trí đã chọn, gây sát thương lên những kẻ địch lúc nó bành trướng ra rồi hất tung những nạn nhân trúng chiêu đi. Cây bên trong vùng tác dụng trở nên cuồng nộ."]]};
